const QUESTIONS = [
// ─── 공공조달 개요 ───
{id:"P1-001",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달의 정의 및 목적",ss:"1-1-1-1",tag:["개념","기초"],difficulty:"하",question:"공공조달에 관한 설명으로 가장 적절한 것은?",options:["민간기업 간 자유로운 상거래만을 의미한다","공공기관이 공공재정을 활용하여 물품·용역·공사 등을 구매하는 활동이다","정부 보조금 지급 절차를 의미한다","공공기관의 인사관리 절차를 의미한다"],answer:1,explanation:"공공조달은 공공기관이 공공재정으로 필요한 물품·용역·공사를 구매하는 활동입니다."},
{id:"P1-002",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달의 목적",ss:"1-1-1-2",tag:["개념","목적"],difficulty:"하",question:"공공조달의 목적과 가장 거리가 먼 것은?",options:["예산의 효율적 집행","공정한 거래 질서 확립","민간기업의 이윤 극대화","사회적 가치 실현"],answer:2,explanation:"민간기업의 이윤 극대화는 민간 기업의 목표이지 공공조달의 목적이 아닙니다."},
{id:"P1-003",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달의 기본 원칙",ss:"1-2-1-1",tag:["원칙"],difficulty:"중",question:"공공조달의 기본 원칙으로 보기 어려운 것은?",options:["공정성","투명성","효율성","수익성 극대화"],answer:3,explanation:"공공조달의 기본 원칙은 공정성·투명성·효율성·경쟁성 등입니다. 수익성 극대화는 민간 목표입니다."},
{id:"P1-004",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"수요기관",ss:"1-1-2-1",tag:["주체"],difficulty:"하",question:"공공조달에서 '수요기관'에 해당하는 설명으로 옳은 것은?",options:["물품·용역·공사 계약이 필요한 공공기관","입찰에 참가하는 민간업체","조달계약을 체결하는 조달청","조달업무 감독기관"],answer:0,explanation:"수요기관은 물품·용역·공사 등의 계약 또는 시설물 관리가 필요한 공공기관입니다."},
{id:"P1-005",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"조달청의 역할",ss:"1-1-4-1",tag:["주체"],difficulty:"중",question:"조달사업법령상 조달청의 역할로 옳지 않은 것은?",options:["수요기관을 대신하여 계약 체결","물자의 비축 및 공급","입찰 참가업체의 영업 지도","조달물자의 품질 관리"],answer:2,explanation:"조달청은 계약·비축·품질관리를 담당하나 업체의 영업 지도 기능은 없습니다."},
{id:"P1-006",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달 절차",ss:"1-1-3-2",tag:["절차","기초"],difficulty:"중",question:"공공조달 절차의 일반적 순서로 가장 적절한 것은?",options:["계약체결 → 입찰공고 → 낙찰자 결정 → 검사","수요 발생 → 예산 확보 → 입찰공고 → 계약체결 → 검사","입찰공고 → 계약체결 → 예산 확보 → 검사","검사 → 계약체결 → 입찰공고 → 수요 발생"],answer:1,explanation:"수요 발생 → 예산 확보 → 발주문서 작성 → 계약방법 결정 → 공고 → 입찰·평가 → 낙찰 → 계약체결 → 이행 → 검사 → 지급 순입니다."},
{id:"P1-007",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"감독 책임",ss:"1-1-4-2",tag:["주체"],difficulty:"중",question:"공공조달의 구성체계 중 감독 및 관리적 책임에 해당하는 것은?",options:["감사원의 조달 감사","수요기관의 구매 집행","공급업체의 납품 이행","조달청의 계약 체결"],answer:0,explanation:"감사원의 조달 감사는 공공조달의 감독·관리적 책임 영역입니다. 국회, 감사원, 각 조달기관 감사부서 등이 관리감독 체계를 이룹니다."},
{id:"P1-008",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"추정가격",ss:"1-5-2-1",tag:["기초","숫자"],difficulty:"중",question:"국가계약법령상 추정가격 산정의 기준이 되는 금액은?",options:["부가가치세를 포함한 금액","부가가치세를 제외한 금액","낙찰가격","계약금액"],answer:1,explanation:"추정가격은 부가세를 제외한 예상 금액으로 계약 방법 결정 기준입니다.",basis:"조달청 내자구매업무 처리규정 제11조 제1항; 국가계약법 시행규칙 제2조 제2호",basisUrl:"https://www.law.go.kr/행정규칙/조달청내자구매업무처리규정"},
{id:"P1-009",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"예산 용어",ss:"1-5-2-1",tag:["회계","개념"],difficulty:"하",question:"'예산 항목에 금액을 올려 잡는 것'을 가리키는 회계 용어는?",options:["계상","책정","산정","정산"],answer:0,explanation:"계상(計上)은 예산에 금액을 올려 잡는 것을 의미합니다."},
{id:"P1-010",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"예산 용어",ss:"1-5-2-1",tag:["회계","개념"],difficulty:"하",question:"'금액·기준을 결정하는 것'을 가리키는 용어는?",options:["계상","책정","산정","정산"],answer:1,explanation:"책정(策定)은 금액·기준을 결정하는 것입니다."},
{id:"P1-011",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"예산 용어",ss:"1-5-2-1",tag:["회계","개념"],difficulty:"하",question:"'계산해서 금액을 도출하는 것'을 의미하는 용어는?",options:["계상","책정","산정","정산"],answer:2,explanation:"산정(算定)은 계산해서 금액을 도출하는 것입니다."},
{id:"P1-012",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달 범위",ss:"1-1-1-3",tag:["개념"],difficulty:"중",question:"공공조달의 범위에 포함되지 않는 것은?",options:["물품 구매","용역 위탁","공사 발주","민간기업 인수합병"],answer:3,explanation:"공공조달은 물품·용역·공사 구매가 대상이며, 민간기업 인수합병은 해당하지 않습니다."},
{id:"P1-013",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달과 민간거래 차이",ss:"1-1-3-1",tag:["비교"],difficulty:"중",question:"공공조달이 민간 상거래와 다른 특성으로 옳지 않은 것은?",options:["엄격한 법령상 절차 준수","경쟁성·공정성·투명성 요구","공공재정의 효율적 집행 의무","당사자의 자유로운 계약 의사 무제한 보장"],answer:3,explanation:"공공계약은 민간과 달리 법령상 절차와 공익 의무에 구속됩니다."},
{id:"P1-014",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달과 사회적가치",ss:"1-4-4-5",tag:["전략"],difficulty:"중",question:"공공조달에서 ESG와 가장 관련이 깊은 조달 유형은?",options:["최저가 입찰","수의계약","전략적 공공조달","지명경쟁입찰"],answer:2,explanation:"ESG(환경·사회·지배구조)는 전략적 공공조달과 연계되어 사회적가치·녹색조달 등에 반영됩니다."},
{id:"P1-015",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"생애주기비용",ss:"1-4-2-3",tag:["개념"],difficulty:"상",question:"생애주기비용(LCC)을 고려한 공공조달에 관한 설명으로 옳지 않은 것은?",options:["구매가격뿐 아니라 유지보수·처분 비용까지 고려한다","초기 구매가격이 낮아도 총비용이 높을 수 있다","환경적 지속가능성과 연관된 개념이다","최저가 낙찰제와 동일한 개념이다"],answer:3,explanation:"LCC는 전 과정 비용을 고려하는 개념으로 단순 최저가와 다릅니다."},
// ─── 공공조달 원칙 및 방법 ───
{id:"P1-016",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"일반경쟁입찰",ss:"1-2-3-1",tag:["입찰방식"],difficulty:"하",question:"일반경쟁입찰에 관한 설명으로 옳은 것은?",options:["발주기관이 특정 업체를 지명하여 경쟁시킨다","자격을 갖춘 불특정 다수가 자유롭게 참가할 수 있다","참가자격을 지역·실적 등으로 제한한다","경쟁 없이 특정 상대방과 계약한다"],answer:1,explanation:"일반경쟁입찰은 자격을 갖춘 불특정 다수가 참가하는 방식으로 공정성·투명성이 가장 높습니다."},
{id:"P1-017",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"제한경쟁",ss:"1-2-3-2",tag:["입찰방식"],difficulty:"하",question:"제한경쟁입찰에 관한 설명으로 옳은 것은?",options:["참가자격을 일정 조건(지역·실적·규모)으로 제한한다","무제한 자유참가 입찰이다","발주기관이 특정 업체를 지정한다","경쟁 없는 직접 계약이다"],answer:0,explanation:"제한경쟁입찰은 자격을 일정 조건으로 제한하는 경쟁입찰입니다."},
{id:"P1-018",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"지명경쟁",ss:"1-2-3-3",tag:["입찰방식"],difficulty:"중",question:"지명경쟁입찰을 적용할 수 있는 경우가 아닌 것은?",options:["계약의 성질상 특수한 설비가 필요한 경우","소수 업체만 제조·공급 가능한 경우","긴급한 필요로 특정 업체가 필요한 경우","추정가격이 고액인 일반 물품 구매"],answer:3,explanation:"지명경쟁은 시행령 제23조①에 열거된 경우(특수한 설비·기술이 필요하고 대상자가 적은 경우, 소액 공사·물품, KS 인증 제품, 수의계약을 할 수 있는 경우 등)에만 할 수 있습니다. 단순히 금액이 큰 일반 물품 구매는 여기에 해당하지 않아 일반경쟁이 원칙입니다.",basis:"국가계약법 시행령 제23조 제1항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제23조"},
{id:"P1-019",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"수의계약",ss:"1-2-4-1",tag:["입찰방식"],difficulty:"하",question:"수의계약의 장점과 가장 거리가 먼 것은?",options:["절차 간소화","신속한 계약 체결","공정성 및 투명성 확보","조달기관에 적합한 대상물 확보 가능성 향상"],answer:2,explanation:"수의계약은 신속·간소가 장점이며, 공정성·투명성은 오히려 단점으로 지적됩니다."},
{id:"P1-020",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"수의계약 사유",ss:"1-5-5-3",tag:["입찰방식"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙에서 수의계약이 가능한 경우가 아닌 것은?",options:["천재지변으로 긴급한 필요가 있는 경우","추정가격이 일정 금액 미만인 소액 계약","2인 이상 입찰자가 있어 경쟁이 가능한 경우","특허권 등으로 특정인만 공급 가능한 경우"],answer:2,explanation:"경쟁이 가능한 경우는 수의계약 사유가 아닙니다. 경쟁입찰 원칙을 따라야 합니다."},
{id:"P1-021",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"수의계약 기준금액",ss:"1-2-4-2",tag:["숫자"],difficulty:"중",question:"물품·용역 소액수의계약이 가능한 추정가격 기준은?",options:["1천만원 미만","2천만원 이하","3천만원 미만","5천만원 미만"],answer:1,explanation:"물품·용역 소액수의계약은 추정가격 2천만원 이하에서 가능합니다.",basis:"국가계약법 시행령 제26조 제1항 제5호 가목 2)",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제26조"},
{id:"P1-022",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"수의계약 기준금액",ss:"1-2-4-2",tag:["숫자"],difficulty:"중",question:"국가계약법령상 「건설산업기본법」에 따른 종합공사의 소액수의계약 추정가격 기준은?",options:["2천만원 이하","4억원 이하","2억원 이하","1억원 이하"],answer:1,explanation:"건설산업기본법상 종합공사는 추정가격 4억원 이하, 전문공사는 2억원 이하, 기타 공사는 1억6천만원 이하에서 소액수의계약이 가능합니다. 물품·용역은 2천만원 이하입니다.",basis:"국가계약법 시행령 제26조 제1항 제5호 가목 1)",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제26조"},
{id:"P1-023",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"경쟁입찰 원칙",ss:"1-2-3-1",tag:["원칙"],difficulty:"중",question:"공공조달에서 일반경쟁입찰을 원칙으로 하는 가장 중요한 이유는?",options:["계약 비용 절감","공정·투명한 경쟁 환경 확보","발주기관의 행정 편의","낙찰 결정 시간 단축"],answer:1,explanation:"일반경쟁은 공정성·투명성을 가장 잘 확보할 수 있어 기본 원칙으로 채택됩니다."},
{id:"P1-024",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"수의계약 방법",ss:"1-5-4-3",tag:["입찰방식"],difficulty:"중",question:"전자공개수의계약에 관한 설명으로 옳지 않은 것은?",options:["나라장터를 통해 공개적으로 진행한다","수의계약 투명성 제고가 목적이다","모든 수의계약에 의무 적용된다","견적서를 전자적으로 제출받는다"],answer:2,explanation:"전자공개수의계약은 일정 금액 이상의 수의계약에 적용되며 모든 수의계약 의무가 아닙니다."},
{id:"P1-025",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"입찰방식 비교",ss:"1-2-3-1",tag:["비교"],difficulty:"중",question:"다음 입찰방식 중 공정성·투명성이 가장 높은 방식은?",options:["수의계약","지명경쟁입찰","제한경쟁입찰","일반경쟁입찰"],answer:3,explanation:"불특정 다수가 자유롭게 참가하는 일반경쟁이 공정성·투명성이 가장 높습니다."},
{id:"P1-026",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"계약체결방식",ss:"1-5-2-2",tag:["방식"],difficulty:"중",question:"협상에 의한 계약이 주로 활용되는 분야로 가장 적절한 것은?",options:["단순 물품 구매","일반 시설 공사","전문 용역 및 IT 개발","소액 수의계약"],answer:2,explanation:"협상계약은 기술능력이 중요한 전문용역·IT 개발·컨설팅 등에 주로 활용됩니다."},
{id:"P1-027",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"평등·기회균등",ss:"1-2-1-1",tag:["원칙"],difficulty:"중",question:"공공조달의 경쟁성 원칙과 가장 관련 깊은 것은?",options:["입찰참가자의 기회 균등 보장","발주기관의 일방적 결정권","특정 업체 우대","계약담당자의 재량 확대"],answer:0,explanation:"경쟁성 원칙은 모든 잠재 참가자에게 동일한 기회를 보장하는 것입니다."},
{id:"P1-028",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"계약체결의 기본",ss:"1-5-2-4",tag:["원칙"],difficulty:"중",question:"국가계약법령상 계약서를 작성하는 경우 계약이 확정되는 시점으로 옳은 것은?",options:["입찰공고일","낙찰자 결정일","담당 공무원과 계약상대자가 계약서에 기명·날인하거나 서명한 때","대금 지급일"],answer:2,explanation:"계약서를 작성하는 경우 담당 공무원과 계약상대자가 계약서에 기명·날인하거나 서명함으로써 계약이 확정됩니다.",basis:"국가계약법 제11조 제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제11조"},
{id:"P1-029",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"경쟁입찰 자격",ss:"2-2-1-1",tag:["절차"],difficulty:"중",question:"경쟁입찰 참가자격 등록에 관한 설명으로 옳지 않은 것은?",options:["나라장터에 온라인으로 등록한다","업종별 등록 요건이 다를 수 있다","한 번 등록하면 영구적으로 유효하다","세부 품명을 추가 등록할 수 있다"],answer:2,explanation:"입찰참가자격 등록은 유효기간이 있으며 갱신해야 합니다."},
{id:"P1-030",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"입찰방식 종합",ss:"1-2-3-3",tag:["종합"],difficulty:"상",question:"다음 중 공공조달 입찰방식과 그 특징의 짝이 잘못된 것은?",options:["일반경쟁 - 불특정 다수 참가, 공정성 가장 높음","제한경쟁 - 자격 조건 제한, 경쟁성 유지","지명경쟁 - 발주자가 지정, 절대적 다수 참가","수의계약 - 경쟁 없이 직접 계약, 절차 간소"],answer:2,explanation:"지명경쟁은 특정 업체를 지명하여 경쟁시키는 방식으로 다수 참가가 아닌 소수 참가입니다."},
// ─── 전자조달시스템 ───
{id:"P1-031",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"나라장터",ss:"1-3-1-1",tag:["전자조달","시스템"],difficulty:"하",question:"나라장터(국가종합전자조달시스템)에 관한 설명으로 옳지 않은 것은?",options:["전자입찰·전자계약 기능을 제공한다","조달청이 운영·관리한다","민간기업은 공급자로 등록할 수 없다","종합쇼핑몰 서비스를 포함한다"],answer:2,explanation:"나라장터는 민간기업도 공급자로 등록하여 입찰과 쇼핑몰 납품이 가능합니다."},
{id:"P1-032",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"종합쇼핑몰",ss:"1-3-2-1",tag:["전자조달"],difficulty:"중",question:"나라장터 종합쇼핑몰에 관한 설명으로 옳은 것은?",options:["민간 일반인이 자유롭게 구매하는 쇼핑몰이다","수요기관이 조달청 단가계약(다수공급자계약·일반 단가계약 등) 물품을 온라인으로 구매하는 시스템이다","해외 물품 직구를 지원하는 플랫폼이다","입찰만 진행되고 구매는 불가능하다"],answer:1,explanation:"종합쇼핑몰은 수요기관이 조달청이 맺은 단가계약(다수공급자계약·제3자단가계약 등) 물품을 온라인으로 납품요구해 구매하는 시스템입니다."},
{id:"P1-033",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"혁신장터",ss:"1-3-2-2",tag:["전자조달"],difficulty:"중",question:"혁신장터에 관한 설명으로 옳은 것은?",options:["일반 물품 구매 전용 플랫폼이다","혁신제품 조달을 위한 나라장터 연계 시스템이다","입찰만 진행되는 별도 시스템이다","민간기업 전용 쇼핑몰이다"],answer:1,explanation:"혁신장터는 혁신제품 지정 후 수의계약이 가능한 나라장터 연계 시스템입니다."},
{id:"P1-034",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자조달 성과",ss:"1-3-1-6",tag:["전자조달"],difficulty:"중",question:"전자조달시스템 도입 성과로 보기 어려운 것은?",options:["조달 업무의 투명성 향상","입찰 비용 및 시간 절감","담합 가능성의 완전한 차단","조달 정보 접근성 향상"],answer:2,explanation:"전자조달 도입으로 담합 가능성이 감소했으나 완전히 차단할 수는 없습니다."},
{id:"P1-035",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"디지털서비스몰",ss:"1-3-2-4",tag:["전자조달"],difficulty:"중",question:"디지털서비스몰 활용 계약에 관한 설명으로 옳은 것은?",options:["물리적 물품 구매에 활용된다","소프트웨어·클라우드 등 디지털 서비스 구매에 활용된다","수의계약이 불가능하다","나라장터와 완전히 별개의 시스템이다"],answer:1,explanation:"디지털서비스몰은 소프트웨어·클라우드 등 디지털 서비스를 공공기관이 구매하는 플랫폼입니다."},
{id:"P1-036",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자입찰",ss:"1-3-1-5",tag:["전자조달","입찰"],difficulty:"중",question:"전자입찰의 특성으로 옳지 않은 것은?",options:["전자서명을 통해 입찰서를 제출한다","전자서명 인증서(공동인증서 등)가 필요하다","입찰서 위·변조 방지가 가능하다","오프라인 입찰보다 절차가 복잡하다"],answer:3,explanation:"전자입찰은 오프라인 대비 절차가 단순하고 신속하며 위변조 방지에도 유리합니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 제11조",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률/제11조"},
{id:"P1-037",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"목록정보시스템",ss:"1-3-3-2",tag:["전자조달"],difficulty:"상",question:"목록정보시스템(나라장터 연계)의 주요 기능이 아닌 것은?",options:["물품 품명·품목 등록 및 관리","물품목록 분류 체계 운영","입찰 참가업체 신용평가","국제 표준분류체계 연계"],answer:2,explanation:"목록정보시스템은 물품 분류·관리 기능을 담당하며 신용평가는 별도 기관 소관입니다."},
{id:"P1-039",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"벤처나라",ss:"1-3-2-3",tag:["전자조달"],difficulty:"중",question:"벤처나라 활용 계약에 관한 설명으로 옳은 것은?",options:["대기업 제품 구매 시스템이다","창업·벤처기업 제품의 공공 판로 개척을 지원하는 나라장터 연계 쇼핑몰이다","나라장터와 별개의 독립 시스템이다","수의계약이 불가능하다"],answer:1,explanation:"벤처나라는 창업·벤처기업의 판로 개척을 돕기 위해 조달사업법에 따라 만든 쇼핑몰로, 나라장터와 연계해 공공기관이 추정가격 2천만원 이하 제품을 바로주문·견적주문으로 살 수 있습니다."},
{id:"P1-040",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"이음장터",ss:"1-3-2-5",tag:["전자조달"],difficulty:"중",question:"이음장터에 관한 설명으로 옳은 것은?",options:["대기업 전용 조달 플랫폼이다","장애인기업 제품 전용 플랫폼이다","지역 중소기업 간 B2B 거래 플랫폼이다","공공기관과 용역(서비스) 공급업체가 가격·조건을 직접 협의해 소액 용역을 거래하는 플랫폼이다"],answer:3,explanation:"이음장터는 2022년 조달청이 용역(서비스) 거래를 활성화하려고 만든 전용 플랫폼으로, 수요기관과 용역 공급업체가 협상을 거쳐 추정가격 2천만원 이하 용역을 직접 거래합니다."},
// ─── 전략적 공공조달 ───
{id:"P1-041",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달",ss:"1-4-2-2",tag:["전략","녹색"],difficulty:"하",question:"녹색제품 우선구매제도에 관한 설명으로 옳지 않은 것은?",options:["공공기관은 녹색제품을 우선 구매할 의무가 있다","환경표지 인증제품이 해당된다","구매 실적은 매년 기후에너지환경부장관에게 제출해야 한다","민간기업도 반드시 녹색제품만 구매해야 한다"],answer:3,explanation:"녹색제품 우선구매 의무는 공공기관에만 적용되며 민간기업에는 강제되지 않습니다.",basis:"녹색제품 구매촉진에 관한 법률 제9조 제1항",basisUrl:"https://www.law.go.kr/법령/녹색제품구매촉진에관한법률/제9조"},
{id:"P1-042",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달 인증",ss:"1-4-2-2",tag:["전략","녹색"],difficulty:"중",question:"녹색제품에 해당하는 인증으로 옳지 않은 것은?",options:["환경표지","우수재활용제품(GR)","저탄소제품","KS 인증"],answer:3,explanation:"KS 인증은 산업표준 인증으로 녹색제품 인증과는 별개입니다."},
{id:"P1-043",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"중소기업자간 경쟁",ss:"1-4-1-2",tag:["전략","중기"],difficulty:"중",question:"중소기업자간 경쟁제도에 관한 설명으로 옳지 않은 것은?",options:["특정 품목을 중소기업만 입찰 참가 가능하도록 지정한다","중소기업 보호를 위한 제도이다","대기업도 예외적으로 참가가 가능하다","조달청장이 품목을 지정한다"],answer:3,explanation:"경쟁제품은 중소벤처기업부장관이 지정하므로 \"조달청장이 지정\"은 틀립니다(판로지원법 제6조①). 공공기관은 특별한 사유가 없으면 중소기업자간 경쟁으로 계약해야 하지만, 유찰 등 시행령이 정한 사유가 있으면 다른 입찰 방법으로 살 수 있어 대기업이 참가하는 경우도 있습니다(제7조①, 시행령 제7조①).",basis:"판로지원법 제6조 제1항, 제7조 제1항, 같은 법 시행령 제7조 제1항",basisUrl:"https://www.law.go.kr/법령/중소기업제품구매촉진및판로지원에관한법률/제6조"},
{id:"P1-044",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"우수조달물품",ss:"1-4-3-2",tag:["전략"],difficulty:"중",question:"우수조달물품 지정제도에 관한 설명으로 옳은 것은?",options:["모든 공공기관이 의무 구매해야 한다","조달청장이 품질·기술력 우수 제품을 지정한다","지정 제품은 수의계약을 할 수 없다","민간기업은 지정 신청이 불가능하다"],answer:1,explanation:"조달청장이 품질·기술력 우수 제품을 지정해 수의계약 등 우선구매 혜택을 부여합니다."},
{id:"P1-045",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"공사용자재 직접구매",ss:"1-4-1-3",tag:["전략","중기"],difficulty:"상",question:"공사용자재 직접구매제도에 관한 설명으로 옳은 것은?",options:["원도급자가 모든 자재를 직접 구매해야 한다","공공기관이 공사에 필요한 중소기업 경쟁제품 자재를 직접 구매해 시공사에 제공하는 제도이다","하도급을 장려하기 위한 제도이다","대기업 자재 납품업체 보호 제도이다"],answer:1,explanation:"일정 규모 이상 공사를 발주하는 공공기관이 중소벤처기업부장관이 정한 공사용 자재(중소기업 경쟁제품)를 직접 구매해 공급하는 제도로, 중소기업 제품 구매를 늘리는 것이 목적입니다.",basis:"판로지원법 제12조",basisUrl:"https://www.law.go.kr/법령/중소기업제품구매촉진및판로지원에관한법률/제12조"},
{id:"P1-046",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"혁신제품",ss:"1-4-3-3",tag:["전략","혁신"],difficulty:"중",question:"혁신제품 지정제도에 관한 설명으로 옳지 않은 것은?",options:["혁신성이 인정된 제품을 조달청이 지정한다","지정 제품은 수의계약으로 구매 가능하다","혁신장터를 통해 거래된다","지정 기간은 영구적이다"],answer:3,explanation:"혁신제품 지정은 통상 3년 한시적이며 영구가 아닙니다."},
{id:"P1-047",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"사회적기업 우선구매",ss:"1-4-4-4",tag:["전략","사회"],difficulty:"중",question:"사회적기업 우선구매제도에 관한 설명으로 옳지 않은 것은?",options:["공공기관은 사회적기업 제품을 우선 구매할 수 있다","사회적가치 실현의 일환이다","사회적기업 인증을 받아야 혜택이 적용된다","사회적기업은 영리를 추구해서는 안 된다"],answer:3,explanation:"사회적기업은 사회적 목적과 함께 영리 활동도 병행할 수 있습니다."},
{id:"P1-048",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"중증장애인생산품",ss:"1-4-4-2",tag:["전략","사회"],difficulty:"중",question:"중증장애인생산품 우선구매제도에 관한 설명으로 옳은 것은?",options:["일반 장애인 기업 제품 구매를 장려하는 제도이다","보건복지부장관이 지정한 중증장애인생산품 생산시설의 제품을 공공기관이 우선 구매하는 제도이다","구매 실적 보고 의무가 없다","민간기업에도 구매 의무가 부과된다"],answer:1,explanation:"중증장애인생산품은 장애인 직업재활시설·장애인복지단체·재활훈련시설 중 보건복지부장관이 지정한 생산시설의 제품·서비스이고, 공공기관은 이를 우선 구매해야 합니다.",basis:"중증장애인생산품 우선구매 특별법 제2조 제2항",basisUrl:"https://www.law.go.kr/법령/중증장애인생산품우선구매특별법/제2조"},
{id:"P1-049",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"여성기업 우선구매",ss:"1-4-4-3",tag:["전략","사회"],difficulty:"중",question:"여성기업 우선구매제도에 관한 설명으로 옳지 않은 것은?",options:["여성기업인이 운영하는 기업 제품을 우선 구매한다","공공기관의 의무 구매 비율이 정해져 있다","여성기업 확인서를 발급받아야 혜택 적용이 가능하다","민간기업에도 동일한 의무가 부과된다"],answer:3,explanation:"여성기업 우선구매 의무는 공공기관에만 적용됩니다."},
{id:"P1-050",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"ESG 조달",ss:"1-4-4-5",tag:["전략","ESG"],difficulty:"상",question:"ESG 기반 공공조달에서 가장 중요하게 고려되는 요소가 아닌 것은?",options:["환경(E)적 영향","사회(S)적 가치","지배구조(G) 투명성","최저가 절대 우선"],answer:3,explanation:"ESG 조달은 환경·사회·지배구조를 중시하며 단순 최저가 원칙과 다릅니다."},
{id:"P1-051",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달 보고",ss:"1-4-2-2",tag:["전략","녹색"],difficulty:"중",question:"녹색제품 구매 실적 보고에 관한 설명으로 옳은 것은?",options:["보고 의무가 없다","공공기관은 매년 기후에너지환경부장관에게 제출해야 한다","민간기업도 보고 의무가 있다","조달청장에게만 보고하면 된다"],answer:1,explanation:"공공기관의 장은 녹색제품 구매실적을 매 회계연도가 끝난 후 3개월 이내에 기후에너지환경부장관에게 제출해야 합니다.",basis:"녹색제품 구매촉진에 관한 법률 제9조 제1항",basisUrl:"https://www.law.go.kr/법령/녹색제품구매촉진에관한법률/제9조"},
{id:"P1-052",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"우수발명품",ss:"1-4-3-1",tag:["전략","혁신"],difficulty:"상",question:"우수발명품 우선구매제도의 주요 목적으로 옳은 것은?",options:["대기업 기술 개발 지원","우수 기술 보유 중소기업·발명자 지원 및 판로 개척","외국 제품 수입 촉진","공공기관 행정비용 절감"],answer:1,explanation:"우수발명품 우선구매는 기술 우수 중소기업과 발명자를 지원하고 판로를 개척하기 위한 제도입니다."},
{id:"P1-053",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"MAS 개요",ss:"3-3-2-2",tag:["MAS"],difficulty:"중",question:"다수공급자계약(MAS) 제도에 관한 설명으로 옳은 것은?",options:["최저가 업체와만 단일 계약을 체결한다","품질·가격이 적정한 다수 공급자와 미리 계약하고 수요기관이 선택 구매한다","경쟁 없이 임의 업체를 선정한다","종합쇼핑몰과는 별개의 시스템이다"],answer:1,explanation:"MAS는 다수 공급자와 미리 계약한 후 수요기관이 종합쇼핑몰에서 선택 구매하는 방식입니다."},
{id:"P1-054",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"카탈로그계약",ss:"3-3-2-6",tag:["MAS"],difficulty:"중",question:"카탈로그계약에 관한 설명으로 옳은 것은?",options:["카탈로그 계약업체에게 제안서를 받아 평가·협상한 결과로 납품업체를 정한다","대형 공사 계약에 주로 활용된다","계약상대자는 반드시 1인으로 정한다","일반경쟁입찰의 일종이다"],answer:0,explanation:"조달청이 카탈로그 제시업체를 심사해 원칙적으로 2인 이상과 계약하고, 수요기관은 그 업체들에게 제안서를 받아 평가·협상한 결과로 납품업체를 정합니다. 디지털서비스 등 일부는 1인과 계약할 수도 있습니다.",basis:"조달사업법 시행령 제16조",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률시행령/제16조"},
{id:"P1-055",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달 범위",ss:"1-4-2-1",tag:["전략","녹색"],difficulty:"중",question:"공공조달에서 녹색조달의 범위에 해당하지 않는 것은?",options:["환경표지 인증제품 구매","우수재활용제품(GR) 구매","유해화학물질 함유 제품 구매","에너지절약·효율 1등급 제품 구매"],answer:2,explanation:"유해화학물질 함유 제품은 녹색조달과 정반대 방향으로 회피 대상입니다."},
{id:"P1-056",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"중기간 경쟁 직접생산",ss:"1-4-1-2",tag:["전략","중기"],difficulty:"중",question:"직접생산확인기준 검토의 목적으로 옳은 것은?",options:["납품 업체의 영업이익을 보장하기 위해","중소기업이 직접 생산한 제품임을 확인하기 위해","대기업 제품 품질 검증을 위해","해외 수입 제품 통관 지원을 위해"],answer:1,explanation:"직접생산확인은 중소기업자간 경쟁제도의 실효성을 확보하기 위한 절차입니다."},
{id:"P1-057",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"전략적 조달 정의",ss:"1-4-4-5",tag:["전략","개념"],difficulty:"중",question:"전략적 공공조달의 핵심 개념으로 옳지 않은 것은?",options:["사회적 가치 실현 도구로서의 조달","경제·산업 정책 수단으로서의 조달","환경 지속가능성 추구 수단","오로지 최저가 낙찰만을 추구"],answer:3,explanation:"전략적 공공조달은 단순 최저가가 아닌 사회·환경·산업적 가치를 함께 추구합니다."},
{id:"P1-058",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"중소기업 보호",ss:"1-4-1-1",tag:["전략","중기"],difficulty:"중",question:"중소기업제품 구매촉진 및 판로지원에 관한 법률의 주요 내용으로 옳지 않은 것은?",options:["공공기관의 중소기업제품 구매 비율 의무화","중소기업자간 경쟁제품 지정 제도 운영","공공기관의 중소기업제품 구매계획·실적 제출","대기업 제품 우선구매 의무화"],answer:3,explanation:"이 법은 중소기업 제품 구매를 촉진하기 위한 것으로 대기업 우선구매와는 반대입니다."},
{id:"P1-059",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"MAS 2단계경쟁",ss:"3-3-2-4",tag:["MAS"],difficulty:"중",question:"다수공급자계약(MAS) 2단계경쟁에 관한 설명으로 옳지 않은 것은?",options:["수요기관이 MAS 계약업체를 대상으로 추가 경쟁을 실시한다","가격·납품조건 등을 비교해 구매업체를 선정한다","어떠한 예외도 없이 반드시 2단계경쟁을 거쳐야 한다","재해복구 등 긴급 시 예외가 인정될 수 있다"],answer:2,explanation:"긴급·재해복구 등 사유로 2단계경쟁 예외가 인정됩니다."},
{id:"P1-060",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달 의무비율",ss:"1-4-2-2",tag:["전략","녹색"],difficulty:"상",question:"녹색제품 우선구매제도에서 공공기관의 의무에 해당하지 않는 것은?",options:["연간 녹색제품 구매계획 수립","녹색제품 우선 구매 노력","구매 실적의 정기적 보고","민간 협력업체의 녹색제품 사용 강제"],answer:3,explanation:"민간 협력업체에 녹색제품 사용을 강제할 수 있는 법적 의무는 없습니다."},
// ─── 공공조달법률 이해 ───
{id:"P1-061",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"국가계약법",ss:"1-1-1-3",tag:["법령","기초"],difficulty:"하",question:"국가를 당사자로 하는 계약에 관한 법률(국가계약법)의 적용 대상으로 옳은 것은?",options:["국가가 일방 당사자인 계약","민간기업 간 모든 계약","개인 간 사적 거래","공공기관 내부 인사관리"],answer:0,explanation:"국가계약법은 국가가 당사자가 되는 계약에 적용되는 법률입니다."},
{id:"P1-062",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"지방계약법",ss:"1-1-1-3",tag:["법령"],difficulty:"중",question:"지방자치단체를 당사자로 하는 계약에 관한 법률(지방계약법)의 적용 대상으로 가장 적절한 것은?",options:["국가기관이 체결하는 계약","지방자치단체가 체결하는 계약","공기업이 체결하는 모든 계약","개인 간 계약"],answer:1,explanation:"지방계약법은 지방자치단체가 당사자가 되는 계약에 적용됩니다."},
{id:"P1-063",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 적용",ss:"1-5-1-1",tag:["법령","민법"],difficulty:"중",question:"공공계약에서 민법이 적용되는 경우로 옳은 것은?",options:["국가계약법령에 특별한 규정이 있는 사항","국가계약법령에 특별한 규정이 없는 사항","입찰공고 전 단계만","계약 종결 후 분쟁 단계만"],answer:1,explanation:"공공계약은 국가계약법령 우선 적용하되 특별 규정이 없는 사항은 민법을 보충적으로 적용합니다."},
{id:"P1-064",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 도급",ss:"1-5-1-4",tag:["법령","민법"],difficulty:"중",question:"민법상 도급계약에 관한 설명으로 옳지 않은 것은?",options:["수급인이 일의 완성을 약정하는 계약이다","도급인은 완성된 결과에 보수를 지급한다","수급인은 완성 전에도 보수를 청구할 수 있다","공사·용역계약의 기본 형태이다"],answer:2,explanation:"도급계약에서 보수는 원칙적으로 일의 완성 후 지급하며, 완성 전 보수 청구는 원칙적으로 불가합니다."},
{id:"P1-065",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 해제·해지",ss:"1-5-1-3",tag:["법령","민법"],difficulty:"중",question:"당사자 일방의 의사표시에 의하여 유효하게 성립된 계약의 효력을 장래에 대하여 소멸시키는 행위는?",options:["해제","해지","철회","취소"],answer:1,explanation:"해지는 유효한 계약을 장래에 향해 소멸시킵니다. 해제는 소급효가 있어 처음부터 없던 것으로 만듭니다."},
{id:"P1-066",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 해제 소급효",ss:"1-5-1-3",tag:["법령","민법"],difficulty:"중",question:"계약 해제 시 원상회복 의무에 관한 설명으로 옳은 것은?",options:["해제 시 이미 이행된 부분의 반환 의무가 없다","소급효가 있어 이미 이행된 부분도 원상회복해야 한다","해제는 장래에 향해서만 효력이 있다","손해배상 청구가 불가능하다"],answer:1,explanation:"계약 해제는 소급효가 있어 이미 이행된 부분도 원상회복해야 합니다."},
{id:"P1-067",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 취소",ss:"1-5-1-2",tag:["법령","민법"],difficulty:"중",question:"계약의 취소에 관한 설명으로 옳은 것은?",options:["유효한 계약의 효력을 장래에 향해 소멸시키는 것이다","하자 있는 의사표시를 처음부터 없었던 것으로 만드는 것이다","의사표시 도달 전 번복하는 것이다","계약 당사자 합의로만 가능하다"],answer:1,explanation:"취소는 사기·강박·착오 등 하자 있는 의사표시를 소급적으로 무효화하는 것입니다."},
{id:"P1-068",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 동시이행항변권",ss:"1-5-1-2",tag:["법령","민법"],difficulty:"상",question:"민법상 동시이행의 항변권에 관한 설명으로 옳은 것은?",options:["상대방이 채무를 이행할 때까지 자신의 채무 이행을 거절할 수 있는 권리","일방적 계약에서만 인정된다","항변권 행사 시 계약이 자동 해제된다","반드시 손해배상 책임이 발생한다"],answer:0,explanation:"동시이행의 항변권은 쌍무계약에서 상대방 이행 시까지 자신의 이행을 거절할 수 있는 권리입니다."},
{id:"P1-069",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"건설산업기본법",ss:"3-4-3-5",tag:["법령","공사"],difficulty:"중",question:"건설산업기본법상 1건 공사의 금액이 ( ) 미만인 건설공사를 도급받은 경우 종합공사를 시공하는 업종을 등록한 건설사업자에게 하도급할 수 없다. ( )에 들어갈 값은?",options:["10억원","20억원","30억원","50억원"],answer:0,explanation:"1건 공사금액 10억원 미만인 건설공사는 종합공사업 등록 건설사업자에게 하도급할 수 없습니다(건설산업기본법 제29조④, 2018.12.31 신설)."},
{id:"P1-070",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"건설산업기본법 - 하도급",ss:"3-4-3-5",tag:["법령","공사"],difficulty:"중",question:"건설산업기본법상 건설공사 하도급에 관한 설명으로 옳지 않은 것은?",options:["수급인은 원칙적으로 도급받은 건설공사의 전부를 하도급할 수 없다","공사 일부를 하도급한 건설사업자는 원칙적으로 발주자에게 그 사실을 통보해야 한다","하수급인은 하도급받은 공사를 원칙적으로 다시 하도급할 수 있다","하도급계약금액이 일정 비율에 미달하면 발주자가 적정성을 심사한다"],answer:2,explanation:"재하도급은 원칙적으로 금지되고, 법이 정한 예외(발주자·수급인의 서면 승낙 등)에서만 허용됩니다(제29조③). 일부 하도급은 발주자에게 통보하는 것이 원칙이고(제29조⑥), 하도급금액이 일정 비율에 못 미치면 발주자가 적정성을 심사합니다(제31조①).",basis:"건설산업기본법 제29조, 제31조",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제29조"},
{id:"P1-071",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"중기간 경쟁법",ss:"1-4-1-1",tag:["법령","중기"],difficulty:"중",question:"중소기업제품 구매촉진 및 판로지원에 관한 법률의 주요 목적으로 가장 적절한 것은?",options:["대기업의 경쟁력 강화","중소기업 제품의 구매 촉진 및 판로 지원","공공기관의 비용 절감","외국기업 진출 지원"],answer:1,explanation:"이 법은 중소기업 제품 구매 촉진과 판로 지원을 목적으로 합니다."},
{id:"P1-072",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"전자조달법",ss:"1-3-1-3",tag:["법령","전자조달"],difficulty:"중",question:"전자조달의 이용 및 촉진에 관한 법률의 주요 내용으로 옳지 않은 것은?",options:["나라장터를 통한 전자입찰·전자계약 의무화","전자조달 표준화 추진","전자조달 보안성 확보","민간 모든 거래에 전자조달 강제 적용"],answer:3,explanation:"전자조달법은 공공조달 영역에 적용되며 민간 모든 거래에 강제되는 것은 아닙니다."},
{id:"P1-073",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"조달사업법",ss:"1-5-3-1",tag:["법령"],difficulty:"중",question:"조달사업에 관한 법률의 주요 내용으로 옳지 않은 것은?",options:["조달청의 조달업무 수행 근거","수요기관 대신 계약 체결 가능","조달물자 비축·관리","민간기업 영업 지도 의무"],answer:3,explanation:"조달사업법은 조달청의 업무 근거이며, 민간기업 영업 지도 의무는 포함하지 않습니다."},
{id:"P1-074",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"법령 우선순위",ss:"1-5-1-1",tag:["법령"],difficulty:"상",question:"공공계약 관련 법령 적용의 일반 원칙으로 옳은 것은?",options:["민법이 가장 우선 적용된다","국가계약법령 등 특별법이 민법보다 우선 적용된다","상법이 항상 우선 적용된다","계약 당사자가 적용 법령을 임의로 선택한다"],answer:1,explanation:"특별법인 국가계약법령이 우선 적용되고 특별 규정이 없는 사항은 민법을 보충 적용합니다."},
{id:"P1-075",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"공기업·준정부기관",ss:"1-1-1-3",tag:["법령"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙의 적용 대상으로 옳은 것은?",options:["국가기관 모든 계약","지방자치단체 계약","공기업과 준정부기관의 계약","민간기업 간 계약"],answer:2,explanation:"이 규칙은 공기업과 준정부기관이 당사자인 계약에 적용됩니다."},
// ─── 공정조달 관리 ───
{id:"P1-076",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"부정당업자 제재",ss:"1-6-2-2",tag:["공정조달"],difficulty:"중",question:"국가계약법령상 부정당업자 제재에 관한 설명으로 옳지 않은 것은?",options:["입찰담합에 참여한 업체는 부정당업자로 제재할 수 있다","제재 처분을 받은 업체는 일정 기간 입찰 참가가 제한된다","부정당업자 제재 기간은 최대 2년이다","허위서류를 제출한 업체는 제재 대상에서 제외된다"],answer:3,explanation:"허위서류 제출은 부정당업자 제재 사유에 포함됩니다."},
{id:"P1-077",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"부정당업자 사유",ss:"1-6-2-2",tag:["공정조달"],difficulty:"중",question:"부정당업자 제재 사유에 해당하지 않는 것은?",options:["입찰 담합","입찰 방해","허위 서류 제출","정당한 가격 인하 요청"],answer:3,explanation:"정당한 가격 인하 요청은 제재 사유가 아닙니다."},
{id:"P1-078",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"공정거래법 연계",ss:"1-6-2-3",tag:["공정조달"],difficulty:"상",question:"입찰담합에 대한 제재 관련 설명으로 옳지 않은 것은?",options:["국가계약법령에 따른 부정당업자 제재","공정거래법에 따른 과징금 부과","형법상 입찰방해죄 적용 가능","담합 참여 업체 모두에 대해 자동 면책"],answer:3,explanation:"담합 참여 업체는 자동 면책되지 않으며 다양한 법적 제재 대상이 됩니다."},
{id:"P1-079",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"청렴계약제",ss:"1-6-2-3",tag:["공정조달"],difficulty:"중",question:"공공조달 청렴계약제의 주요 내용으로 옳지 않은 것은?",options:["계약 당사자 간 청렴 서약","청탁·뇌물 금지","위반 시 계약 해지 등 제재","계약담당자 개인의 자율적 판단에 위임"],answer:3,explanation:"청렴계약제는 명시적 서약·규정에 따른 강제 사항이며 개인 자율에 맡기지 않습니다."},
{id:"P1-080",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"이해충돌 방지",ss:"2-3-2-2",tag:["공정조달"],difficulty:"중",question:"낙찰자 선정 과정에서 이해충돌이 발생한 평가위원의 조치로 옳은 것은?",options:["계속 평가에 참여한다","평가에서 회피한다","다른 위원과 상의하여 결정한다","발주기관장의 지시를 따른다"],answer:1,explanation:"이해충돌이 있는 평가위원은 반드시 회피해야 합니다."},
{id:"P1-081",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"분쟁조정",ss:"1-6-1-1",tag:["공정조달"],difficulty:"중",question:"공공조달 분쟁조정에 관한 설명으로 옳지 않은 것은?",options:["국가계약분쟁조정위원회에서 조정한다","조정은 소송을 먼저 제기한 뒤에만 신청할 수 있다","조정 결정에 이의가 있으면 소송을 제기할 수 있다","분쟁조정은 소송보다 신속하게 처리된다"],answer:1,explanation:"조정(재심) 청구는 이의신청 결과에 이의가 있는 입찰자·계약상대자 등이 소송과 별도로 할 수 있는 절차라서, 소송을 먼저 낼 필요가 없습니다(법 제28조④). 조정 완료 후 15일 이내에 이의를 제기하면 소송으로 다툴 수 있습니다(제31조③).",basis:"국가계약법 제28조 제4항, 제31조 제3항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제28조"},
{id:"P1-082",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"분쟁해결 방법",ss:"1-6-1-1",tag:["공정조달"],difficulty:"중",question:"공공계약 분쟁해결 방법 중 소송보다 빠르고 비용이 적게 드는 것은?",options:["형사고소","민사소송","조정·중재","행정소송"],answer:2,explanation:"조정·중재는 소송보다 신속하고 비용이 적게 드는 분쟁해결 방법입니다."},
{id:"P1-083",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"청탁금지법",ss:"1-6-2-3",tag:["공정조달"],difficulty:"중",question:"청탁금지법(김영란법)의 공공조달 적용에 관한 설명으로 옳지 않은 것은?",options:["공직자 등에 대한 부정청탁 금지","공직자 등의 금품 등 수수 금지","공공조달 담당자도 적용 대상","민간기업 직원에게는 적용되지 않는다"],answer:3,explanation:"청탁금지법은 공직자 등을 대상으로 하지만, 그들에게 청탁·금품을 제공하는 자도 처벌 대상입니다."},
{id:"P1-084",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"이해충돌방지법",ss:"1-6-2-3",tag:["공정조달"],difficulty:"상",question:"공직자의 이해충돌 방지법의 주요 내용으로 옳지 않은 것은?",options:["직무 관련 사적 이해관계 신고 의무","직무 관련자와의 거래 신고 의무","직무관련자인 퇴직자와의 사적 접촉 신고","민간기업 임직원에게 전면 적용"],answer:3,explanation:"이해충돌방지법은 공직자 등을 대상으로 하며 민간기업 임직원에게 전면 적용되지 않습니다. 퇴직 후 취업 제한은 공직자윤리법의 내용입니다.",basis:"공직자의 이해충돌 방지법 제5조, 제9조, 제15조",basisUrl:"https://www.law.go.kr/법령/공직자의이해충돌방지법"},
{id:"P1-085",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"투명성 제도",ss:"1-2-1-2",tag:["공정조달"],difficulty:"중",question:"공공조달의 투명성 확보를 위한 제도로 보기 어려운 것은?",options:["전자입찰 시스템 도입","입찰 결과 공개","담합 업체에 대한 부정당업자 제재","최저가 낙찰 강제 적용"],answer:3,explanation:"최저가 낙찰 강제는 투명성과 직접적인 관련이 적은 가격 경쟁 방법론입니다."},
{id:"P1-086",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"평가위원 사전접촉 금지",ss:"2-3-2-3",tag:["공정조달"],difficulty:"중",question:"제안서 평가위원 사전접촉 금지 규정의 주요 목적은?",options:["평가위원 업무 부담 감소","공정한 평가 환경 확보","입찰 기간 단축","발주기관의 행정 편의"],answer:1,explanation:"평가위원 사전접촉 금지는 특정 업체의 부당한 영향력을 차단하여 공정한 평가를 보장하기 위함입니다."},
{id:"P1-087",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"하도급지킴이",ss:"1-5-4-4",tag:["공정조달","공사"],difficulty:"중",question:"하도급지킴이 시스템에 관한 설명으로 옳지 않은 것은?",options:["하도급대금 지급 여부를 전자적으로 관리한다","발주자가 하수급인에게 직접 지급하는 시스템이다","하도급 분쟁 예방에 기여한다","하수급인 보호 목적"],answer:1,explanation:"하도급지킴이는 하도급대금의 청구·승인·지급을 전용계좌로 전자 처리하는 대금지급시스템이며, 발주자가 하수급인에게 대금을 직접 지급하는 제도(직불)와는 다릅니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 제9조의2",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률/제9조의2"},
{id:"P1-088",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"공정조달 신고",ss:"1-6-2-3",tag:["공정조달"],difficulty:"중",question:"공공조달 관련 비리 신고에 대한 설명으로 옳지 않은 것은?",options:["신고자 비밀 보장","신고자 보호 조치","공익신고자에 대한 포상","신고자 신원 공개 의무"],answer:3,explanation:"신고자의 신원은 비밀로 보장되며 공개 의무는 없습니다."},
{id:"P1-089",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"부정당업자 효과",ss:"1-6-1-4",tag:["공정조달"],difficulty:"상",question:"부정당업자 제재 처분의 효과로 옳지 않은 것은?",options:["일정 기간 입찰 참가 제한","모든 공공기관에 효력","제재 기간 중 신규 계약 체결 제한","제재 결정 즉시 기존 계약도 자동 무효"],answer:3,explanation:"부정당업자 제재가 기존 계약을 자동 무효로 만들지 않습니다."},
{id:"P1-090",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"공정조달 종합",ss:"1-5-3-4",tag:["공정조달","종합"],difficulty:"상",question:"공공조달의 공정성 확보를 위한 제도적 장치로 옳지 않은 것은?",options:["전자조달시스템 의무 사용","평가위원 사전접촉 금지","청렴계약제 운영","낙찰자의 자율적 가격 결정 보장"],answer:3,explanation:"낙찰자가 자율적으로 가격을 결정하는 것은 공정성 확보 장치라기보다 입찰 방식의 일부 특성입니다."},
// ─── 공공조달계획 ───
{id:"P2-001",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"수요분석",ss:"2-1-1-1",tag:["계획","수요"],difficulty:"하",question:"공공조달계획 수립 시 수요정보 분석에 포함되는 사항으로 옳은 것은?",options:["공급업체 대표자의 개인 정보","경쟁업체의 내부 영업기밀","공급 대상물의 특성·예상 수요량·수요 발생 시기","발주기관 직원의 인사 자료"],answer:2,explanation:"수요정보 분석은 공급 대상물 특성, 예상 수요량, 수요 발생 시기 등을 포함합니다."},
{id:"P2-002",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"공급역량분석",ss:"2-1-2-4",tag:["계획","공급"],difficulty:"중",question:"공급역량분석에서 검토 사항이 아닌 것은?",options:["공급업체의 생산능력","대표자의 개인 학력 및 경력","납품 실적 및 경험","재무 안정성"],answer:1,explanation:"공급역량분석은 생산능력·실적·재무 안정성 등이 핵심이며 대표자 개인 학력은 평가 사항이 아닙니다."},
{id:"P2-003",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"비상공급",ss:"2-1-1-4",tag:["계획","리스크"],difficulty:"중",question:"공공조달 계획에서 비상 공급계획 수립이 필요한 상황은?",options:["정상적인 조달이 가능한 경우","천재지변·공급 중단 등 비상 상황 대비","납품 가격이 하락하는 경우","입찰 경쟁이 치열한 경우"],answer:1,explanation:"비상 공급계획은 천재지변·공급망 붕괴 등 비상 상황에 대비한 대체 공급 방안입니다."},
{id:"P2-004",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"리스크 관리",ss:"2-1-4-3",tag:["계획","리스크"],difficulty:"중",question:"공공조달 리스크 관리 우선순위 결정 기준으로 옳은 것은?",options:["발생 가능성만 고려","영향도만 고려","담당자 경험에만 의존","발생 가능성과 영향도를 모두 고려"],answer:3,explanation:"리스크 관리 우선순위는 발생 가능성(확률)과 영향도(심각도)를 함께 고려해야 합니다."},
{id:"P2-005",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"공급 리스크",ss:"2-1-4-3",tag:["계획","리스크"],difficulty:"중",question:"공급 리스크 유형으로 보기 어려운 것은?",options:["단일 공급업체 의존 리스크","원자재 가격 급등 리스크","발주기관 직원의 퇴직","납기 지연 리스크"],answer:2,explanation:"발주기관 직원 퇴직은 공급 리스크와 직접 관련이 없습니다."},
{id:"P2-006",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"시장 분석",ss:"2-1-2-3",tag:["계획","분석"],difficulty:"중",question:"공공조달 시장 분석의 목적으로 옳지 않은 것은?",options:["공무원 인사 현황 파악","적정 공급 가격 파악","공급 가능 업체 현황 파악","경쟁 강도 분석"],answer:0,explanation:"공무원 인사 현황은 조달시장 분석과 무관합니다."},
// ─── 조달요구 응대 및 제안 ───
{id:"P2-007",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"제안서 작성",ss:"3-3-1-2",tag:["제안서"],difficulty:"중",question:"제안서 작성 시 가장 우선시해야 할 사항은?",options:["제안요청서(RFP)의 요구사항 충족","제안서 디자인의 화려함","경쟁업체 비방","발주기관 담당자 개인 친밀도 강조"],answer:0,explanation:"제안서는 제안요청서(RFP)의 요구사항을 빠짐없이 충족하는 것이 최우선입니다."},
{id:"P2-008",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"제안서 구성",ss:"3-3-1-2",tag:["제안서"],difficulty:"중",question:"기술제안서 구성 요소로 가장 적절한 것은?",options:["경쟁사 약점 분석 자료","수행방법·투입인력·유사실적·일정계획","발주기관 내부 정보","개인 친분 자료"],answer:1,explanation:"기술제안서는 수행방법, 투입인력, 유사실적, 일정계획 등을 포함합니다."},
{id:"P2-009",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"행정예고 검색",ss:"2-2-1-3",tag:["분석"],difficulty:"중",question:"조달 관련 입법·행정예고 검색의 목적으로 옳은 것은?",options:["낙찰 가격을 미리 예측","법령 및 제도 변경에 대비하여 사전에 의견을 제출","경쟁 업체 정보 수집","발주기관 담당자 정보 파악"],answer:1,explanation:"행정예고 검색은 법령·규정 변경을 사전 파악하고 의견을 제출하기 위한 것입니다."},
{id:"P2-010",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"공급 의사결정",ss:"2-1-3-1",tag:["제안"],difficulty:"중",question:"공급 의사결정을 위한 비용 분석 시 고려할 비용이 아닌 것은?",options:["직접 구매 비용","발주기관 직원의 개인 생활비","조달 행정 비용","물류 및 보관 비용"],answer:1,explanation:"직원 개인 생활비는 공급 의사결정 비용 분석 항목이 아닙니다."},
{id:"P2-011",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"입찰 참가 결정",ss:"2-2-3-2",tag:["전략"],difficulty:"중",question:"입찰 참가 의사결정 시 검토해야 할 핵심 사항으로 거리가 먼 것은?",options:["과업 수행 능력 보유 여부","발주기관 임원 출신 학교","수익성 분석","경쟁 강도 평가"],answer:1,explanation:"발주기관 임원 출신 학교는 입찰 참가 결정 기준이 아닙니다."},
{id:"P2-012",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"전략적 가격 결정",ss:"2-1-3-2",tag:["전략"],difficulty:"상",question:"공공입찰 가격 결정 전략으로 옳지 않은 것은?",options:["원가 분석을 통한 적정가격 산정","적격심사 통과 가능 가격 검토","경쟁사 동향 분석","담합을 통한 가격 조정"],answer:3,explanation:"담합은 불법이며 입찰 가격 전략이 아닙니다."},
// ─── 사전규격공개 분석 ───
{id:"P2-013",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"사전규격공개 개요",ss:"2-2-2-3",tag:["사전규격"],difficulty:"하",question:"사전규격공개에 관한 설명으로 옳지 않은 것은?",options:["입찰 전 규격(과업내용)을 공개하는 제도","특정 업체에 유리한 규격 설정 방지가 목적","공개된 규격에 대해 의견을 제출할 수 있다","금액 규모에 관계없이 모든 입찰에 의무 실시"],answer:3,explanation:"국가계약에서 구매규격 사전공개는 물품·용역 경쟁입찰이 대상이고(공사는 이 조항의 대상이 아님), 해당 연도에 이미 1회 이상 공개한 물품·용역은 생략할 수 있어 \"모든 입찰에 의무\"는 틀립니다.",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제77조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/정부입찰ㆍ계약집행기준"},
{id:"P2-014",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"공개 기간",ss:"2-2-2-3",tag:["사전규격","숫자"],difficulty:"하",question:"정부 입찰·계약 집행기준상 물품·용역 구매규격 사전공개의 원칙적인 공개 기간은?",options:["1일","7일","5일","10일"],answer:2,explanation:"구매규격 사전공개는 원칙적으로 5일간 전자조달시스템(나라장터)에 공개합니다. 긴급한 경우에는 3일간으로 줄일 수 있습니다.",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제77조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/정부입찰ㆍ계약집행기준"},
{id:"P2-015",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"규격 검토",ss:"2-2-2-1",tag:["사전규격"],difficulty:"중",question:"사전규격공개 시 응찰자가 검토해야 할 핵심 사항으로 옳은 것은?",options:["발주기관 담당자 인적사항","경쟁사 영업기밀","과업 수행 가능 여부 및 특정 업체 유리 조항 확인","계약 후 사후 변경 가능성"],answer:2,explanation:"사전규격공개는 과업 수행 가능 여부와 특정 업체 유리 조항 확인이 핵심입니다."},
{id:"P2-016",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"의견 처리",ss:"2-2-2-4",tag:["사전규격"],difficulty:"중",question:"사전규격공개 의견 제출에 대한 발주기관의 대응으로 옳은 것은?",options:["의견을 무조건 무시한다","의견 제출자를 입찰에서 배제한다","의견을 비공개로 처리한다","합리적 의견은 반영하여 규격을 수정할 수 있다"],answer:3,explanation:"합리적 의견은 반영하여 규격을 수정·보완할 수 있습니다."},
{id:"P2-017",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"독소조항",ss:"2-2-2-3",tag:["사전규격"],difficulty:"상",question:"사전규격공개에서 발견할 수 있는 '특정업체 유리 조항' 예시로 옳은 것은?",options:["특정 브랜드·모델명을 직접 명시한 규격","일반적인 KS 인증 요구","공인된 시험성적서 요구","납품 실적의 합리적 요구"],answer:0,explanation:"특정 브랜드·모델명을 직접 명시한 규격은 대표적인 특정업체 유리 조항입니다."},
{id:"P2-018",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"공개 매체",ss:"2-2-2-3",tag:["사전규격"],difficulty:"중",question:"사전규격공개는 어디에 공개해야 하는가?",options:["발주기관 자체 게시판","나라장터","해당 업체에만 개별 송부","민간 신문"],answer:1,explanation:"사전규격공개는 나라장터를 통해 공개해야 합니다."},
// ─── 입찰공고문 분석 ───
{id:"P2-019",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 명시사항",ss:"2-2-3-2",tag:["공고"],difficulty:"중",question:"국가를 당사자로 하는 계약에 관한 법령상 입찰공고 명시 사항이 아닌 것은?",options:["계약 조건 공시 장소","입찰 비리 신고 사항","계약의 중간보고일","입찰보증금 국고귀속 사항"],answer:2,explanation:"중간보고일은 입찰공고 명시 사항이 아닙니다."},
{id:"P2-020",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 기간",ss:"2-2-3-2",tag:["공고","숫자"],difficulty:"하",question:"국가계약법 시행령상 입찰공고는 원칙적으로 입찰서 제출마감일 전일부터 기산하여 며칠 전에 해야 하는가?",options:["7일","3일","1일","10일"],answer:0,explanation:"입찰공고는 입찰서 제출마감일 전일부터 기산해 7일 전에 하는 것이 원칙입니다. 재공고입찰이나 긴급한 경우 등은 5일 전까지 공고할 수 있습니다(제35조④). 공사는 규모별로 더 긴 기간이 적용됩니다(제35조③).",basis:"국가계약법 시행령 제35조 제1항·제4항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제35조"},
{id:"P2-021",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 분석",ss:"2-2-3-2",tag:["공고"],difficulty:"중",question:"입찰공고문에서 가장 먼저 확인해야 할 사항으로 옳은 것은?",options:["발주기관 담당자 이름","공고일 날씨","입찰참가자격 충족 여부","공고 글씨 크기"],answer:2,explanation:"입찰참가자격을 먼저 확인해야 입찰 참여 자체가 가능합니다."},
{id:"P2-022",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"입찰설명회",ss:"2-2-4-1",tag:["공고"],difficulty:"중",question:"입찰설명회에 관한 설명으로 옳지 않은 것은?",options:["발주기관이 입찰참가자에게 과업 내용을 설명한다","입찰 준비에 필요한 정보를 식별하는 기회이다","업체는 궁금한 사항을 질의할 수 있다","설명회에 참가한 업체만 입찰할 수 있는 것이 법령상 원칙이다"],answer:3,explanation:"설명회 참가는 법령이 정한 입찰 참가 요건이 아닙니다. 다만 공고문에 설명회(현장설명) 참가를 조건으로 정할 수 있으므로, 공고문의 참가자격 사항을 꼭 확인해야 합니다.",basis:"국가계약법 시행령 제14조의2, 제36조 제3호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제36조"},
{id:"P2-023",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"긴급공고",ss:"2-2-3-2",tag:["공고"],difficulty:"상",question:"긴급공고의 특성으로 옳은 것은?",options:["통상 공고기간보다 단축된 기간으로 공고된다","공고기간이 더 길어진다","공고 절차가 생략된다","수의계약과 동일하다"],answer:0,explanation:"긴급공고는 천재지변 등 사유로 통상 공고기간보다 짧은 기간으로 진행됩니다."},
{id:"P2-024",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"국제입찰 공고",ss:"2-2-3-2",tag:["공고","숫자"],difficulty:"상",question:"특정조달(GPA 대상) 입찰공고 기간을 긴급 사유와 전자조달 이용에 따른 단축을 함께 적용하여 줄이더라도, 그 공고기간은 최소 며칠 이상이어야 하는가?",options:["5일","7일","10일","25일"],answer:2,explanation:"원칙 40일에서 긴급 사유(10일 이전 공고)와 전자조달 이용 단축(5일씩)을 함께 적용해도 공고기간은 10일 미만으로 줄일 수 없습니다.",basis:"특정조달을 위한 국가를 당사자로 하는 계약에 관한 법률 시행령 특례규정 제11조 제3항~제5항",basisUrl:"https://www.law.go.kr/법령/특정조달을위한국가를당사자로하는계약에관한법률시행령특례규정/제11조"},
// ─── 입찰서 제출 및 개찰 ───
{id:"P2-025",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"입찰보증금",ss:"2-2-3-3",tag:["입찰","숫자"],difficulty:"하",question:"입찰보증금에 관한 설명으로 옳은 것은?",options:["입찰금액의 5% 이상 납부, 낙찰 후 미계약 시 국고 귀속","입찰금액의 10% 이상 납부","전자입찰의 경우 납부 면제","현금으로만 납부 가능"],answer:0,explanation:"입찰보증금은 입찰금액의 5% 이상이며 낙찰 후 미계약 시 국고에 귀속됩니다.",basis:"국가계약법 시행령 제37조 제1항; 국가계약법 제9조 제3항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제37조"},
{id:"P2-026",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"무효입찰",ss:"2-2-5-2",tag:["입찰"],difficulty:"중",question:"다음 중 무효입찰 사유에 해당하는 것은?",options:["위임장을 지참한 대리인의 입찰","동일인이 2개 이상의 입찰서를 제출","입찰 금액을 아라비아 숫자로 기재","전자입찰시스템으로 입찰서 제출"],answer:1,explanation:"동일인이 2개 이상 입찰서 제출은 대표적인 무효입찰 사유입니다."},
{id:"P2-027",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"투찰",ss:"2-2-5-1",tag:["입찰"],difficulty:"중",question:"전자투찰에 관한 설명으로 옳은 것은?",options:["오프라인 봉투에 담아 우편 발송","발주기관 담당자에게 직접 전달","입찰 마감 후에도 제출 가능","정해진 시간 내 나라장터를 통해 입찰서를 제출"],answer:3,explanation:"전자투찰은 나라장터를 통해 정해진 시간 안에 입찰서를 제출하는 방식입니다."},
{id:"P2-028",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"개찰",ss:"2-2-5-3",tag:["입찰"],difficulty:"중",question:"개찰에 관한 설명으로 옳은 것은?",options:["입찰 마감 후 봉인된 입찰서를 일제히 열어 금액을 확인","개별 입찰서를 순차적으로 발주자만 열람","입찰 마감 전 미리 확인","개찰조서 작성 의무 없음"],answer:0,explanation:"개찰은 입찰 마감 후 봉인된 입찰서를 일제히 열어 금액을 확인하는 절차입니다."},
{id:"P2-029",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"예정가격",ss:"1-5-2-1",tag:["입찰"],difficulty:"중",question:"예정가격에 관한 설명으로 옳지 않은 것은?",options:["입찰자에게 사전 공개하여 공정한 경쟁을 유도한다","입찰 또는 계약 전에 미리 작성한다","복수예비가격 방식으로 작성할 수 있다","낙찰자 결정의 기준이 된다"],answer:0,explanation:"예정가격은 담합 방지를 위해 사전 비공개가 원칙입니다."},
{id:"P2-030",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"복수예비가격",ss:"1-5-2-1",tag:["입찰"],difficulty:"상",question:"복수예비가격제도에 관한 설명으로 옳은 것은?",options:["낙찰가격을 미리 공개하는 제도","입찰자가 자유롭게 가격을 정하는 제도","여러 개의 예비가격 중 추첨으로 예정가격을 결정","수의계약 전용 제도"],answer:2,explanation:"복수예비가격은 여러 개의 예비가격을 작성한 후 추첨 등으로 예정가격을 결정하는 방식입니다."},
// ─── 입찰·제안평가 및 계약체결 ───
{id:"P2-031",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"평가 절차",ss:"2-3-4-2",tag:["평가"],difficulty:"중",question:"제안평가 절차에 관한 설명으로 옳은 것은?",options:["가격평가만 진행 후 종료","발주기관장 단독 평가","제안서 제출 즉시 자동 채점","평가위원회 구성 → 기술평가 → 가격평가 → 종합점수 산출"],answer:3,explanation:"제안평가는 평가위원회 구성 → 기술평가 → 가격평가 → 종합점수 산출 순으로 진행됩니다."},
{id:"P2-032",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"평가위원회",ss:"2-3-2-1",tag:["평가"],difficulty:"중",question:"제안서 평가위원회 구성에 관한 설명으로 옳지 않은 것은?",options:["외부 전문가를 포함하여 구성","이해충돌 시 회피 의무","발주기관 담당자가 단독으로 평가","평가 결과 기록·보존 의무"],answer:2,explanation:"제안서평가위원회는 소속공무원과 해당 분야 학식과 경험이 풍부한 사람 등으로 구성하고, 제안서 평가는 이 위원회를 거쳐야 하므로 담당자가 단독으로 평가할 수 없습니다.",basis:"국가계약법 시행령 제43조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제43조"},
{id:"P2-033",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"협상계약 체결 기한",ss:"2-3-4-2",tag:["계약","숫자"],difficulty:"중",question:"협상에 의한 계약체결기준상 협상 성립 후 며칠 이내에 계약을 체결해야 하는가?",options:["3일","7일","10일","5일"],answer:2,explanation:"협상이 성립된 후 10일 이내에 계약을 체결해야 합니다(협상에 의한 계약체결기준 제15조①).",basis:"(계약예규) 협상에 의한 계약체결기준 제15조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P2-034",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"기술평가 비율",ss:"2-3-4-2",tag:["평가","숫자"],difficulty:"상",question:"협상에 의한 계약체결기준상 기술능력 평가와 입찰가격 평가의 기본 배점은?",options:["기술 70 + 가격 30","기술 60 + 가격 40","기술 80 + 가격 20","기술 50 + 가격 50"],answer:0,explanation:"기본 배점은 기술능력 70점 + 입찰가격 30점입니다(협상에 의한 계약체결기준 [별표]). 사업 특성에 따라 일정 범위에서 조정할 수 있습니다(같은 기준 제7조).",basis:"(계약예규) 협상에 의한 계약체결기준 제7조 제1항·제2항 및 별표",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P2-035",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"기술평가 항목",ss:"2-3-4-2",tag:["평가"],difficulty:"중",question:"기술제안서 평가 항목에 해당하지 않는 것은?",options:["공사 수행방법","투입 인력의 자격","대표자 개인 재산 규모","유사 과업 실적"],answer:2,explanation:"기술제안서 평가는 수행방법·인력·실적 등을 평가하며 대표자 개인 재산은 평가 항목이 아닙니다."},
{id:"P2-036",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"평가위원 사전접촉",ss:"2-3-2-3",tag:["평가","공정"],difficulty:"중",question:"평가위원 사전접촉 금지 규정의 목적으로 가장 적절한 것은?",options:["공정한 평가 환경 확보","평가위원 업무 부담 감소","입찰 기간 단축","발주기관 행정 편의"],answer:0,explanation:"평가위원 사전접촉 금지는 공정한 평가를 보장하기 위함입니다."},
// ─── 낙찰자 결정방법 ───
{id:"P2-037",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"적격심사제",ss:"2-3-4-1",tag:["낙찰"],difficulty:"중",question:"적격심사제도에 관한 설명으로 옳은 것은?",options:["최저가 입찰자가 자동 낙찰","최저가 입찰자부터 가격평가와 계약이행능력을 함께 평가","모든 입찰에 의무 적용","기술제안서 평가가 반드시 포함"],answer:1,explanation:"적격심사는 최저가부터 가격+이행능력을 함께 평가해 일정 점수 이상이면 낙찰자로 결정합니다."},
{id:"P2-038",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"적격심사 기준",ss:"2-3-4-1",tag:["낙찰","숫자"],difficulty:"중",question:"추정가격 10억원 미만 공사 적격심사의 낙찰하한율은? (현행 기준)",options:["80%","89.745%","85%","90%"],answer:1,explanation:"현행 적격심사기준 [별표]의 입찰가격 평점식으로 계산한 공사 낙찰하한율은 10억원 미만 89.745%, 10억~50억원 88.745%, 50억~100억원 87.495%입니다(2026년 상향).",basis:"(계약예규) 적격심사기준 제8조 제1항 및 별표(추정가격 10억원 미만 공사 입찰가격 평점)",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)적격심사기준"},
{id:"P2-039",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"종합심사낙찰제",ss:"2-3-4-4",tag:["낙찰"],difficulty:"중",question:"종합심사낙찰제에 관한 설명으로 옳은 것은?",options:["가격뿐 아니라 시공능력·사회적 책임 등을 종합 평가","모든 공사 입찰에 적용","최저가 자동 낙찰","용역계약에 주로 활용"],answer:0,explanation:"종합심사낙찰제는 가격·공사수행능력·사회적 책임 등을 종합 평가합니다. 추정가격 100억원 이상 공사와 국가유산수리 공사, 일정 규모 이상 건설기술 용역(건설사업관리 50억원·기본설계 30억원·실시설계 40억원 이상)에 적용합니다.",basis:"국가계약법 시행령 제42조 제4항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제42조"},
{id:"P2-040",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"종합심사 배점",ss:"2-3-4-4",tag:["낙찰","숫자"],difficulty:"상",question:"공사계약 종합심사낙찰제 심사기준(일반공사)의 배점으로 옳은 것은?",options:["공사수행능력 40~50점 + 입찰금액 50~60점, 사회적 책임은 가점","공사수행능력 30점 + 입찰금액 60점 + 사회적 책임 10점","공사수행능력 20점 + 입찰금액 70점 + 사회적 책임 10점","공사수행능력 50점 + 입찰금액 30점 + 사회적 책임 20점"],answer:0,explanation:"일반공사는 공사수행능력 40~50점 + 입찰금액 50~60점(합계 100점)이고, 사회적 책임은 가점(1점)입니다. 간이형은 40점 + 60점, 가점 1.5점입니다(공사계약 종합심사낙찰제 심사기준 [별표1-1]·[별표1-3]).",basis:"(계약예규) 공사계약 종합심사낙찰제 심사기준 별표1-1",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약종합심사낙찰제심사기준"},
{id:"P2-041",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"종합심사 적용대상",ss:"2-3-4-4",tag:["낙찰","숫자"],difficulty:"중",question:"종합심사낙찰제는 추정가격 몇 억원 이상 공사에 적용되는가?",options:["300억원","100억원","200억원","500억원"],answer:1,explanation:"추정가격 100억원 이상 공사에 종합심사낙찰제가 적용됩니다(시행령 42조④1호). 100억원 미만 공사는 대부분 적격심사 대상입니다(국가유산수리 공사 등 예외).",basis:"국가계약법 시행령 제42조 제4항 제1호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제42조"},
{id:"P2-042",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"PQ",ss:"3-4-2-3",tag:["낙찰","숫자"],difficulty:"중",question:"입찰참가자격사전심사요령상 교량·터널·항만 등 18개 주요 공종 공사에 별표2(주요 공종 심사기준)를 적용하는 추정가격 기준은?",options:["100억원","50억원","200억원","300억원"],answer:2,explanation:"PQ(입찰참가자격 사전심사)는 발주기관이 \"할 수 있는\" 제도입니다. PQ를 할 때 추정가격 200억원 이상인 교량·공항·댐·터널·항만 등 18개 공종 공사에는 별표2 심사기준을 적용합니다.",basis:"(계약예규) 입찰참가자격사전심사요령 제6조 제5항 제1호",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)입찰참가자격사전심사요령"},
{id:"P2-043",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"협상계약",ss:"2-3-3-3",tag:["낙찰"],difficulty:"중",question:"협상에 의한 계약의 낙찰자 결정 절차로 옳은 것은?",options:["최저가 자동 낙찰","발주기관장 단독 결정","기술·가격 합산점수가 높은 협상적격자부터 차례로 협상","무작위 추첨"],answer:2,explanation:"협상순서는 기술능력평가 점수와 입찰가격평가 점수를 더한 합산점수가 높은 순서입니다(동점이면 기술점수가 높은 쪽). 1순위와 협상이 성립하면 끝나고, 결렬되면 다음 순위와 협상합니다. 기술점수만으로 순서를 정하지 않습니다.",basis:"협상에 의한 계약체결기준 제8조 제2항, 제10조",basisUrl:"https://www.law.go.kr/행정규칙/협상에의한계약체결기준"},
{id:"P2-044",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"낙찰률",ss:"2-3-4-5",tag:["낙찰"],difficulty:"중",question:"낙찰률의 정의로 옳은 것은?",options:["예정가격 대비 낙찰금액 비율","입찰자 수 대비 낙찰자 수 비율","계약금액 대비 선급금 비율","총 사업비 대비 공사비 비율"],answer:0,explanation:"낙찰률은 예정가격 대비 낙찰금액의 비율입니다."},
{id:"P2-045",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"최저가 낙찰제",ss:"2-3-4-5",tag:["낙찰"],difficulty:"중",question:"최저가 낙찰제에 관한 설명으로 옳은 것은?",options:["가격과 기술을 종합 평가","발주자가 임의로 선정","경쟁 없이 결정","가장 낮은 금액을 써낸 업체를 낙찰자로 결정"],answer:3,explanation:"최저가 낙찰제는 가장 낮은 금액을 써낸 업체를 낙찰자로 결정합니다."},
{id:"P2-046",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"저가낙찰",ss:"2-3-4-5",tag:["낙찰","숫자"],difficulty:"상",question:"공사 저가낙찰의 기준으로 옳은 것은?",options:["예정가격 80% 미만 낙찰","예정가격 70% 미만 낙찰","예정가격 90% 미만 낙찰","예정가격 50% 미만 낙찰"],answer:1,explanation:"예정가격 70% 미만 낙찰을 저가낙찰로 보며 공사이행보증 50%로 강화됩니다.",basis:"국가계약법 시행령 제52조 제1항 제2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제52조"},
{id:"P2-047",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"일괄입찰",ss:"3-4-3-2",tag:["낙찰"],difficulty:"상",question:"공사 일괄입찰(턴키)에 관한 설명으로 옳지 않은 것은?",options:["설계와 시공을 하나의 업체가 수행","발주기관이 설계를 완료한 후 시공만 입찰","기술제안 능력이 중요한 평가 요소","대형 복잡 공사에 주로 적용"],answer:1,explanation:"턴키는 설계+시공을 묶는 방식이며 발주기관이 설계를 완료하지 않습니다."},
{id:"P2-048",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"낙찰자 결정방법",sub:"대안입찰",ss:"3-4-3-2",tag:["낙찰"],difficulty:"상",question:"공사 대안입찰에 관한 설명으로 옳은 것은?",options:["원안 외에 업체가 대안 설계를 제안할 수 있다","시공 방법 변경 불가","원안보다 가격이 높은 설계도 대안으로 인정된다","모든 공사에 적용된다"],answer:0,explanation:"대안입찰은 원안입찰과 함께 입찰자가 대안을 낼 수 있게 허용한 공사 입찰입니다. 대안은 정부 실시설계서보다 가격이 낮으면서 공사기간이 늘지 않고 기능·효과가 같거나 나은 설계여야 하므로, 원안보다 비싼 설계는 대안이 될 수 없습니다.",basis:"국가계약법 시행령 제79조 제1항 제3호·제4호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제79조"},
// ─── 입찰결과 분석 및 이의제기 ───
{id:"P2-049",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"이의제기 사유",ss:"2-3-5-2",tag:["이의제기"],difficulty:"중",question:"입찰 결과에 대한 이의 제기가 가능한 사유로 옳은 것은?",options:["낙찰자의 영업 규모가 작은 경우","입찰·낙찰 과정에서 법령 위반 오류가 있는 경우","경쟁 업체의 가격이 낮은 경우","발주기관이 마음에 들지 않는 업체를 선정한 경우"],answer:1,explanation:"법령 위반·절차 오류가 있는 경우 이의 제기가 가능합니다."},
{id:"P2-051",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"낙찰 결과 분석",ss:"2-3-5-1",tag:["분석"],difficulty:"중",question:"낙찰 결과 분석 시 검토해야 할 핵심 사항은?",options:["낙찰자 대표 출신학교","발주기관 담당자 연락처","경쟁사 매출액","낙찰률·평가 점수·경쟁 강도"],answer:3,explanation:"낙찰률, 평가 점수, 경쟁 강도 등은 향후 입찰 전략 수립에 필요한 핵심 정보입니다."},
{id:"P2-052",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"낙찰 무효",ss:"2-3-5-1",tag:["이의제기"],difficulty:"상",question:"낙찰의 무효 사유로 보기 어려운 것은?",options:["낙찰자의 영업 규모가 작은 것","입찰 담합 적발","입찰참가자격 결격 사유 발견","법령 위반 절차"],answer:0,explanation:"단순히 영업 규모가 작은 것은 낙찰 무효 사유가 아닙니다."},
{id:"P2-053",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"이의제기 절차",ss:"2-3-5-2",tag:["이의제기"],difficulty:"중",question:"입찰 이의 제기 절차로 옳은 것은?",options:["즉시 형사고소","민간 중재기관에 신고","발주기관에 서면 이의 → 미해결 시 분쟁조정 → 소송","경쟁 업체에 항의"],answer:2,explanation:"이의 제기는 발주기관 서면 이의 → 분쟁조정 → 소송 순으로 단계적으로 진행됩니다."},
{id:"P2-054",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"부정당업자 등록",ss:"1-6-2-2",tag:["이의제기","제재"],difficulty:"중",question:"부정당업자 제재의 효과로 옳은 것은?",options:["일정 기간(2년 이내) 국가기관 등 공공 입찰 참가 제한","해당 발주기관에만 제한","민형사 처벌은 면제","제재 즉시 기존 계약 자동 무효"],answer:0,explanation:"입찰참가자격 제한은 2년 이내이고, 제한 사실은 다른 중앙관서에 통보되어 그 기관들도 제한하며 전자조달시스템에 게재되므로, 처분한 기관뿐 아니라 다른 기관 입찰 참가도 막힙니다.",basis:"국가계약법 제27조 제1항·제5항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제27조"},
{id:"P2-055",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"낙찰 결과 활용",ss:"2-3-5-1",tag:["분석"],difficulty:"중",question:"입찰 결과 분석 결과의 활용 방안으로 가장 적절한 것은?",options:["경쟁사 비방 자료로 활용","향후 입찰 가격 전략 수립","발주자 협박 자료로 활용","담합 자료로 활용"],answer:1,explanation:"입찰 결과 분석은 향후 입찰 가격·전략 수립에 활용하는 것이 바람직합니다."},
{id:"P2-056",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"이의제기 기한",ss:"2-3-5-2",tag:["이의제기"],difficulty:"상",question:"낙찰자 결정 후 이의 제기 기간에 관한 일반 원칙으로 옳은 것은?",options:["통상 일정 기한 내(예: 통지 후 일정일)에 제기해야 함","무기한 제기 가능","이의 제기 자체가 불가능","계약 종결 후에도 자유롭게 가능"],answer:0,explanation:"이의 제기는 통상 일정 기한 내에 제기해야 효력이 있습니다."},
{id:"P2-057",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"낙찰 통지",ss:"2-2-5-3",tag:["낙찰"],difficulty:"중",question:"낙찰자 통지에 관한 설명으로 옳은 것은?",options:["구두로만 통지","통지 없이 계약 체결","비공식적 통보","낙찰자 결정 결과를 해당자에게 지체 없이 통보"],answer:3,explanation:"낙찰자 결정 결과는 해당자에게 지체 없이 통보해야 합니다. 전자입찰은 입찰공고에 정한 방법(나라장터 등)으로 공식 통보하며, 구두·비공식 통보나 통보 없는 계약 체결은 허용되지 않습니다.",basis:"(계약예규) 적격심사기준 제8조 제4항",basisUrl:"https://www.law.go.kr/행정규칙/적격심사기준"},
{id:"P2-058",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"입찰 통계",ss:"2-3-5-1",tag:["분석"],difficulty:"중",question:"입찰 통계 분석을 통해 얻을 수 있는 정보가 아닌 것은?",options:["과거 낙찰률 추이","경쟁 강도","경쟁사의 내부 회의록","평균 입찰자 수"],answer:2,explanation:"경쟁사의 내부 회의록은 통계 분석으로 얻을 수 있는 정보가 아닙니다."},
{id:"P2-059",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"부정당업자 처분 절차",ss:"1-6-2-2",tag:["제재"],difficulty:"상",question:"부정당업자 제재 처분 절차에 관한 설명으로 옳은 것은?",options:["사실 조사 → 의견 청취 → 처분 결정 → 통지","즉시 처분 통지","조사 없이 자동 처분","민간 중재로 결정"],answer:0,explanation:"부정당업자 제재는 사실 조사·의견 청취 등 적법 절차를 거쳐 처분합니다."},
{id:"P2-060",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰결과 분석 및 이의제기",sub:"종합 - 입찰 결과 처리",ss:"2-2-5-3",tag:["종합"],difficulty:"상",question:"입찰 결과 처리에 관한 설명으로 옳지 않은 것은?",options:["낙찰자 결정 즉시 모든 입찰자에게 결과 비공개","낙찰자에게 서면 통지","입찰 결과는 나라장터 공개","이의 제기 기회 보장"],answer:0,explanation:"입찰 결과는 공개·통지가 원칙입니다. 모든 입찰자에게 비공개하지 않습니다."},
// ─── 계약관리 일반 절차 ───
{id:"P3-001",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약 효력",ss:"3-1-1-1",tag:["계약","기초"],difficulty:"하",question:"계약서를 작성하는 국가계약은 어느 때에 확정되는가?",options:["낙찰자로 결정되었다는 통지를 한 때","입찰공고에 계약조건을 게시한 때","담당 공무원과 계약상대자가 계약서에 기명·날인하거나 서명한 때","선금을 포함한 첫 대가를 지급한 때"],answer:2,explanation:"계약서를 작성하는 경우 담당 공무원과 계약상대자가 계약서에 기명하고 날인하거나 서명해야 계약이 확정됩니다(국가계약법 제11조②). 낙찰 통지나 대가 지급은 확정 시점이 아닙니다.",basis:"국가계약법 제11조②",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제11조"},
{id:"P3-002",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약금액 산정",ss:"3-1-1-1",tag:["계약","계산"],difficulty:"중",question:"낙찰자와 계약을 체결할 때 계약서에 적는 계약금액에 대한 설명으로 옳은 것은?",options:["부가가치세를 제외한 추정가격을 계약금액으로 한다","예정가격을 그대로 계약금액으로 한다","낙찰금액에 부가가치세를 별도로 합산하여 산정한다","낙찰금액과 같은 금액으로 한다"],answer:3,explanation:"예정가격에는 부가가치세 등 세액이 포함되므로(시행규칙 제11조①) 입찰금액과 낙찰금액도 세액을 포함한 금액입니다. 따라서 계약금액은 낙찰금액과 같으며 부가가치세를 다시 더하지 않습니다.",basis:"국가계약법 시행규칙 제11조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제11조"},
{id:"P3-003",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약서 작성",ss:"3-1-1-1",tag:["계약"],difficulty:"중",question:"국가계약법이 계약서에 명백히 적도록 열거한 사항이 아닌 것은?",options:["계약보증금","다른 입찰자들의 투찰금액","위험부담","지체상금"],answer:1,explanation:"계약서에는 계약의 목적, 계약금액, 이행기간, 계약보증금, 위험부담, 지체상금 및 그 밖에 필요한 사항을 명백히 적어야 합니다(국가계약법 제11조①). 다른 입찰자의 투찰금액은 기재사항이 아닙니다.",basis:"국가계약법 제11조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제11조"},
{id:"P3-004",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"착수협의",ss:"3-1-1-3",tag:["계약"],difficulty:"중",question:"계약 체결 직후 착수 단계에서 발주기관과 계약상대자가 확인할 내용으로 가장 거리가 먼 것은?",options:["업무 공정 예정표와 착수 일정","투입할 인력과 장비 계획","중간·최종 보고의 시기와 방법","발주기관 직원의 개인 신상 정보"],answer:3,explanation:"용역 착수 시에는 용역공정예정표, 인력 및 장비투입계획서 등을 담은 착수신고서를 제출하게 할 수 있습니다(용역계약일반조건 제13조①). 착수 단계는 일정·인력·보고 체계를 맞추는 자리이며 직원 개인정보와는 관계가 없습니다.",basis:"(계약예규) 용역계약일반조건 제13조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-005",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약담당자 의무",ss:"3-1-1-1",tag:["계약"],difficulty:"중",question:"계약담당공무원이 계약 이행 과정에서 해야 할 일로 볼 수 없는 것은?",options:["계약상대자에게 개인적인 부탁이나 청탁을 하는 것","계약 내용대로 이행되는지 감독·점검하는 것","계약 변경 사항을 문서로 관리하는 것","정해진 기한 안에 대가를 지급하는 것"],answer:0,explanation:"계약담당공무원은 이행 감독, 변경 관리, 기한 내 대가 지급 등을 공정하게 수행해야 합니다. 계약상대자에게 사적 청탁을 하는 것은 청렴 의무에 어긋나는 행위입니다."},
{id:"P3-006",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약 일반원칙",ss:"3-1-1-1",tag:["계약"],difficulty:"중",question:"국가계약법이 정한 계약의 원칙에 어긋나는 것은?",options:["계약은 당사자가 서로 대등한 입장에서 합의하여 체결한다","당사자는 계약 내용을 신의성실의 원칙에 따라 이행한다","발주기관은 필요하면 계약상대자의 법령상 이익을 부당하게 제한하는 특약을 일방적으로 넣을 수 있다","계약상대자의 계약상 이익을 부당하게 제한하는 특약은 무효이다"],answer:2,explanation:"계약은 대등한 입장에서 합의로 체결하고 신의성실에 따라 이행해야 하며(국가계약법 제5조①), 계약상대자의 이익을 부당하게 제한하는 특약은 정할 수 없고 정하더라도 무효입니다(같은 조 ③④).",basis:"국가계약법 제5조①③④",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제5조"},
{id:"P3-007",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약상대자 의무",ss:"3-1-3-2",tag:["계약"],difficulty:"중",question:"계약상대자가 지켜야 할 의무로 옳지 않은 것은?",options:["계약문서에서 정한 내용대로 이행한다","계약을 통해 알게 된 정보라도 계약이 끝난 뒤에는 자유롭게 외부에 알릴 수 있다","계약 내용을 신의성실에 따라 이행한다","이행 중 계약 내용 변경으로 제출 서류가 달라지면 변경된 서류를 다시 제출한다"],answer:1,explanation:"계약상대자는 계약을 통해 얻은 정보나 국가의 비밀사항을 계약이행 전후를 가리지 않고 외부에 누설할 수 없습니다(공사계약일반조건 제50조②). 계약이 끝났다고 공개가 허용되지 않습니다.",basis:"(계약예규) 공사계약일반조건 제50조②",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-008",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약 위험관리",ss:"3-1-3-5",tag:["계약","리스크"],difficulty:"상",question:"계약 이행 단계의 위험관리 활동으로 보기 어려운 것은?",options:["담당 공무원 개인의 보수 조정 협의","납기 지연 징후를 조기에 파악하고 만회 계획을 세우는 것","원자재 가격 급등이 계약 이행에 줄 영향을 평가하는 것","불가항력 사태에 대비한 대응 절차를 마련하는 것"],answer:0,explanation:"위험관리는 납기·원가·불가항력처럼 계약 이행을 방해할 수 있는 요인을 찾아 대비하는 활동입니다. 공무원 개인의 보수 문제는 계약 위험과 관련이 없습니다."},
// ─── 계약변경 관리 ───
{id:"P3-009",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"변경 일반",ss:"3-1-2-1",tag:["변경"],difficulty:"중",question:"이미 체결된 계약의 내용을 바꿀 때 일반적으로 거치는 절차가 아닌 것은?",options:["변경 사유가 타당한지 검토한다","당사자가 합의한 뒤 변경계약서를 작성한다","변경 내용을 관계자에게 통보한다","변경 내용을 반영하여 입찰공고를 처음부터 다시 낸다"],answer:3,explanation:"계약변경은 기존 계약을 유지한 채 사유 검토, 변경계약서 작성, 통보 순으로 처리합니다. 새로 입찰에 부치는 것은 변경이 아니라 새 계약 절차입니다."},
{id:"P3-010",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"설계변경",ss:"3-4-2-5",tag:["변경","공사"],difficulty:"중",question:"공사계약에서 설계변경으로 기존 비목의 물량이 늘거나 줄어 계약금액을 조정할 때, 증감된 물량에 적용하는 단가의 원칙은?",options:["설계변경 당시를 기준으로 산정한 단가에 낙찰률을 곱한 단가","계약상대자가 제출한 산출내역서상의 단가(계약단가)","설계변경 당시의 시장가격","발주기관이 재량으로 정하는 단가"],answer:1,explanation:"증감된 공사량의 단가는 산출내역서상의 계약단가로 합니다. 다만 계약단가가 예정가격단가보다 높은데 물량이 늘면 증가분에는 예정가격단가를 적용합니다(시행령 제65조③1). 낙찰률을 곱한 단가는 계약단가가 없는 신규비목에 쓰는 방식입니다.",basis:"국가계약법 시행령 제65조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제65조"},
{id:"P3-011",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"물가변동 90일",ss:"3-1-2-2",tag:["변경","숫자"],difficulty:"중",question:"물가변동으로 계약금액을 조정하려면 원칙적으로 계약을 체결한 날부터 얼마 이상 지나야 하는가?",options:["30일","60일","120일","90일"],answer:3,explanation:"계약 체결일(장기계속계약은 제1차 계약 체결일)부터 90일 이상 지나고 조정률이 3% 이상 증감해야 조정합니다(시행령 제64조①). 천재지변·원자재 가격 급등 시의 예외(같은 조 ⑤)는 별도입니다.",basis:"국가계약법 시행령 제64조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제64조"},
{id:"P3-012",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"물가변동 변동률",ss:"3-1-2-2",tag:["변경","숫자"],difficulty:"중",question:"물가변동 조정 요건에서 입찰일을 기준으로 산출한 품목조정률 또는 지수조정률은 얼마 이상 증감해야 하는가?",options:["1%","5%","3%","10%"],answer:2,explanation:"품목조정률이나 지수조정률이 100분의 3 이상 증감한 때 계약금액을 조정합니다(시행령 제64조①1·2). 오르는 경우와 내리는 경우 모두 해당합니다.",basis:"국가계약법 시행령 제64조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제64조"},
{id:"P3-013",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"물가변동 종합",ss:"3-1-2-2",tag:["변경"],difficulty:"중",question:"물가변동으로 인한 계약금액 조정에 대한 설명으로 옳은 것은?",options:["계약 체결 후 90일 이상 지나고 조정률이 3% 이상 증감하면 계약금액을 조정한다","계약 체결 다음 날부터 곧바로 조정할 수 있다","물가가 내려간 경우에는 계약금액을 줄이지 않는다","한 번 조정하면 그 계약에서는 다시 조정할 수 없다"],answer:0,explanation:"90일 경과와 3% 이상 증감을 함께 충족해야 하며 증가뿐 아니라 감소도 조정 대상입니다. 조정기준일부터 90일 이내에만 다시 조정하지 못할 뿐 이후 재조정은 가능합니다(시행령 제64조①).",basis:"국가계약법 시행령 제64조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제64조"},
{id:"P3-014",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"과업변경",ss:"3-1-2-2",tag:["변경","용역"],difficulty:"중",question:"용역계약에서 과업내용이 바뀌는 경우에 대한 설명으로 옳은 것은?",options:["계약을 체결하면 과업내용은 어떤 경우에도 바꿀 수 없다","과업내용을 바꾸려면 계약을 해지하고 다시 입찰해야 한다","과업을 추가하더라도 추가 대가는 지급하지 않는다","발주기관이 과업 변경을 지시하거나 승인하면 그에 따라 계약금액을 조정한다"],answer:3,explanation:"발주기관은 필요하면 추가업무·공정계획 변경·항목 삭제 등을 지시할 수 있고(추가 시 사전 협의), 이 경우 계약금액은 시행령 제65조를 준용해 조정하며 과업에 없던 일을 요구하면 정당한 대가를 지급해야 합니다(용역계약일반조건 제16조①④).",basis:"(계약예규) 용역계약일반조건 제16조①④",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-015",exam:"필기",subject:"공공계약관리",major:"계약변경 관리",sub:"기간 연장",ss:"3-1-3-3",tag:["변경"],difficulty:"중",question:"공사계약에서 계약상대자가 계약기간 연장을 신청할 수 있는 사유로 옳지 않은 것은?",options:["천재지변 등 불가항력으로 공사가 지체된 경우","계약상대자가 자기 사정으로 인력을 제때 투입하지 못한 경우","발주기관의 책임으로 착공이 늦어진 경우","대체할 수 없는 중요 관급자재의 공급이 늦어진 경우"],answer:1,explanation:"불가항력, 중요 관급자재 공급 지연, 발주기관 책임의 착공 지연 등 지체일수 산입 제외 사유가 계약기간 안에 생기면 연장을 신청할 수 있습니다(공사계약일반조건 제26조①, 제25조③). 계약상대자 자신의 사정은 해당하지 않습니다.",basis:"(계약예규) 공사계약일반조건 제26조①, 제25조③",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
// ─── 계약이행 관리 ───
{id:"P3-016",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"착공계",ss:"3-4-3-3",tag:["이행","공사"],difficulty:"하",question:"공사계약의 착공신고서에 대한 설명으로 옳은 것은?",options:["공사를 착공할 때 공사공정예정표 등을 첨부하여 발주기관에 제출하는 서류","준공검사를 요청할 때 제출하는 서류","하도급 승인을 받기 위해 제출하는 서류","기성대가를 청구할 때 첨부하는 서류"],answer:0,explanation:"계약상대자는 착공 시 현장기술자지정신고서, 공사공정예정표, 안전·환경·품질관리계획서 등을 포함한 착공신고서를 발주기관에 제출합니다. 공사기간 30일 미만 등은 제출을 생략하게 할 수 있습니다(공사계약일반조건 제17조①).",basis:"(계약예규) 공사계약일반조건 제17조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-017",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"선급금 한도",ss:"3-1-4-2",tag:["이행","숫자"],difficulty:"중",question:"정부 입찰·계약 집행기준상 선금은 계약금액의 얼마를 넘지 않는 범위에서 지급할 수 있는가?",options:["100분의 50","100분의 100","100분의 30","100분의 70"],answer:3,explanation:"계약상대자가 요청하면 계약금액의 100분의 70을 넘지 않는 범위에서 선금을 지급할 수 있습니다(집행기준 제34조①).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제34조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-018",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"선급금보증금",ss:"3-1-4-5",tag:["이행"],difficulty:"중",question:"선금을 지급할 때 계약상대자에게 받는 채권확보 수단에 대한 설명으로 옳은 것은?",options:["선금은 보증서 없이 지급하는 것이 원칙이다","보증금액은 선금액과 정확히 같은 금액이면 충분하다","원칙적으로 보증서 등을 받되, 보증금액은 선금액에 약정이자상당액을 더한 금액 이상이어야 한다","국가·지방자치단체와 계약한 경우에도 반드시 보증서를 받아야 한다"],answer:2,explanation:"선금 지급 시 증권·보증서를 제출하게 하고 그 금액은 선금액에 약정이자상당액을 더한 금액 이상이어야 합니다(집행기준 제35조①②). 국가·지방자치단체·공기업 등과의 계약은 보증서 대신 반납을 확약하는 문서를 받습니다(제35조① 단서).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제35조①②",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-019",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"공사 선금 의무 100억",ss:"3-1-4-2",tag:["이행","숫자"],difficulty:"상",question:"계약상대자가 선금을 처음 신청하면 발주기관은 규모별 기준 금액을 넘지 않는 범위에서 청구일부터 14일 이내에 지급해야 한다. 계약금액이 100억원 이상인 공사의 기준 비율은?",options:["계약금액의 100분의 30","계약금액의 100분의 40","계약금액의 100분의 50","계약금액의 100분의 20"],answer:0,explanation:"공사는 100억원 이상 100분의 30, 20억~100억원 미만 100분의 40, 20억원 미만 100분의 50입니다. 최초 신청 시 이 금액까지 청구일부터 14일 이내에 지급합니다(집행기준 제34조②④, 2026.4.1 개정).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제34조②④",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-020",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"공사 선금 의무 20억미만",ss:"3-1-4-2",tag:["이행","숫자"],difficulty:"상",question:"선금을 처음 신청할 때 청구일부터 14일 이내에 지급해야 하는 기준 금액과 관련하여, 계약금액 20억원 미만인 공사(수해복구공사 제외)의 기준 비율은?",options:["계약금액의 100분의 30","계약금액의 100분의 40","계약금액의 100분의 50","계약금액의 100분의 70"],answer:2,explanation:"일반 공사는 규모가 작을수록 비율이 높아 20억원 미만이면 100분의 50입니다. 100분의 70은 20억원 미만 수해복구공사의 기준입니다(집행기준 제34조②④, 2026.4.1 개정).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제34조②④",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-021",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"물품·용역 선금 3억미만",ss:"3-1-4-2",tag:["이행","숫자"],difficulty:"상",question:"물품 제조 또는 용역 계약에서 계약상대자가 선금을 처음 신청할 때, 계약금액 3억원 미만 계약의 기준 비율(청구일부터 14일 이내 지급)은?",options:["계약금액의 100분의 30","계약금액의 100분의 50","계약금액의 100분의 40","계약금액의 100분의 60"],answer:1,explanation:"물품 제조·용역은 10억원 이상 100분의 30, 3억~10억원 미만 100분의 40, 3억원 미만 100분의 50입니다. 최초 신청 시 이 금액까지 14일 이내에 지급합니다(집행기준 제34조②④, 2026.4.1 개정).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제34조②④",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-022",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"기성",ss:"3-1-4-2",tag:["이행"],difficulty:"중",question:"공사계약에서 \"기성(旣成)부분\"이 뜻하는 것으로 옳은 것은?",options:["계약 체결 전에 미리 협의한 공정","계약상대자를 제재하는 사유","대가 지급을 거절할 수 있는 사유","공사 진행 중 이미 시공이 끝난 부분으로, 검사를 거쳐 그 대가를 중간에 받을 수 있는 부분"],answer:3,explanation:"기성부분은 공사 도중 이미 완성된 부분을 말하며, 발주기관은 검사를 거쳐 그 대가를 적어도 30일마다 지급해야 합니다(시행령 제58조③).",basis:"국가계약법 시행령 제58조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제58조"},
{id:"P3-023",exam:"필기",subject:"공공계약관리",major:"계약이행 관리",sub:"기성대가 주기",ss:"3-1-4-2",tag:["이행","숫자"],difficulty:"상",question:"기성부분 또는 기납부분에 대한 대가는 계약수량·이행 전망·이행기간 등을 참작하여 적어도 며칠마다 지급해야 하는가?",options:["30일","7일","15일","60일"],answer:0,explanation:"기성·기납부분의 대가는 적어도 30일마다 지급해야 합니다(시행령 제58조③).",basis:"국가계약법 시행령 제58조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제58조"},
// ─── 계약종결 관리 ───
{id:"P3-024",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"검사 기한",ss:"3-1-4-1",tag:["종결","숫자"],difficulty:"중",question:"계약상대자로부터 이행을 완료했다는 통지를 받은 경우, 검사는 원칙적으로 통지받은 날부터 며칠 이내에 마쳐야 하는가?",options:["7일","10일","14일","30일"],answer:2,explanation:"검사는 이행 완료 통지를 받은 날부터 14일 이내에 완료해야 합니다(시행령 제55조①). 경제위기 등으로 재정경제부장관이 고시한 기간에는 7일로 단축됩니다.",basis:"국가계약법 시행령 제55조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제55조"},
{id:"P3-025",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"대금 지급",ss:"3-1-4-2",tag:["종결","숫자"],difficulty:"중",question:"검사를 마친 뒤 계약상대자가 대가 지급을 청구하면, 발주기관은 원칙적으로 청구를 받은 날부터 며칠 이내에 지급해야 하는가?",options:["5일","3일","7일","14일"],answer:0,explanation:"대가는 검사 완료 후 청구를 받은 날부터 5일(공휴일·토요일 제외) 이내에 지급해야 하고(시행령 제58조①⑥), 늦어지면 지연이자를 지급합니다(제59조). 경제위기 고시 기간에는 3일입니다.",basis:"국가계약법 시행령 제58조①, 제59조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제58조"},
{id:"P3-026",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"불가항력 지급",ss:"3-1-4-2",tag:["종결","숫자"],difficulty:"상",question:"천재지변 등 불가항력 때문에 지급기한 안에 대가를 지급하지 못한 경우, 그 사유가 없어진 날부터 며칠 이내에 지급해야 하는가?",options:["5일","3일","7일","10일"],answer:1,explanation:"불가항력으로 기한 내 지급하지 못하면 사유가 소멸한 날부터 3일 이내에 대가를 지급해야 합니다(시행령 제58조②).",basis:"국가계약법 시행령 제58조②",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제58조"},
{id:"P3-027",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"검사·검수",ss:"3-1-4-1",tag:["종결"],difficulty:"중",question:"국가계약에서 이행 완료에 따른 검사에 대한 설명으로 옳지 않은 것은?",options:["계약서·설계서 등 관계 서류에 따라 이행 내용을 확인한다","검사하는 자는 원칙적으로 검사조서를 작성한다","품질인증을 받은 물품 등 대통령령으로 정하는 물품은 검사를 하지 않을 수 있다","물품 계약에서 시험 등 검사에 드는 비용과 검사로 생긴 손상은 발주기관이 부담한다"],answer:3,explanation:"물품구매·제조 계약의 검사 비용과 검사로 인한 변형·파손 등 손상은 계약상대자가 부담합니다(국가계약법 제14조④). 나머지는 같은 조 ①~③의 내용으로 옳습니다.",basis:"국가계약법 제14조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제14조"},
{id:"P3-028",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"세금계산서",ss:"3-1-4-2",tag:["종결"],difficulty:"중",question:"세금계산서에 대한 설명으로 옳은 것은?",options:["과세 재화·용역을 공급한 사업자가 공급가액과 부가가치세액을 적어 공급받는 자에게 발급한다","세무서가 발급하여 공급자에게 교부하는 서류이다","부가가치세가 면제되는 재화를 공급할 때에도 발급해야 한다","공급가액만 적고 부가가치세액은 적지 않는다"],answer:0,explanation:"사업자가 재화·용역을 공급하면(면세 공급 제외) 공급가액과 부가가치세액 등을 적은 세금계산서를 공급받는 자에게 발급해야 합니다(부가가치세법 제32조①). 계약대가 청구 시 이를 증빙으로 첨부합니다.",basis:"부가가치세법 제32조①",basisUrl:"https://www.law.go.kr/법령/부가가치세법/제32조"},
{id:"P3-029",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"정산",ss:"3-1-4-3",tag:["종결"],difficulty:"중",question:"계약 마무리 단계의 정산에 대한 설명으로 옳은 것은?",options:["최초 계약금액을 그대로 지급하는 절차이다","검사 전에 예상 금액을 미리 계산하는 절차이다","보증금 납부액을 산정하는 절차이다","이미 지급한 선금·기성대가 등을 반영하여 최종 지급액을 확정하는 절차이다"],answer:3,explanation:"정산은 선금·기성대가 등 이미 지급한 금액을 반영해 마지막으로 줄 금액을 확정하는 절차입니다. 선금은 기성·기납 대가를 지급할 때마다 정산액을 공제합니다(집행기준 제37조①).",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제37조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-030",exam:"필기",subject:"공공계약관리",major:"계약종결 관리",sub:"계약 종결 절차",ss:"3-1-4-3",tag:["종결"],difficulty:"상",question:"계약종결 과정에서 가장 마지막에 이루어지는 것은?",options:["납품(준공) 검사","이행 완료를 최종 확인하고 관계 서류를 정리·보관하여 종결 처리하는 것","대가 지급","하자보수보증금 납부"],answer:1,explanation:"검사 후 하자보수보증금을 대가 지급 전까지 납부하고(시행령 제62조②) 대가를 지급한 뒤, 이행 완료를 확인하고 서류를 정리·보관하는 것으로 계약을 종결합니다."},
// ─── 물품 계약관리 ───
{id:"P3-031",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 규격",ss:"3-2-1-2",tag:["물품"],difficulty:"중",question:"물품 구매계약에서 납품할 물품의 사양과 성능을 정하는 핵심 발주 문서는?",options:["과업지시서","설계도면","규격서(구매사양서)","공사 시방서"],answer:2,explanation:"물품은 계약에 명시된 규격명세·규격번호 등을 충족해야 하므로 규격서(구매사양서)가 핵심입니다(물품구매(제조)계약일반조건 제13조①). 과업지시서는 용역, 설계도면·시방서는 공사의 문서입니다.",basis:"(계약예규) 물품구매(제조)계약일반조건 제13조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
{id:"P3-032",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"납품 검수",ss:"3-1-3-1",tag:["물품"],difficulty:"중",question:"물품 계약에서 납품부터 대가 지급까지의 순서로 옳은 것은?",options:["납품 → 대가 지급 → 검사","납품 → 품질·수량 등 검사 → 검사조서 작성 → 대가 지급","검사조서 작성 → 납품 → 대가 지급","대가 지급 → 납품 → 검사"],answer:1,explanation:"납품된 물품을 검사하고 검사조서를 작성한 뒤에 대가를 지급합니다(국가계약법 제14조②, 제15조①).",basis:"국가계약법 제14조②, 제15조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제15조"},
{id:"P3-033",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 지체상금률",ss:"3-1-4-6",tag:["물품","숫자"],difficulty:"중",question:"물품의 제조·구매 계약에 원칙적으로 적용하는 1일 지체상금률은?",options:["0.05%","0.125%","0.075%","0.25%"],answer:2,explanation:"물품 제조·구매의 지체상금률은 1천분의 0.75(0.075%)입니다. 계약 후 설계와 제조를 일괄하고 설계 승인이 필요한 물품만 예외로 1천분의 0.5입니다(시행규칙 제75조2호).",basis:"국가계약법 시행규칙 제75조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-034",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 하자보수",ss:"3-1-4-4",tag:["물품","숫자"],difficulty:"상",question:"조달청이 물품 구매계약에서 하자보수보증이 필요하다고 보아 하자보수보증금을 내게 할 때, 그 금액은 계약금액의 얼마인가?",options:["3%","2%","5%","10%"],answer:0,explanation:"조달청은 하자보수보증이 필요한 경우 물품은 계약금액의 100분의 3, 용역은 100분의 2의 하자보수보증금을 납부하게 할 수 있습니다(조달청 내자구매업무 처리규정 제59조①).",basis:"조달청 내자구매업무 처리규정 제59조①",basisUrl:"https://www.law.go.kr/행정규칙/조달청내자구매업무처리규정"},
{id:"P3-035",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 소액수의",ss:"3-2-1-4",tag:["물품","숫자"],difficulty:"중",question:"계약상대자의 규모와 관계없이 소액 수의계약을 할 수 있는 물품 제조·구매 계약의 추정가격 기준은?",options:["2천만원 이하","1천만원 이하","5천만원 이하","1억원 이하"],answer:0,explanation:"추정가격 2천만원 이하 물품 제조·구매·임차 또는 용역 계약은 수의계약을 할 수 있습니다(시행령 제26조①5가2). 2천만원 초과 1억원 이하는 소기업·소상공인이나 여성·장애인·사회적기업 등과 체결하거나 특수한 지식·기술이 필요한 계약 등 정해진 경우에만 수의계약할 수 있습니다(같은 목 3)~5)).",basis:"국가계약법 시행령 제26조①5가",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제26조"},
{id:"P3-036",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"외자구매",ss:"3-2-1-5",tag:["물품"],difficulty:"상",question:"해외에서 물품을 들여오는 외자구매 절차에서 가장 먼저 해야 할 일은?",options:["납품 물품 검사","수요기관이 규격·예산·용도 등을 정해 조달을 요청","계약서 작성","대금 지급"],answer:1,explanation:"외자구매는 수요기관이 규격·배정예산·용도 등을 적어 나라장터로 조달을 요청하는 것에서 시작해, 구매규격 사전공개(5일 이상, 긴급하면 3일 이상) → 입찰·계약 → 납품 검사 → 대금 지급 순으로 진행합니다.",basis:"조달청 외자구매업무 처리규정 제11조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/조달청외자구매업무처리규정"},
{id:"P3-037",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"종합쇼핑몰",ss:"3-3-2-1",tag:["물품"],difficulty:"중",question:"나라장터 종합쇼핑몰을 통한 물품 구매에 대한 설명으로 옳은 것은?",options:["일반 국민이 개인 용도로 물품을 사는 쇼핑몰이다","매번 최저가 입찰을 거쳐야만 구매할 수 있다","조달청이 2인 이상과 체결한 다수공급자계약(MAS) 물품 등을 수요기관이 비교해 골라 주문한다","수의계약으로 체결된 물품만 올라와 있다"],answer:2,explanation:"다수공급자계약은 품질·성능이 비슷한 물품을 수요기관이 선택할 수 있도록 조달청장이 2인 이상과 체결하는 단가계약입니다(조달사업법 제13조①). 수요기관은 종합쇼핑몰에서 이를 골라 주문합니다.",basis:"조달사업법 제13조①",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률/제13조"},
{id:"P3-038",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"카탈로그계약",ss:"3-3-2-6",tag:["물품"],difficulty:"중",question:"「조달사업에 관한 법률 시행령」에 따른 카탈로그 계약의 운영 방식으로 옳은 것은?",options:["조달청이 최저가 입찰자 1인과만 계약하고, 수요기관은 그 업체 제품만 살 수 있다","조달청이 카탈로그 제시업체의 재무상태·납품실적·카탈로그 내용을 심사해 원칙적으로 2인 이상과 계약하고, 수요기관은 제안서 평가·협상을 거쳐 납품업체를 정한다","수요기관은 아무 절차 없이 카탈로그에 적힌 가격으로 원하는 업체에서 곧바로 구매한다","총공사비 300억원 이상 대형공사에 쓰는 계약방법이다"],answer:1,explanation:"카탈로그 계약은 조달청이 카탈로그 제시자를 심사해 2인 이상(일부 수요물자는 1인)을 계약상대자로 정하고, 수요기관이 제안서를 받아 평가·협상한 결과로 납품자를 결정하는 방식입니다(시행령 제16조②④).",basis:"조달사업법 시행령 제16조②③④",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률시행령/제16조"},
{id:"P3-039",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"납기 연장",ss:"3-1-3-3",tag:["물품"],difficulty:"중",question:"물품구매(제조)계약일반조건상 계약상대자가 계약기간 연장을 신청할 수 있는 사유로 보기 어려운 것은?",options:["태풍·지진 등 불가항력으로 제조가 중단된 경우","대체해 쓸 수 없는 중요 관급재료의 공급이 늦어져 공정이 멈춘 경우","발주기관의 설계도서 승인이 계획된 일정보다 늦어진 경우","계약상대자 공장의 인력 이탈 등 내부 사정으로 생산이 늦어진 경우"],answer:3,explanation:"계약기간 연장 사유는 제24조③ 각 호(불가항력, 중요 관급재료 공급 지연, 발주기관 책임에 따른 지연 등 계약상대자 책임 없는 사유)입니다(제25조①). 계약상대자 내부 사정은 여기에 해당하지 않습니다.",basis:"(계약예규) 물품구매(제조)계약일반조건 제25조①·제24조③",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
{id:"P3-040",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"규격 변경",ss:"3-2-2-2",tag:["물품"],difficulty:"중",question:"물품 계약에서 납품 물품의 규격을 바꾸는 것에 관한 설명으로 옳은 것은?",options:["계약상대자가 동등 이상 성능이라고 판단하면 발주기관과 협의 없이 다른 규격으로 납품할 수 있다","담당 공무원의 구두 승인만 있으면 문서 없이도 변경의 효력이 생긴다","물품은 계약상 규격을 충족해야 하므로, 규격 변경은 발주기관과 계약내용을 변경하는 방식으로 하고 금액은 실비 범위에서 조정한다","계약을 체결한 뒤에는 어떠한 사유로도 규격을 바꿀 수 없다"],answer:2,explanation:"납품 물품은 계약상 규격을 충족해야 하고(제13조①), 계약내용이 바뀌면 실비를 넘지 않는 범위에서 계약금액을 조정합니다(제11조의2①). 구두 승인·지시는 문서로 보완되어야 효력이 있습니다(제5조①).",basis:"(계약예규) 물품구매(제조)계약일반조건 제13조①·제11조의2①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
// ─── 용역·MAS 관리 ───
{id:"P3-041",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"용역 과업지시서",ss:"3-3-1-1",tag:["용역"],difficulty:"중",question:"용역계약일반조건상 용역 계약문서 가운데 수행할 업무의 범위와 내용을 정하는 핵심 문서는?",options:["과업내용서(과업지시서)","공사시방서","물량내역서","물품 규격서"],answer:0,explanation:"용역 계약문서는 계약서·유의서·일반조건·특수조건·과업내용서·산출내역서로 구성되며(제4조①), 업무 범위는 과업내용서가 정합니다. 시방서·물량내역서는 공사, 규격서는 물품의 문서입니다.",basis:"(계약예규) 용역계약일반조건 제4조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-042",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"용역 지체상금률",ss:"3-1-4-6",tag:["용역","숫자"],difficulty:"중",question:"국가계약법 시행규칙상 용역계약에 적용하는 1일 지체상금률은?",options:["1천분의 0.5 (0.05%)","1천분의 1.25 (0.125%)","1천분의 0.75 (0.075%)","1천분의 2.5 (0.25%)"],answer:1,explanation:"물품의 수리·가공·대여, 용역 및 기타 계약의 지체상금률은 1일 1천분의 1.25입니다(시행규칙 제75조 제3호).",basis:"국가계약법 시행규칙 제75조 제3호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-043",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"용역 하자보수",ss:"3-1-4-4",tag:["용역","숫자"],difficulty:"상",question:"용역계약일반조건상 소프트웨어용역의 하자보수보증금률은? (별도 법률에 따로 정한 경우는 제외)",options:["계약금액의 100분의 2","계약금액의 100분의 3","계약금액의 100분의 5","계약금액의 100분의 10"],answer:0,explanation:"용역계약일반조건 제4장(소프트웨어용역) 제59조①은 하자보수보증금률을 100분의 2로 정합니다. 하자보수 책임기간은 사업 종료 확인 후 1년입니다(제58조①).",basis:"(계약예규) 용역계약일반조건 제59조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-044",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"용역 협상계약 절차",ss:"3-3-1-5",tag:["용역"],difficulty:"중",question:"협상에 의한 계약체결기준상 협상 순위를 정하고 협상하는 절차로 옳은 것은?",options:["가장 낮은 가격을 낸 자를 협상 없이 곧바로 계약상대자로 정한다","기술능력 점수만으로 순위를 매겨 1위와 가격만 협상한다","기술능력 점수가 배점한도의 85% 이상인 자를 협상적격자로 하고, 기술·가격 합산점수가 높은 순서대로 협상해 성립하면 계약한다","협상적격자 전원과 동시에 협상한 뒤 가장 유리한 조건을 고른다"],answer:2,explanation:"예산(예정가격) 이하로 입찰하고 기술능력 점수가 배점한도의 85% 이상인 자가 협상적격자이며, 협상 순서는 기술·가격 평가점수 합산 순입니다(제8조①②). 우선순위자와 협상이 성립하면 다른 적격자와는 협상하지 않고, 결렬되면 차순위와 차례로 협상합니다(제10조).",basis:"(계약예규) 협상에 의한 계약체결기준 제8조①②·제10조",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P3-045",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"용역 중간보고",ss:"3-1-1-4",tag:["용역"],difficulty:"중",question:"용역을 수행하는 동안 발주기관에 보고하는 흐름으로 가장 일반적인 것은?",options:["용역을 끝낸 뒤 결과보고를 한 번만 한다","착수 → 중간 → 완료(최종) 단계로 나누어 보고한다","계약을 맺은 뒤에는 보고 의무가 전혀 없다","모든 보고를 구두로 하고 문서는 남기지 않는다"],answer:1,explanation:"용역은 착수 시 수행계획을 보고하고, 진행 중 중간보고, 종료 시 완료보고를 하는 것이 통상의 관리 흐름입니다. 착수 단계에서는 발주기관이 요구하면 공정예정표·인력투입계획을 담은 착수신고서를 내야 합니다(용역계약일반조건 제13조①).",basis:"(계약예규) 용역계약일반조건 제13조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-046",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"MAS 개요",ss:"3-3-2-2",tag:["MAS"],difficulty:"중",question:"조달사업법상 다수공급자계약(MAS)에 관한 설명으로 옳은 것은?",options:["최저가 1개 업체와만 계약해 모든 수요기관에 공급하게 한다","경쟁 절차 없이 조달청이 임의로 고른 업체와 계약한다","해외 조달물자 구매에만 쓰는 제도이다","품질·성능·효율이 같거나 비슷한 물자를 수요기관이 고를 수 있도록 2인 이상을 계약상대자로 하여 계약한다"],answer:3,explanation:"다수공급자계약은 조달청장이 같거나 비슷한 종류의 수요물자를 수요기관이 선택할 수 있도록 2인 이상을 계약상대자로 하여 체결하는 계약입니다(조달사업법 제13조①).",basis:"조달사업법 제13조①",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률/제13조"},
{id:"P3-048",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"MAS 2단계 예외",ss:"3-3-2-4",tag:["MAS"],difficulty:"상",question:"용역 다수공급자계약 업무처리규정상 수요기관의 장이 요청하면 조달청장이 2단계경쟁 예외를 허용할 수 있는 경우를 모두 고른 것은?\nㄱ. 재해복구에 필요한 용역을 긴급하게 구매하는 경우\nㄴ. 방역사업에 필요한 용역을 긴급하게 구매하는 경우\nㄷ. 2단계경쟁 회피가 아닌 명백한 사유가 있어 수요기관의 장이 예외를 요청하는 경우",options:["ㄱ, ㄴ, ㄷ","ㄱ, ㄴ","ㄱ, ㄷ","ㄴ, ㄷ"],answer:0,explanation:"제20조① 제1호는 재해복구·방역사업·이상기후 대응 용역의 긴급 구매를, 제2호는 회피 목적이 아닌 명백한 사유에 따른 요청을 예외 사유로 정하므로 셋 다 해당합니다.",basis:"용역 다수공급자계약 업무처리규정 제20조①",basisUrl:"https://www.law.go.kr/행정규칙/용역다수공급자계약업무처리규정"},
{id:"P3-049",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"MAS 적격성 평가",ss:"3-3-2-3",tag:["MAS"],difficulty:"중",question:"조달사업법 시행령상 다수공급자계약의 계약상대자를 정하는 방식으로 옳은 것은?",options:["입찰가격만 비교해 최저가 1인과 계약한다","납품실적만 보고 가격협상 없이 계약상대자를 정한다","재무상태·납품실적 등을 평가해 기준에 맞는 자를 고른 뒤 가격협상을 거쳐 낙찰자로 정한 2인 이상과 계약한다","수요기관마다 1개 업체만 지정해 계약한다"],answer:2,explanation:"조달청장은 입찰자의 재무상태·납품실적 등을 평가해 기준에 맞는 자를 선정하고, 가격협상으로 낙찰자가 된 2인 이상을 계약상대자로 정합니다(시행령 제13조①).",basis:"조달사업법 시행령 제13조①",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률시행령/제13조"},
{id:"P3-050",exam:"필기",subject:"공공계약관리",major:"용역·MAS 관리",sub:"MAS 실적 평가",ss:"3-3-2-5",tag:["MAS"],difficulty:"중",question:"물품 다수공급자계약 업무처리규정상 계약이행실적평가 결과의 쓰임으로 옳은 것은?",options:["신규 업체의 계약 참여를 막는 용도로만 쓴다","등급화한 결과를 종합쇼핑몰로 제공해 수요기관의 구매 판단을 돕고, 계약연장·재계약·2단계경쟁 평가 등에 활용한다","평가 등급에 따라 계약단가를 자동으로 올려 준다","우수 등급 업체는 2단계경쟁 대상에서 빠진다"],answer:1,explanation:"평가 결과는 등급화해 종합쇼핑몰로 수요기관에 제공할 수 있고, 계약연장·재계약·차기계약·입찰참가자격 사전심사·2단계경쟁 평가 등에 활용합니다(제41조①②). 등급은 최우수·우수·보통·미흡 4단계입니다(제44조②).",basis:"물품 다수공급자계약 업무처리규정 제41조①②",basisUrl:"https://www.law.go.kr/행정규칙/물품다수공급자계약업무처리규정"},
// ─── 공사계약관리 ───
{id:"P3-051",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"설계서",ss:"3-4-2-1",tag:["공사"],difficulty:"하",question:"공사 계약의 핵심 발주문서인 \"설계서\"를 이루는 문서로 옳게 묶은 것은? (공사계약일반조건 기준)",options:["공사시방서·설계도면·현장설명서·물량내역서","과업내용서·산출내역서","규격서·견품","제안요청서·제안서"],answer:0,explanation:"공사계약일반조건은 설계서를 공사시방서, 설계도면, 현장설명서, 공사기간 산정근거, 물량내역서로 정의하고(제2조 제4호), 설계서는 계약문서의 하나입니다(제3조①).",basis:"(계약예규) 공사계약일반조건 제2조 제4호·제3조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-052",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 지체상금률",ss:"3-1-4-6",tag:["공사","숫자"],difficulty:"중",question:"국가계약법 시행규칙상 공사계약의 1일 지체상금률은?",options:["1천분의 0.75","1천분의 1.25","1천분의 0.5","1천분의 1.5"],answer:2,explanation:"공사의 지체상금률은 1일 1천분의 0.5(0.05%)입니다(시행규칙 제75조 제1호).",basis:"국가계약법 시행규칙 제75조 제1호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-053",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 소액수의",ss:"1-2-4-2",tag:["공사","숫자"],difficulty:"중",question:"국가계약법 시행령상 건설산업기본법에 따른 종합공사를 소액수의계약으로 할 수 있는 추정가격 상한은?",options:["1억6천만원 이하","2억원 이하","2천만원 이하","4억원 이하"],answer:3,explanation:"종합공사는 추정가격 4억원 이하, 전문공사는 2억원 이하, 그 밖의 공사 관련 법령에 따른 공사는 1억6천만원 이하일 때 수의계약을 할 수 있습니다(시행령 제26조① 제5호 가목 1)).",basis:"국가계약법 시행령 제26조① 제5호 가목",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제26조"},
{id:"P3-054",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"준공검사",ss:"3-1-4-1",tag:["공사"],difficulty:"중",question:"공사계약일반조건상 준공검사에 관한 설명으로 옳은 것은?",options:["계약상대자가 준공신고만 하면 검사 없이 곧바로 준공대가를 지급한다","계약담당공무원은 준공 통지를 받은 날부터 원칙적으로 14일 이내에 계약서·설계서 등에 따라 계약상대자 입회하에 이행을 확인하는 검사를 해야 한다","검사는 계약상대자를 배제하고 발주기관 단독으로만 진행한다","검사 기간은 어떤 경우에도 연장할 수 없다"],answer:1,explanation:"준공 통지를 받으면 14일 이내에 계약서·설계서·준공신고서 등으로 계약상대자 입회하에 검사해야 하며, 불가항력이나 계약금액 100억원 이상 등 특별한 사유가 있으면 연장할 수 있습니다(제27조①②).",basis:"(계약예규) 공사계약일반조건 제27조①②",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-055",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 시공관리",ss:"3-4-3-3",tag:["공사"],difficulty:"중",question:"공사계약일반조건상 계약상대자가 안전·환경 및 품질관리계획서를 발주기관에 내는 시점은?",options:["착공할 때 착공신고서에 포함하여 제출","준공검사를 신청할 때","입찰공고 전 사전규격을 공개할 때","하자담보책임기간이 끝날 때"],answer:0,explanation:"착공 시 내는 착공신고서에는 안전·환경 및 품질관리계획서가 포함되어야 합니다(제17조① 제3호). 공사기간 30일 미만 등은 착공신고서 제출을 면제할 수 있습니다.",basis:"(계약예규) 공사계약일반조건 제17조① 제3호",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-056",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"안전관리",ss:"3-4-1-2",tag:["공사","숫자"],difficulty:"상",question:"건설기술 진흥법 시행령상 안전관리계획을 세워야 하는 건설공사에 해당하는 것은?",options:["총공사비 50억원 이상인 공사만 해당한다","추정가격 1억원 미만의 모든 소규모 공사","1종·2종 시설물의 건설공사(유지관리 공사 제외)","규모와 종류에 관계없이 모든 건설공사"],answer:2,explanation:"대상은 1종·2종 시설물 건설공사, 지하 10미터 이상 굴착공사, 10층 이상 16층 미만 건축물 공사 등 공사 종류로 정하며 공사금액 기준은 없습니다(시행령 제98조①).",basis:"건설기술 진흥법 시행령 제98조① 제1호",basisUrl:"https://www.law.go.kr/법령/건설기술진흥법시행령/제98조"},
{id:"P3-057",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 일괄입찰",ss:"3-4-3-2",tag:["공사"],difficulty:"상",question:"국가계약법 시행령상 일괄입찰(턴키)에 관한 설명으로 옳은 것은?",options:["정부가 실시설계를 끝낸 뒤 시공만 입찰에 부친다","추정가격 2억원 이하 단순 공사에 쓰는 수의계약 방식이다","정부 설계 중 대체 가능한 공종만 입찰자가 다른 설계를 낼 수 있게 하는 방식이다","입찰자가 정부의 기본계획·지침에 따라 설계서 등을 작성해 입찰서와 함께 내는 설계·시공 일괄입찰이다"],answer:3,explanation:"일괄입찰은 입찰 시 설계서 등 시공에 필요한 도서를 작성해 입찰서와 함께 제출하는 설계·시공 일괄입찰입니다(시행령 제79조① 제5호). 셋째 보기는 대안입찰(제4호)에 대한 설명입니다.",basis:"국가계약법 시행령 제79조① 제5호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제79조"},
{id:"P3-059",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 하자담보",ss:"3-1-4-4",tag:["공사","숫자"],difficulty:"중",question:"건설산업기본법상 하자담보책임기간이 가장 긴 것은?",options:["방수공사","철근콘크리트·철골 구조로서 구조내력에 해당하는 부분","일반 도장공사","타일 마감공사"],answer:1,explanation:"철근콘크리트·철골 등 구조내력에 해당하는 목적물은 10년, 그 밖의 경우는 5년 범위에서 공종별로 정합니다(건설산업기본법 제28조①, 시행령 제30조·별표 4).",basis:"건설산업기본법 제28조① 제1호",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제28조"},
{id:"P3-060",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 시공 일반",ss:"3-4-3-3",tag:["공사","종합"],difficulty:"상",question:"공사계약의 이행 단계(계약 체결부터 준공까지)에서 하는 활동이 아닌 것은?",options:["착공신고서 제출","기성부분 대가 청구","입찰공고 재공고","현장 안전관리 활동"],answer:2,explanation:"재공고입찰은 계약상대자를 정하기 전 단계의 일입니다. 착공신고서 제출(공사계약일반조건 제17조①), 기성대가 청구, 안전관리는 이행 단계 활동입니다.",basis:"(계약예규) 공사계약일반조건 제17조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
// ─── 하도급관리 ───
{id:"P3-061",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급 정의",ss:"3-4-3-5",tag:["하도급"],difficulty:"하",question:"건설산업기본법상 \"하도급\"의 뜻으로 옳은 것은?",options:["발주자가 인력을 직접 고용해 시공하는 것","여러 건설사업자가 공동수급체를 꾸려 함께 도급받는 것","계약서 없이 구두로 공사를 맡기는 것","도급받은 건설공사의 전부 또는 일부를 다시 도급하기 위해 수급인이 제3자와 맺는 계약"],answer:3,explanation:"하도급은 도급받은 건설공사의 전부 또는 일부를 다시 도급하기 위하여 수급인이 제3자와 체결하는 계약입니다(제2조 제12호).",basis:"건설산업기본법 제2조 제12호",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제2조"},
{id:"P3-062",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급 금지",ss:"3-4-3-5",tag:["하도급","숫자"],difficulty:"중",question:"건설산업기본법상 1건 공사금액이 (   ) 미만인 건설공사를 도급받은 건설사업자는 그 일부를 종합공사업을 등록한 건설사업자에게 하도급할 수 없다. 빈칸에 알맞은 것은?",options:["20억원","10억원","30억원","50억원"],answer:1,explanation:"1건 공사금액이 10억원 미만이면 그 일부를 종합공사를 시공하는 업종의 건설사업자에게 하도급할 수 없습니다(제29조④, 2018.12.31 신설).",basis:"건설산업기본법 제29조④",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제29조"},
{id:"P3-063",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"전부 하도급",ss:"3-4-3-5",tag:["하도급"],difficulty:"중",question:"건설산업기본법상 건설공사 하도급에 관한 설명으로 옳지 않은 것은?",options:["건설사업자는 도급받은 공사의 전부나 주요 부분의 대부분을 다른 건설사업자에게 하도급할 수 없다(법정 예외 제외)","공사 일부를 하도급한 건설사업자는 원칙적으로 발주자에게 그 사실을 통보해야 한다","하수급인은 하도급받은 공사를 원칙적으로 다른 사람에게 다시 하도급할 수 있다","수급인이 도급받은 전문공사는 원칙적으로 하도급할 수 없고, 발주자 서면 승낙 등 요건을 갖춘 경우에만 일부를 하도급할 수 있다"],answer:2,explanation:"하수급인의 재하도급은 원칙적으로 금지되고 법에 정한 경우에만 허용됩니다(제29조③). 나머지는 제29조①②⑥의 내용입니다.",basis:"건설산업기본법 제29조③",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제29조"},
{id:"P3-064",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"발주자 승인",ss:"3-1-1-5",tag:["하도급"],difficulty:"중",question:"종합공사를 도급받은 건설사업자가 그 공사의 일부를 하도급했을 때 발주자에 대해 원칙적으로 거쳐야 하는 절차는?",options:["하도급 전에 발주자의 서면 승낙을 반드시 받아야 한다","발주자에 대한 절차는 없고 원도급자가 단독으로 결정한다","공사를 마친 뒤 사후 보고로 갈음한다","하도급계약을 체결한 날부터 30일 이내에 발주자에게 통보한다"],answer:3,explanation:"하도급한 건설사업자는 하도급계약 체결일부터 30일 이내에 발주자에게 통보해야 하며, 감리자에게 기한 내 통보하면 발주자에게 통보한 것으로 봅니다(법 제29조⑥, 시행령 제32조①②). 서면 승낙은 전문공사 하도급·재하도급 등 예외적인 경우의 요건입니다.",basis:"건설산업기본법 제29조⑥, 같은 법 시행령 제32조①",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제29조"},
{id:"P3-066",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급 통보",ss:"3-4-3-5",tag:["하도급"],difficulty:"중",question:"국가기관이 발주한 건설공사에서 하도급 통보를 받은 발주자가 할 조치로 옳은 것은?",options:["하수급인이 현저히 부적당하거나 하도급금액이 기준 비율에 못 미치면 시공능력·계약내용의 적정성을 심사하고, 부적정하면 변경을 요구한다","통보를 받는 즉시 하수급인에게 하도급대금을 직접 지급한다","원도급 계약을 해지하고 하수급인과 직접 계약한다","발주자가 새 하수급인을 직접 고른다"],answer:0,explanation:"국가·지자체 등 발주자는 하수급인이 현저히 부적당하거나 하도급금액이 도급금액 중 해당 부분의 82% 또는 발주자 예정가격의 64%에 못 미치면 적정성을 심사해야 하고, 부적정하면 변경을 요구해야 합니다(법 제31조②③, 시행령 제34조①). 변경 요구는 통보를 받은 날 등부터 30일 이내에 서면으로 합니다(시행령 제34조③).",basis:"건설산업기본법 제31조②③",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제31조"},
{id:"P3-067",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급대금",ss:"3-4-3-5",tag:["하도급"],difficulty:"상",question:"건설산업기본법상 하도급대금 지급에 관한 설명으로 옳은 것은?",options:["하도급대금을 언제 줄지는 전적으로 수급인이 정한다","수급인은 준공금이나 기성금을 받은 날부터 15일 이내에 해당 금액을 하수급인에게 현금으로 지급해야 한다","기성금을 받은 날부터 60일 안에만 지급하면 된다","발주자에게 선급금을 받아도 하수급인에게 나눠 줄 의무는 없다"],answer:1,explanation:"수급인은 준공금·기성금을 받은 날부터 15일 이내에 하도급대금(기성금은 하수급인 시공분)을 현금으로 지급해야 하고, 선급금도 받은 날부터 15일 이내에 비율에 따라 지급해야 합니다(제34조①④).",basis:"건설산업기본법 제34조①",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제34조"},
{id:"P3-068",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"공사용자재 직접구매",ss:"1-4-1-3",tag:["하도급"],difficulty:"중",question:"판로지원법상 공사용 자재 직접구매 제도에 관한 설명으로 옳은 것은?",options:["공사용 자재를 하도급 단계를 여러 번 거쳐 구매하도록 하는 제도이다","대기업 자재의 공공 납품을 보호하는 제도이다","외국산 자재의 공공시장 진입을 늘리는 제도이다","공공기관이 중소기업자간 경쟁제품 중 고시된 공사용 자재를 직접 구매해 공사에 관급자재로 제공하는 제도이다"],answer:3,explanation:"중소벤처기업부장관이 경쟁제품 중 직접구매에 적합한 공사용 자재를 고시하고, 일정 규모 이상 공사를 발주하는 공공기관은 직접구매를 검토·조치해야 합니다(법 제12조②③). 종합공사는 추정가격 40억원 이상이 대상이며, 해당 품목이 4천만원 이상이면 관급자재로 설계에 반영해 직접 구매합니다(시행령 제11조).",basis:"판로지원법 제12조②③",basisUrl:"https://www.law.go.kr/법령/중소기업제품구매촉진및판로지원에관한법률/제12조"},
{id:"P3-069",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급 분쟁",ss:"3-1-2-5",tag:["하도급"],difficulty:"상",question:"하도급거래에서 원사업자와 수급사업자 사이의 분쟁 해결에 관한 설명으로 옳은 것은?",options:["하도급 분쟁은 법원 소송 말고는 해결할 방법이 없다","분쟁의 결론은 원사업자가 단독으로 정한다","한국공정거래조정원 등에 설치된 하도급분쟁조정협의회에 조정을 신청할 수 있다","하도급 분쟁은 조달청 계약심의위원회가 최종 결정한다"],answer:2,explanation:"원사업자·수급사업자는 하도급거래 분쟁에 대해 하도급분쟁조정협의회에 조정을 신청할 수 있습니다(하도급법 제24조의4①). 협의회는 한국공정거래조정원에 두고, 사업자단체도 공정거래위원회 승인을 받아 설치할 수 있습니다(제24조①②). 하도급법이 적용되지 않는 건설 하도급 분쟁은 건설분쟁 조정위원회가 다룹니다(건설산업기본법 제69조③).",basis:"하도급법 제24조의4①",basisUrl:"https://www.law.go.kr/법령/하도급거래공정화에관한법률/제24조의4"},
{id:"P3-070",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급 종합",ss:"3-4-3-5",tag:["하도급","종합"],difficulty:"상",question:"건설산업기본법상 건설공사 하도급에 관한 종합 설명으로 옳지 않은 것은?",options:["수급인은 도급받은 공사 전부를 다른 건설사업자 1인에게 하도급할 수 있다","하수급인의 재하도급은 원칙적으로 금지된다","하도급계약을 체결하면 원칙적으로 30일 이내에 발주자에게 통보해야 한다","1건 공사금액 10억원 미만인 공사는 그 일부를 종합공사업 등록 건설사업자에게 하도급할 수 없다"],answer:0,explanation:"도급받은 공사의 전부(또는 주요 부분의 대부분)를 하도급하는 것은 금지되며, 계획·관리·조정하면서 2인 이상에게 나누어 하도급하는 경우만 예외입니다(제29조①). 나머지는 제29조③④⑥, 시행령 제32조①의 내용입니다.",basis:"건설산업기본법 제29조①",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제29조"},
// ─── 지체상금 ───
{id:"P3-071",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"지체상금 일반",ss:"3-1-4-6",tag:["지체상금"],difficulty:"중",question:"국가계약법 시행령상 지체상금에 관한 설명으로 옳지 않은 것은?",options:["계약상대자가 계약상 의무 이행을 지체하면 부과한다","계약금액 × 지체상금률 × 지체일수로 계산한다","부과액은 계약금액의 100분의 30을 넘을 수 없다","천재지변처럼 계약상대자 책임이 없는 사유로 늦어진 일수도 지체일수에 넣는다"],answer:3,explanation:"계약상대자의 책임 없는 사유로 지체된 일수는 지체일수에 산입하지 않습니다(제74조① 후단). 상한은 계약금액의 100분의 30입니다(제74조③).",basis:"국가계약법 시행령 제74조①③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제74조"},
{id:"P3-074",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"용역 지체상금률",ss:"3-1-4-6",tag:["지체상금","숫자"],difficulty:"중",question:"국가계약법 시행규칙상 물품의 수리·가공·대여 계약에 적용하는 1일 지체상금률은?",options:["1천분의 0.5","1천분의 0.75","1천분의 1.25","1천분의 2.5"],answer:2,explanation:"물품의 수리·가공·대여는 용역·기타 계약과 같이 1일 1천분의 1.25(0.125%)입니다(시행규칙 제75조 제3호).",basis:"국가계약법 시행규칙 제75조 제3호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-075",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"군용 지체상금률",ss:"3-1-4-6",tag:["지체상금","숫자"],difficulty:"상",question:"국가계약법 시행규칙상 군용 음·식료품 제조·구매 계약의 1일 지체상금률은?",options:["1천분의 1.5","1천분의 0.75","1천분의 1.25","1천분의 2.5"],answer:0,explanation:"군용 음·식료품 제조·구매는 1일 1천분의 1.5(0.15%)입니다(시행규칙 제75조 제4호).",basis:"국가계약법 시행규칙 제75조 제4호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-076",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"운송 지체상금률",ss:"3-1-4-6",tag:["지체상금","숫자"],difficulty:"상",question:"국가계약법 시행규칙상 지체상금률이 가장 높은 운송·보관 및 양곡가공 계약의 1일 요율은?",options:["1천분의 1.25","1천분의 2.5","1천분의 1.5","1천분의 0.75"],answer:1,explanation:"운송·보관 및 양곡가공은 1일 1천분의 2.5(0.25%)로 지체상금률 가운데 가장 높습니다(시행규칙 제75조 제5호).",basis:"국가계약법 시행규칙 제75조 제5호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-077",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"지체상금 한도",ss:"3-1-4-6",tag:["지체상금","숫자"],difficulty:"중",question:"국가계약법 시행령상 계약상대자가 납부할 지체상금의 상한은?",options:["계약금액의 100분의 10","계약금액의 100분의 20","계약금액의 100분의 50","계약금액의 100분의 30"],answer:3,explanation:"지체상금이 계약금액(검사·인수한 기성·기납부분 금액은 공제)의 100분의 30을 넘으면 100분의 30으로 합니다(시행령 제74조③).",basis:"국가계약법 시행령 제74조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제74조"},
{id:"P3-078",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"지체상금 계산",ss:"3-1-4-6",tag:["지체상금","계산"],difficulty:"중",question:"계약금액 1억원인 일반 물품 구매계약(설계·제조 일괄 승인 대상 아님)의 납품이 계약상대자 책임으로 8일 늦어졌다. 지체상금은?",options:["400,000원","800,000원","600,000원","1,000,000원"],answer:2,explanation:"물품 제조·구매의 지체상금률은 1일 1천분의 0.75이므로 100,000,000원 × 0.75/1,000 × 8일 = 600,000원입니다(시행령 제74조①, 시행규칙 제75조 제2호).",basis:"국가계약법 시행령 제74조①, 시행규칙 제75조 제2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-079",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"지체상금 계산 공사",ss:"3-1-4-6",tag:["지체상금","계산"],difficulty:"상",question:"계약금액 5억원인 공사의 준공이 계약상대자 책임으로 10일 늦어졌다. 지체상금은?",options:["2,500,000원","1,250,000원","3,750,000원","5,000,000원"],answer:0,explanation:"공사의 지체상금률은 1일 1천분의 0.5이므로 500,000,000원 × 0.5/1,000 × 10일 = 2,500,000원입니다(시행령 제74조①, 시행규칙 제75조 제1호).",basis:"국가계약법 시행령 제74조①, 시행규칙 제75조 제1호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제75조"},
{id:"P3-080",exam:"필기",subject:"공공계약관리",major:"지체상금",sub:"지체상금 면제",ss:"3-1-4-6",tag:["지체상금"],difficulty:"중",question:"공사 이행이 늦어졌더라도 그 기간을 지체일수에서 빼 주어 지체상금을 물리지 않는 사유에 해당하는 것은?",options:["계약상대자의 운영자금이 부족해 자재 구매가 늦어진 경우","태풍·지진 등 계약당사자 누구의 책임도 아닌 불가항력으로 공사가 지연된 경우","하수급인의 인력 수급이 원활하지 않아 공정이 밀린 경우","계약상대자가 다른 현장에 장비를 먼저 투입해 착수가 늦어진 경우"],answer:1,explanation:"계약상대자에게 책임이 없는 사유로 지체된 날수는 지체일수에 넣지 않으며, 공사계약일반조건은 그 첫째 사유로 불가항력(태풍·홍수·지진·전쟁 등)을 든다. 자금·인력·장비 운용 문제는 계약상대자 책임이다.",basis:"국가계약법 시행령 제74조①; (계약예규) 공사계약일반조건 제25조③·제32조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제74조"},
// ─── 보증금 종합 ───
{id:"P3-082",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"일반 계약보증금",ss:"3-1-4-5",tag:["보증금","숫자"],difficulty:"중",question:"물품이나 용역 계약을 맺을 때 계약상대자에게 납부하게 하는 계약보증금의 원칙적인 비율은?",options:["계약금액의 10% 이상","계약금액의 5% 이상","계약금액의 15% 이상","계약금액의 20% 이상"],answer:0,explanation:"계약보증금은 계약금액의 100분의 10 이상이 원칙이다. 5%는 재난·경제위기로 재정경제부장관이 기간을 정해 고시한 경우에만 허용되는 예외다.",basis:"국가계약법 시행령 제50조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제50조"},
{id:"P3-083",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"공사 계약보증금",ss:"3-1-4-5",tag:["보증금","숫자"],difficulty:"중",question:"공사계약에서 계약상대자가 이행보증 방법으로 '계약보증금 납부'를 선택했을 때 원칙적으로 납부해야 하는 금액은?",options:["계약금액의 5% 이상","계약금액의 40% 이상","계약금액의 10% 이상","계약금액의 20% 이상"],answer:2,explanation:"공사도 물품·용역과 같이 계약보증금은 계약금액의 100분의 10 이상이다(시행령 제50조①). 40%는 계약보증금 대신 제출하는 공사이행보증서의 보증 비율이다(시행령 제52조①).",basis:"국가계약법 시행령 제50조①, 제52조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제50조"},
{id:"P3-084",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"공사이행보증서",ss:"3-1-4-5",tag:["보증금","숫자"],difficulty:"중",question:"예정가격의 70% 이상으로 낙찰된 공사에서 계약보증금 대신 공사이행보증서를 낸다면, 보증기관이 납부를 보증해야 하는 금액은 원칙적으로 얼마 이상인가?",options:["계약금액의 20%","계약금액의 30%","계약금액의 50%","계약금액의 40%"],answer:3,explanation:"공사이행보증서는 보증기관이 이행하지 못하면 계약금액의 100분의 40 이상을 납부하겠다고 보증하는 것이어야 한다. 20%는 경제위기 고시 기간의 예외, 50%는 저가낙찰 공사에 적용된다.",basis:"국가계약법 시행령 제52조①2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제52조"},
{id:"P3-085",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"저가낙찰 이행보증",ss:"3-1-4-5",tag:["보증금","숫자"],difficulty:"상",question:"예정가격의 70%에 못 미치는 금액으로 낙찰된 공사에서 공사이행보증서로 이행을 보증하려 할 때, 보증 금액의 원칙적인 기준은?",options:["계약금액의 40% 이상","계약금액의 50% 이상","계약금액의 60% 이상","계약금액의 70% 이상"],answer:1,explanation:"저가로 낙찰된 공사(예정가격의 100분의 70 미만)는 부실 위험을 고려해 공사이행보증 비율을 100분의 40에서 100분의 50으로 높여 적용한다.",basis:"국가계약법 시행령 제52조①2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제52조"},
{id:"P3-086",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"선금 한도",ss:"3-1-4-2",tag:["보증금","숫자"],difficulty:"중",question:"계약상대자가 선금 지급을 요청할 때, 계약담당공무원이 지급할 수 있는 선금의 전체 한도는?",options:["계약금액의 30%","계약금액의 50%","계약금액의 100%","계약금액의 70%"],answer:3,explanation:"선금은 계약금액의 100분의 70을 넘지 않는 범위에서 지급할 수 있다. 30·40·50%는 최초 신청 때 14일 이내 지급해야 하는 규모별 금액일 뿐 전체 한도가 아니다.",basis:"(계약예규) 정부 입찰·계약 집행기준 제34조①",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-087",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"선급금보증금",ss:"3-1-4-5",tag:["보증금"],difficulty:"중",question:"선금을 지급할 때 확보해야 하는 채권(보증)에 관한 설명으로 옳은 것은?",options:["선금은 보증 없이 지급하는 것이 원칙이고 보증은 계약상대자가 원할 때만 받는다","보증보험증권은 인정되지 않고 현금으로만 담보를 제공해야 한다","원칙적으로 선금액에 약정이자상당액을 더한 금액 이상을 보증하는 증권이나 보증서를 제출하게 한다","선금액의 절반만 보증하면 나머지는 계약보증금으로 대신한다"],answer:2,explanation:"선금을 줄 때는 시행령 제37조②의 증권·보증서(보증보험증권 포함)를 받아야 하고, 보증금액은 선금액에 약정이자상당액을 가산한 금액 이상이어야 한다. 다만 국가·지방자치단체·공기업·준정부기관 등과의 계약은 예외다.",basis:"(계약예규) 정부 입찰·계약 집행기준 제35조①②",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)정부입찰ㆍ계약집행기준"},
{id:"P3-088",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"하자보수보증금 - 물품/용역",ss:"3-1-4-5",tag:["보증금","숫자"],difficulty:"상",question:"조달청이 물품·용역 계약에서 하자보수보증이 필요하다고 보아 하자보수보증금을 받을 때 적용하는 비율로 옳은 것은?",options:["물품 계약금액의 3% / 용역 계약금액의 2%","물품 계약금액의 2% / 용역 계약금액의 3%","물품·용역 모두 계약금액의 5%","물품·용역 모두 계약금액의 10%"],answer:0,explanation:"조달청 내자구매업무 처리규정은 하자보수보증이 필요한 경우 물품은 계약금액의 100분의 3, 용역은 100분의 2를 하자보수보증금으로 납부하게 할 수 있다고 정한다.",basis:"조달청 내자구매업무 처리규정 제59조①",basisUrl:"https://www.law.go.kr/행정규칙/조달청내자구매업무처리규정"},
{id:"P3-089",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"보증금 종합",ss:"3-1-4-5",tag:["보증금","종합"],difficulty:"상",question:"국가계약에서 각 보증금의 원칙적인 비율을 짝지은 것 중 옳지 않은 것은?",options:["입찰보증금 - 입찰금액의 5% 이상","계약보증금 - 계약금액의 10% 이상","공사이행보증서 - 계약금액의 40% 이상","예정가격 70% 미만 낙찰 공사의 공사이행보증서 - 계약금액의 70% 이상"],answer:3,explanation:"저가낙찰(예정가격의 100분의 70 미만) 공사의 공사이행보증 비율은 100분의 50 이상이다. 입찰보증금 5%, 계약보증금 10%, 공사이행보증서 40%는 원문과 같다.",basis:"국가계약법 시행령 제37조①, 제50조①, 제52조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제52조"},
{id:"P3-090",exam:"필기",subject:"공공계약관리",major:"보증금 종합",sub:"보증금 납부 방법",ss:"3-1-4-5",tag:["보증금"],difficulty:"중",question:"입찰보증금이나 계약보증금을 납부하는 수단으로 인정되지 않는 것은?",options:["보험회사가 발행한 보증보험증권","계약상대자 대표이사 개인의 연대보증 각서","금융기관이 발행한 지급보증서","현금(은행 발행 자기앞수표 포함)"],answer:1,explanation:"보증금은 현금 또는 금융기관 지급보증서, 보증보험증권, 공제조합 등의 보증서, 정기예금증서 등 시행령 제37조②에 열거된 보증서등으로 내야 한다. 대표자 개인의 연대보증은 열거되어 있지 않다.",basis:"국가계약법 시행령 제37조②, 제50조⑦",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제37조"},
// ─── 공공계약(국가 및 지방)법령 ───
{id:"P1-091",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"추정가격·예정가격",ss:"1-5-2-1",tag:["법령","가격"],difficulty:"중",question:"추정가격과 예정가격에 관한 설명으로 옳지 않은 것은?",options:["예정가격은 입찰자에게 사전 공개하여 경쟁을 촉진한다","추정가격은 부가가치세를 제외한 예상 금액이다","예정가격은 낙찰자 결정의 기준이 된다","추정가격은 계약 방법 결정의 기준이 된다"],answer:0,explanation:"예정가격은 담합 방지를 위해 사전 비공개가 원칙이며 개찰 시 공개됩니다."},
{id:"P1-092",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"입찰·낙찰 절차",ss:"1-5-2-3",tag:["법령","절차"],difficulty:"중",question:"국가계약법령상 입찰·낙찰 절차에 관한 설명으로 옳지 않은 것은?",options:["입찰공고는 나라장터를 통해 게시한다","입찰보증금은 낙찰 후 무조건 반환된다","낙찰자 결정 방법은 공고 시 명시한다","무효입찰 사유는 법령에 명시되어 있다"],answer:1,explanation:"낙찰 후 미계약 시 입찰보증금은 국고 귀속되므로 무조건 반환되지 않습니다."},
{id:"P1-093",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"계약체결·이행",ss:"1-5-2-4",tag:["법령"],difficulty:"중",question:"국가계약법령상 계약체결에 관한 설명으로 옳은 것은?",options:["계약서는 구두 합의로 갈음할 수 있다","낙찰자 결정 즉시 계약이 성립한다","발주기관장 단독 서명만으로 계약이 성립한다","계약서에 담당공무원과 계약상대자가 기명·날인하거나 서명함으로써 계약이 확정된다"],answer:3,explanation:"계약서를 작성하는 경우 담당공무원과 계약상대자가 계약서에 기명·날인하거나 서명함으로써 계약이 확정됩니다.",basis:"국가계약법 제11조 제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제11조"},
{id:"P1-094",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"이의신청·분쟁조정",ss:"1-5-2-5",tag:["법령","분쟁"],difficulty:"상",question:"공공조달 이의신청 및 분쟁조정에 관한 설명으로 옳지 않은 것은?",options:["조정 결정에는 불복할 수 없다","발주기관에 서면으로 이의를 제기할 수 있다","국가계약분쟁조정위원회에서 조정 가능하다","이의신청 가능 기간이 법령으로 정해져 있다"],answer:0,explanation:"조정 완료 후 15일 이내에 이의를 제기하면 재판상 화해 효력이 생기지 않으므로, 소송(민사소송 등)으로 다툴 수 있습니다. 그래서 \"불복할 수 없다\"는 틀립니다.",basis:"국가계약법 제31조 제3항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제31조"},
{id:"P1-095",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"계약 방법 규정",ss:"1-5-2-2",tag:["법령","계약"],difficulty:"중",question:"국가계약법령상 계약방법 결정의 일반 원칙은?",options:["수의계약을 원칙으로 한다","제한경쟁을 원칙으로 한다","지명경쟁을 원칙으로 한다","일반경쟁을 원칙으로 한다"],answer:3,explanation:"공공계약은 일반경쟁을 원칙으로 하고 사유가 있을 때만 다른 방법을 적용합니다."},
{id:"P1-096",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"지방계약법",ss:"1-1-1-3",tag:["법령","지방"],difficulty:"상",question:"지방계약법에 관한 설명으로 옳지 않은 것은?",options:["지방자치단체가 당사자인 계약에 적용된다","국가계약법과 별도의 법령이다","지방재정의 효율적 집행을 목적으로 한다","국가계약법과 내용이 전혀 다르다"],answer:3,explanation:"지방계약법은 국가계약법과 큰 틀이 유사하며 일부 차이만 있습니다."},
// ─── 조달사업법령 ───
{id:"P1-097",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"조달사업법-대금지급",ss:"1-5-3-3",tag:["법령","조달사업"],difficulty:"중",question:"국가계약법령상 대가 지급에 관한 설명으로 옳지 않은 것은?",options:["검사를 마친 후 계약상대자의 청구를 받은 날부터 5일 이내 지급이 원칙이다","청구 후 무기한 지급이 허용된다","지연 시 지연이자가 발생한다","불가항력 시에는 사유 소멸 후 3일 이내 지급한다"],answer:1,explanation:"대가는 검사를 마친 후 계약상대자의 청구를 받은 날부터 5일 이내에 지급해야 하고, 불가항력으로 늦어지면 사유가 없어진 날부터 3일 이내에 지급합니다. 늦으면 지연이자를 줍니다. 무기한 지급은 허용되지 않습니다.",basis:"국가계약법 시행령 제58조 제1항·제2항, 제59조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제58조"},
{id:"P1-098",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"조달사업법-수요기관 지원",ss:"1-5-3-5",tag:["법령","조달사업"],difficulty:"중",question:"조달사업법령상 수요기관 지원과 관련된 조달청 업무로 보기 어려운 것은?",options:["수요기관 대신 계약 체결","조달물자 비축 및 공급","조달정보 시스템 제공","수요기관 직원 인사 관리"],answer:3,explanation:"수요기관 직원 인사 관리는 조달청의 업무 영역이 아닙니다."},
{id:"P1-099",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"조달사업법-공정성",ss:"1-5-3-4",tag:["법령","조달사업"],difficulty:"중",question:"조달사업법령상 조달사업의 공정성 확보를 위한 제도가 아닌 것은?",options:["부정당업자 제재","이해충돌 평가위원 회피","청렴계약제 운영","조달업체 영업비밀 공개 의무화"],answer:3,explanation:"조달업체 영업비밀 공개 의무화는 오히려 공정한 경쟁을 저해할 수 있어 공정성 확보 제도가 아닙니다."},
{id:"P1-100",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"조달사업법-정책기반",ss:"1-5-3-1",tag:["법령","조달사업"],difficulty:"상",question:"조달사업법령상 공공조달의 정책기반에 해당하지 않는 것은?",options:["민간기업 지배구조 개입","전략적 조달 추진","사회적 가치 실현","공공구매 효율성 제고"],answer:0,explanation:"민간기업 지배구조 개입은 정책기반이 아니며 오히려 공공조달이 회피해야 할 사항입니다."},
// ─── 전자조달법령 ───
{id:"P1-101",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"전자조달법-전자공고",ss:"1-5-4-1",tag:["법령","전자조달"],difficulty:"중",question:"전자조달법령상 전자적 공고에 관한 설명으로 옳은 것은?",options:["입찰 공고는 종이 신문에만 게재해야 한다","전자조달시스템을 통해 공고하는 것이 원칙이다","공고 기간 규정은 없다","수의계약은 공고하지 않는다"],answer:1,explanation:"전자조달법령상 입찰공고는 나라장터 등 전자조달시스템을 통해 공고하는 것이 원칙입니다."},
{id:"P1-103",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"전자조달법-하도급 전자처리",ss:"1-5-4-4",tag:["법령","전자조달"],difficulty:"중",question:"하도급 관리의 전자적 처리에 관한 설명으로 옳은 것은?",options:["하수급인에게 발주자가 직접 지급한다","하도급지킴이 같은 전자적 대금지급시스템으로 하도급대금의 청구·승인·지급을 처리한다","하도급 전자처리는 의무가 아니다","하도급 정보는 비공개로 처리한다"],answer:1,explanation:"하도급지킴이는 하도급대금의 청구·승인·지급을 전자로 처리하고 수요기관이 이를 확인할 수 있게 하는 전자적 대금지급시스템입니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 제9조의2",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률/제9조의2"},
{id:"P1-104",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"전자조달법-이용제한",ss:"1-5-4-5",tag:["법령","전자조달"],difficulty:"상",question:"전자조달시스템 이용·활용 제한 사유에 해당하는 것은?",options:["입찰 참가 횟수가 적은 자","부정당업자 제재 처분을 받은 자","납품 실적이 부족한 자","사업장이 지방에 있는 자"],answer:1,explanation:"부정당업자 제재 처분을 받으면 일정 기간 전자조달시스템 이용이 제한될 수 있습니다."},
// ─── 공기업·준정부기관 계약사무규칙 ───
{id:"P1-105",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"공기업-수의계약 규정",ss:"1-5-5-3",tag:["법령","공기업"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙상 수의계약 가능 사유가 아닌 것은?",options:["2인 이상 입찰자가 있어 경쟁이 가능한 경우","천재지변으로 긴급한 필요가 있는 경우","추정가격이 일정 금액 미만인 소액","특허권 등으로 특정인만 공급 가능"],answer:0,explanation:"경쟁이 가능한 경우는 수의계약이 아닌 경쟁입찰 원칙을 따라야 합니다."},
{id:"P1-106",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"공기업-국제입찰",ss:"1-5-5-1",tag:["법령","공기업"],difficulty:"상",question:"공기업·준정부기관 국제입찰 대상 공공조달계약 범위에 관한 설명으로 옳은 것은?",options:["모든 계약은 국내입찰만 가능하다","공기업은 국제입찰을 할 수 없다","일정 금액 이상의 계약은 국제입찰을 적용할 수 있다","외국 기업만 참여 가능하다"],answer:2,explanation:"공기업·준정부기관도 일정 금액 이상 계약에 대해 국제입찰을 적용할 수 있습니다."},
{id:"P1-107",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"공기업-이의신청",ss:"1-5-5-5",tag:["법령","공기업"],difficulty:"상",question:"공기업·준정부기관 계약사무규칙상 이의신청에 관한 설명으로 옳은 것은?",options:["이의신청은 절대 불가하다","공기업은 이의신청 의무가 없다","이의신청 절차가 마련되어 있다","이의신청은 구두로만 가능하다"],answer:2,explanation:"공기업·준정부기관도 이의신청 절차가 규정되어 있으며 서면이 원칙입니다."},
// ─── 목록정보시스템 ───
{id:"P1-108",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"목록정보-물품목록법령",ss:"1-3-3-1",tag:["전자조달","목록"],difficulty:"중",question:"물품목록법령의 주요 내용으로 옳지 않은 것은?",options:["물품의 분류·품명·품목을 표준화한다","목록정보시스템 운영의 법적 근거를 제공한다","민간기업 제품 가격을 통제한다","국제 표준분류체계 연계의 근거가 된다"],answer:2,explanation:"물품목록법령은 분류·표준화 근거이며 가격 통제는 그 범위가 아닙니다."},
{id:"P1-109",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"목록정보-이용절차",ss:"1-3-3-2",tag:["전자조달","목록"],difficulty:"중",question:"목록정보시스템 이용 일반절차에 관한 설명으로 옳은 것은?",options:["물품 등록 신청 → 분류·품명 검토 → 품목번호 부여 → 등록 완료","등록 즉시 자동 승인","민간 가격 협상 후 등록","수의계약과 통합된 별도 절차"],answer:0,explanation:"목록정보시스템은 신청 → 검토 → 품목번호 부여 → 등록 절차를 따릅니다."},
{id:"P1-110",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"목록정보-국제표준화",ss:"1-3-3-6",tag:["전자조달","목록"],difficulty:"상",question:"목록정보시스템 활용 분류체계 국제 표준화의 의의로 옳은 것은?",options:["민간 거래 차단","해외 진출 제한","국제 거래 호환성·정보 교환 효율성 제고","조달 정보 비공개화"],answer:2,explanation:"국제 표준화는 국제 거래의 호환성과 정보 교환 효율성을 높이기 위함입니다."},
// ─── 공사계약 일반개요 ───
{id:"P3-091",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"건설산업기본법",ss:"3-4-1-1",tag:["법령","공사"],difficulty:"중",question:"건설산업기본법이 정하는 내용으로 보기 어려운 것은?",options:["업종별 건설업 등록","도급받은 건설공사의 하도급 제한","건설회사 임직원의 인사평가 기준","종합공사와 전문공사의 구분"],answer:2,explanation:"건설산업기본법은 건설업 등록(제9조), 종합·전문공사 정의(제2조), 하도급 제한(제29조) 등 건설공사의 도급과 시공에 관한 사항을 정한다. 회사 내부의 인사평가는 규율 대상이 아니다.",basis:"건설산업기본법 제1조, 제2조, 제9조, 제29조",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제1조"},
{id:"P3-092",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"건설기술진흥법",ss:"3-4-1-2",tag:["법령","공사"],difficulty:"중",question:"건설기술 진흥법의 목적에 비추어 이 법이 다루는 내용으로 옳은 것은?",options:["건설기술의 연구·개발 촉진과 건설공사의 품질·안전 확보","기업 영업비밀의 부정 취득 방지","국가공무원의 임용과 보수","조달청의 조직과 정원"],answer:0,explanation:"건설기술 진흥법은 건설기술의 연구·개발을 촉진해 기술 수준을 높이고, 건설공사의 품질을 높이며 안전을 확보하는 것을 목적으로 한다.",basis:"건설기술 진흥법 제1조",basisUrl:"https://www.law.go.kr/법령/건설기술진흥법/제1조"},
{id:"P3-093",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"건설공사 발주 세부기준",ss:"3-4-1-3",tag:["법령","공사"],difficulty:"상",question:"국토교통부 고시인 「건설공사 발주 세부기준」에서 정하는 내용이 아닌 것은?",options:["건설공사를 종합공사와 전문공사로 구분하는 기준","부대공사의 범위와 판단 기준","종합공사·전문공사의 시공자격","시공업체의 영업이익률 상한"],answer:3,explanation:"이 고시는 건설산업기본법에 따른 부대공사의 범위·기준과 종합·전문공사의 구분, 시공자격, 발주방식 등을 정한다. 업체의 이익률을 통제하는 규정은 없다.",basis:"건설공사 발주 세부기준 제1조, 제4조~제7조",basisUrl:"https://www.law.go.kr/행정규칙/건설공사발주세부기준"},
{id:"P3-094",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 일반개요-종합",ss:"3-4-1-3",tag:["법령","공사"],difficulty:"중",question:"공사계약과 관련된 법령·기준과 그 규율 내용의 연결로 옳지 않은 것은?",options:["국가계약법 - 국가가 당사자가 되는 계약의 기본 사항","건설공사 발주 세부기준 - 건설자재의 민간 거래가격 결정","건설기술 진흥법 - 건설기술 연구·개발 촉진과 공사 품질·안전 확보","건설산업기본법 - 건설업 등록과 건설공사 하도급 제한"],answer:1,explanation:"건설공사 발주 세부기준은 발주자가 건설공사를 발주할 때 종합·전문공사 구분, 부대공사 범위, 시공자격 등을 판단하는 기준이며 민간 가격을 정하지 않는다.",basis:"건설공사 발주 세부기준 제1조; 국가계약법 제1조",basisUrl:"https://www.law.go.kr/행정규칙/건설공사발주세부기준"},
// ─── 공사계약 특화 절차 ───
{id:"P3-095",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"일괄입찰",ss:"3-4-3-2",tag:["공사","입찰"],difficulty:"중",question:"국가계약법 시행령상 일괄입찰(턴키)에 대한 설명으로 옳은 것은?",options:["입찰자가 정부가 제시한 기본계획·지침에 따라 설계서 등 시공에 필요한 도서를 작성해 입찰서와 함께 제출한다","정부가 실시설계를 모두 마친 뒤 시공만을 대상으로 입찰에 부친다","주로 소규모의 단순 공종 공사에 쓰인다","경쟁 없이 특정 업체와 맺는 수의계약의 한 형태이다"],answer:0,explanation:"일괄입찰은 정부가 제시한 공사일괄입찰기본계획·지침에 따라 입찰자가 설계서와 시공 도서를 작성해 입찰서와 함께 내는 설계·시공 일괄입찰이다.",basis:"국가계약법 시행령 제79조①5호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제79조"},
{id:"P3-096",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"대안입찰",ss:"3-4-3-2",tag:["공사","입찰"],difficulty:"중",question:"공사 대안입찰에 관한 설명으로 옳지 않은 것은?",options:["원안입찰과 함께 입찰자의 의사에 따라 대안을 낼 수 있도록 허용된 공사의 입찰이다","대안은 정부 설계와 동등 이상의 기능·효과를 가지면서 가격이 더 낮고 공사기간이 원안을 넘지 않아야 한다","규모와 관계없이 모든 공사를 대안입찰로 발주해야 한다","대형공사 등의 입찰방법은 중앙건설기술심의위원회 심의를 거친다"],answer:2,explanation:"대안입찰은 대형공사(300억원 이상)나 특정공사 중 심의를 거쳐 정해진 공사에 적용하는 방식이지 모든 공사에 의무적인 것이 아니다.",basis:"국가계약법 시행령 제79조①3호·4호, 제80조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제79조"},
{id:"P3-097",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"기술제안입찰",ss:"3-4-3-2",tag:["공사","입찰"],difficulty:"상",question:"공사 기술제안입찰에 관한 설명으로 옳은 것은?",options:["입찰가격만 비교해 가장 낮은 가격을 낸 자를 낙찰자로 정한다","경쟁을 거치지 않는 수의계약 방식의 하나이다","입찰자가 설계를 처음부터 스스로 작성해 시공과 함께 제출하는 방식이다","입찰자가 발주기관이 준 설계서를 검토해 공사비 절감·공기단축 등 기술제안서를 작성해 입찰서와 함께 낸다"],answer:3,explanation:"기술제안입찰은 발주기관이 교부한 실시설계서 또는 기본설계서를 바탕으로 입찰자가 공사비 절감·공기단축·공사관리 방안 등을 담은 기술제안서를 입찰서와 함께 제출하는 방식이다. 설계를 스스로 작성하는 것은 일괄입찰이다.",basis:"국가계약법 시행령 제98조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제98조"},
{id:"P3-098",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 시공관리",ss:"3-4-3-3",tag:["공사","시공"],difficulty:"중",question:"건설공사 시공 단계에서 이루어지는 관리 활동으로 보기 어려운 것은?",options:["품질관리계획을 세워 발주자의 승인을 받고 품질시험·검사를 하는 것","발주기관이 시공사의 주식을 사들여 경영에 참여하는 것","안전관리계획을 세워 착공 전에 승인받고 안전점검을 하는 것","공정 진행과 작업 내용을 기록해 관리하는 것"],answer:1,explanation:"시공관리는 품질·안전·공정을 관리하는 활동이다. 건설기술 진흥법은 품질관리계획과 안전관리계획 수립·승인을 요구한다. 시공사 주식 매입은 시공관리와 관계없다.",basis:"건설기술 진흥법 제55조①, 제62조①",basisUrl:"https://www.law.go.kr/법령/건설기술진흥법/제55조"},
// ─── 기술용역 계약 ───
{id:"P3-099",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"기술용역 계약",ss:"3-4-3-4",tag:["용역","공사"],difficulty:"상",question:"설계·감리 같은 기술용역을 발주할 때에 관한 설명으로 가장 옳은 것은?",options:["전문성·기술성이 필요하면 제안서를 평가해 협상적격자를 뽑는 협상에 의한 계약을 활용할 수 있다","기술용역은 반드시 최저가 입찰자와 계약해야 한다","기술용역은 수의계약으로만 체결할 수 있다","기술능력은 평가하지 않고 추첨으로 계약상대자를 정한다"],answer:0,explanation:"물품·용역 계약에서 전문성·기술성 등이 필요하면 여러 공급자의 제안서를 평가해 협상적격자를 선정하고 협상을 거쳐 계약할 수 있다. 기술능력 평가가 중요한 설계·감리 용역에 많이 쓰인다.",basis:"국가계약법 시행령 제43조①",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제43조"},
// ─── 하도급지킴이 ───
{id:"P3-100",exam:"필기",subject:"공공계약관리",major:"하도급관리",sub:"하도급지킴이",ss:"3-4-3-6",tag:["하도급","전자조달"],difficulty:"중",question:"조달청 하도급지킴이처럼 공공 건설공사의 공사대금을 전자적으로 청구·지급하는 시스템의 주된 역할로 옳은 것은?",options:["발주기관이 원도급자 대신 하수급인을 직접 선정한다","원도급자가 받은 공사대금을 제한 없이 인출할 수 있게 한다","하수급인·건설근로자·장비업자 몫의 대금이 제대로 지급되는지 전자적으로 관리·확인한다","민간 건설공사의 하도급계약 내용을 사전에 심사해 승인한다"],answer:2,explanation:"공공 발주 건설공사의 수급인과 하수급인은 전자조달 시스템으로 공사대금을 청구·수령해야 하며, 하수급인·근로자·장비업자 등에게 줄 몫을 다른 데 쓸 수 없다. 시스템은 이 몫의 출금을 막고 지급 과정을 전자적으로 관리한다.",basis:"건설산업기본법 제34조⑨; 전자조달시스템등을 통한 공사대금의 청구 및 지급 등에 관한 고시 제5조",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제34조"},
// ══════════════════════════════════════════════════
// 필기 추가 50문제
// ══════════════════════════════════════════════════
// ─── P2 공공조달계획 수립 및 분석 (+20) ───
// 공공조달계획 (+4)
{id:"P2-061",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"조달계획 수립",ss:"2-1-1-1",tag:["계획","절차"],difficulty:"중",question:"공공조달계획 수립 시 가장 먼저 해야 할 것은?",options:["입찰공고 작성","수요조사 및 요구사항 파악","예산 집행","계약서 작성"],answer:1,explanation:"조달계획은 수요조사 → 예산확보 → 계약방법 결정 → 공고 순이며, 수요파악이 최우선입니다."},
{id:"P2-062",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"소요량 산정",ss:"2-1-1-2",tag:["계획","수량"],difficulty:"하",question:"공공조달에서 소요량을 과다 산정했을 때 발생할 수 있는 문제로 옳은 것은?",options:["공급 부족으로 업무 지연","예산 낭비 및 불용 발생","지체상금 부과","입찰 참가자 감소"],answer:1,explanation:"소요량 과다 산정은 불필요한 예산 집행 및 불용을 야기합니다."},
{id:"P2-063",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"연간조달계획",ss:"2-1-1-3",tag:["계획"],difficulty:"중",question:"연간 조달계획을 수립하는 주된 목적으로 가장 적절한 것은?",options:["수의계약 비율 확대","예산 낭비 방지 및 적기 조달 보장","담당자의 업무 편의","공급업체 수 축소"],answer:1,explanation:"연간 조달계획은 예산의 효율적 집행과 필요 시점에 적기 공급을 보장하기 위해 수립합니다."},
// 조달요구 응대 및 제안 (+4)
{id:"P2-065",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"조달요구 분석",ss:"2-1-1-2",tag:["요구분석"],difficulty:"중",question:"조달 담당자가 내부 수요부서의 요구사항을 검토할 때 가장 우선적으로 확인해야 할 사항은?",options:["공급업체 선호도","예산 가용 여부 및 추정가격","담당자의 개인 선호","공급자의 영업 정보"],answer:1,explanation:"조달 요구 분석 시 예산 가용 여부와 추정가격 파악이 계약방법 결정 등 이후 절차의 기준이 됩니다."},
{id:"P2-066",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"시장조사",ss:"2-1-2-3",tag:["시장조사","RFI"],difficulty:"중",question:"조달 전 시장조사(RFI) 단계에서 수집하는 정보로 가장 적절하지 않은 것은?",options:["공급업체 기술 현황","시장 가격 수준","공급 가능 업체 수","낙찰자의 최종 계약금액"],answer:3,explanation:"RFI는 입찰 전 단계로 낙찰 결과는 아직 존재하지 않습니다. 시장 기술·가격·업체 현황을 파악하는 단계입니다."},
{id:"P2-067",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"제안서 작성",ss:"2-2-1-2",tag:["제안","RFP"],difficulty:"중",question:"제안요청서(RFP)에 반드시 포함되어야 하는 사항으로 가장 거리가 먼 것은?",options:["과업 범위 및 요구사항","제안서 제출 기한 및 방법","평가 기준 및 배점","공급업체의 내부 인사 정보"],answer:3,explanation:"RFP는 과업범위·제출방법·평가기준 등을 포함하며 공급업체 내부 인사는 포함 대상이 아닙니다."},
{id:"P2-068",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"요구사항 명세",ss:"2-2-1-2",tag:["SOW","명세"],difficulty:"상",question:"과업지시서(SOW)와 제안요청서(RFP)의 관계를 가장 잘 설명한 것은?",options:["SOW와 RFP는 동일한 문서이다","SOW는 수행 범위·방법·산출물을 명시하고, RFP는 SOW를 포함해 제안서 작성 전반을 안내하는 문서다","RFP가 먼저 작성되고 SOW는 계약 후 작성된다","SOW는 물품 구매에만 사용한다"],answer:1,explanation:"SOW는 과업 수행 내용을 구체화한 문서이며, RFP는 SOW를 포함하여 평가기준·제출방법 등을 담은 포괄적 요청문서입니다."},
// 사전규격공개 분석 (+4)
{id:"P2-069",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"대상 및 기간",ss:"2-2-2-3",tag:["사전규격공개","기간"],difficulty:"중",question:"정부 입찰·계약 집행기준상 긴급한 경우 구매규격 사전공개 기간은 며칠까지 줄일 수 있는가?",options:["1일","3일","5일","7일"],answer:1,explanation:"원칙은 5일간 공개이고, 긴급한 경우에는 3일간 공개할 수 있습니다.",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제77조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/정부입찰ㆍ계약집행기준"},
{id:"P2-070",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"목적",ss:"2-2-2-3",tag:["사전규격공개","목적"],difficulty:"하",question:"사전규격공개 제도의 주된 목적으로 옳은 것은?",options:["특정 업체 우대","발주기관의 행정 편의","특정 업체에 유리한 규격 설정 방지","계약 기간 단축"],answer:2,explanation:"사전규격공개는 불공정한 규격 설정을 방지하고 입찰의 공정성을 확보하기 위한 제도입니다."},
{id:"P2-071",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"의견 처리",ss:"2-2-2-4",tag:["사전규격공개","절차"],difficulty:"중",question:"사전규격공개에서 접수된 업체 의견에 대한 발주기관의 처리 방법으로 옳은 것은?",options:["모든 의견을 무조건 반영해야 한다","제기된 의견은 수요목적 범위 내에서 적극 수렴하도록 검토한다","의견 접수 후 처리 결과를 공개하지 않아도 된다","의견을 접수한 업체는 입찰에 참가할 수 없다"],answer:1,explanation:"제기된 의견은 수요목적 범위 내에서 적극 수렴되도록 검토해야 하며, 이의사항 조정이 필요하면 계약심의회 등에 자문을 요청할 수 있습니다.",basis:"(계약예규) 정부 입찰ㆍ계약 집행기준 제77조 제3항·제4항",basisUrl:"https://www.law.go.kr/행정규칙/정부입찰ㆍ계약집행기준"},
{id:"P2-072",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"사전규격공개 분석",sub:"규격 작성 원칙",ss:"2-2-2-1",tag:["규격","원칙"],difficulty:"중",question:"발주기관이 규격서를 작성할 때 지켜야 할 원칙으로 가장 거리가 먼 것은?",options:["특정 상표·모델명 지정 금지","기능·성능 중심으로 작성","객관적이고 중립적인 기준 적용","특정 업체에 유리한 기준 반영"],answer:3,explanation:"규격서는 특정 업체에 유리하지 않도록 객관적·기능 중심으로 작성해야 합니다."},
// 입찰공고문 분석 (+4)
{id:"P2-073",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 기간",ss:"2-2-3-2",tag:["공고","기간"],difficulty:"하",question:"국가계약법 시행령상 재공고입찰이나 긴급한 경우 등에는 입찰공고를 입찰서 제출마감일 전날부터 기산하여 며칠 전까지 할 수 있는가?",options:["3일","5일","7일","10일"],answer:1,explanation:"원칙은 7일 전 공고지만, 재공고입찰·긴급한 경우 등 제35조④ 각 호에 해당하면 5일 전까지 공고할 수 있습니다.",basis:"국가계약법 시행령 제35조 제4항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제35조"},
{id:"P2-074",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 내용",ss:"2-2-3-2",tag:["공고","내용"],difficulty:"중",question:"입찰공고문에 반드시 포함되어야 하는 사항으로 옳지 않은 것은?",options:["입찰 참가 자격","입찰서 제출 기한 및 장소","예정가격","계약의 종류 및 목적물"],answer:2,explanation:"예정가격은 사전 비공개 원칙입니다. 개찰 시 공개하며 공고문에 기재하지 않습니다."},
{id:"P2-075",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"국제입찰",ss:"2-2-3-2",tag:["국제입찰","기간"],difficulty:"중",question:"특정조달(GPA 대상) 일반경쟁입찰의 입찰공고는 원칙적으로 입찰서 제출마감일 전날부터 기산하여 며칠 이전에 해야 하는가?",options:["7일","14일","20일","40일"],answer:3,explanation:"원칙은 40일 이전 공고입니다. 긴급한 경우 등은 10일 이전까지 가능하고, 전자조달시스템으로 공고·서류 게재·입찰서 접수를 하면 각각 5일씩 줄일 수 있지만 어떤 경우에도 10일 미만으로는 줄일 수 없습니다.",basis:"특정조달을 위한 국가를 당사자로 하는 계약에 관한 법률 시행령 특례규정 제11조 제2항~제5항",basisUrl:"https://www.law.go.kr/법령/특정조달을위한국가를당사자로하는계약에관한법률시행령특례규정/제11조"},
{id:"P2-076",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰공고문 분석",sub:"공고 수단",ss:"2-2-3-2",tag:["공고","나라장터"],difficulty:"하",question:"공공조달 입찰공고의 주요 게시 수단으로 옳은 것은?",options:["관보 및 일간신문만 사용한다","나라장터(G2B)에 게시한다","발주기관 내부 게시판에만 게시한다","구두로 공지한다"],answer:1,explanation:"국가종합전자조달시스템인 나라장터(G2B)를 통해 전자 입찰공고가 이루어집니다."},
// 입찰서 제출 및 개찰 (+4)
{id:"P2-077",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"복수예비가격",ss:"1-5-2-1",tag:["예정가격","개찰"],difficulty:"중",question:"복수예비가격에 관한 설명으로 옳은 것은?",options:["입찰자가 제출하는 여러 개의 입찰가격","기초금액의 ±2% 범위에서 15개를 작성 후 4개 추첨 평균으로 예정가격 결정","낙찰자가 선택하는 가격","개찰 전 공개하는 예비 금액"],answer:1,explanation:"복수예비가격은 기초금액 ±2% 범위에서 15개 작성 후 4개 추첨, 그 평균이 예정가격이 됩니다."},
{id:"P2-078",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"무효입찰",ss:"2-2-5-2",tag:["무효","입찰"],difficulty:"중",question:"다음 중 무효입찰에 해당하는 경우가 아닌 것은?",options:["동일인이 2개 이상의 입찰서를 제출한 경우","입찰보증금을 납부하지 않은 경우","입찰금액을 정자로 정확히 기재한 경우","대리권 없는 자가 대리 입찰한 경우"],answer:2,explanation:"금액을 정확히 기재하는 것은 유효 입찰 요건입니다. 무효 사유는 동일인 복수제출·보증금 미납·대리권 없는 대리 등입니다."},
{id:"P2-079",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰서 제출 및 개찰",sub:"전자입찰",ss:"2-2-5-1",tag:["전자입찰"],difficulty:"하",question:"전자입찰(전자투찰)의 장점으로 가장 거리가 먼 것은?",options:["입찰 담합 방지","입찰 비용 절감","현장 방문 불필요","종이문서 보관 의무 소멸"],answer:3,explanation:"전자입찰로 담합 방지·비용 절감·방문 불필요 등의 이점이 있으나, 법령에 따른 문서 보관 의무는 여전히 존재합니다."},
// 입찰·제안평가 및 계약체결 (+4)
{id:"P2-081",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"적격심사",ss:"2-3-4-1",tag:["낙찰","심사"],difficulty:"중",question:"적격심사에서 낙찰하한율(예: 10억 미만 공사 89.745%)의 의미로 옳은 것은?",options:["계약금액의 일정 비율을 납부해야 한다는 뜻이다","예정가격 대비 그 비율 이상의 입찰금액 제시자부터 심사 대상이 된다","낙찰자의 이윤 보장 비율이다","그 비율 이하를 써야 낙찰된다"],answer:1,explanation:"적격심사 낙찰하한율은 예정가격 대비 그 비율 이상을 써야 심사 대상이 된다는 의미입니다. 공사는 규모별(10억 미만 89.745% 등)로 다릅니다."},
{id:"P2-082",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"협상계약 절차",ss:"2-3-4-2",tag:["협상계약","절차"],difficulty:"중",question:"협상에 의한 계약의 절차로 옳은 것은?",options:["가격만 평가 후 최저가 선정","기술·가격 평가 → 합산점수 높은 순으로 협상 → 협상 성립 후 10일 이내 계약","입찰가격 제출 → 개찰 → 낙찰","기술평가 없이 제안서만 평가"],answer:1,explanation:"기술능력 평가(배점한도의 85% 이상이 협상적격자)와 가격 평가 점수를 합산한 순서대로 협상하고, 협상이 성립하면 10일 이내에 계약을 체결합니다.",basis:"(계약예규) 협상에 의한 계약체결기준 제8조, 제15조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/협상에의한계약체결기준"},
{id:"P2-083",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"평가위원",ss:"2-3-2-1",tag:["평가","위원"],difficulty:"중",question:"입찰 평가위원회에 관한 설명으로 옳지 않은 것은?",options:["외부 전문가로 구성하는 것이 원칙","평가 전 위원 명단 비공개","평가위원의 사전 업체 접촉 금지","평가 결과는 참여 업체에게 즉시 개별 통보"],answer:3,explanation:"평가 결과는 최종 확정 후 공식 통보하며, 평가 중 개별 통보는 공정성 훼손 우려로 허용되지 않습니다."},
{id:"P2-084",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"낙찰률",ss:"2-3-5-1",tag:["낙찰","계산"],difficulty:"중",question:"예정가격이 1억원이고 낙찰금액이 9천만원일 때 낙찰률은?",options:["85%","90%","95%","100%"],answer:1,explanation:"낙찰률 = 낙찰금액 ÷ 예정가격 = 9,000만원 ÷ 1억원 = 90%입니다.",basis:"국가계약법 시행령 제31조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제31조"},
// ─── P1 공공조달과 법제도 이해 추가 (+15) ───
// 전자조달시스템 보강 (+5)
{id:"P1-111",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"나라장터 기능",ss:"1-3-1-5",tag:["나라장터","전자조달"],difficulty:"하",question:"나라장터(KONEPS)에서 제공하는 서비스로 옳지 않은 것은?",options:["전자입찰","전자계약","세금 신고 및 납부","종합쇼핑몰"],answer:2,explanation:"나라장터는 전자입찰·계약·쇼핑몰 기능을 제공하지만, 세금 신고·납부는 국세청 홈택스에서 처리합니다."},
{id:"P1-112",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자서명",ss:"1-5-4-2",tag:["전자조달","서명"],difficulty:"중",question:"전자입찰 시 인증서(공동인증서 등)로 전자서명을 하는 이유로 가장 적절한 것은?",options:["입찰 담당자의 신원과 전자문서의 진위를 확인하기 위해","입찰가격을 자동 계산하기 위해","예정가격을 미리 확인하기 위해","계약서를 자동 생성하기 위해"],answer:0,explanation:"전자서명(실지명의를 확인할 수 있는 공동인증서 등 인증서)은 입찰자 신원 확인과 전자문서 위변조 방지를 위해 사용됩니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 제11조 제1항",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률/제11조"},
{id:"P1-113",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"혁신장터",ss:"1-3-2-2",tag:["혁신제품","전자조달"],difficulty:"중",question:"혁신장터를 통한 혁신제품 조달에 관한 설명으로 옳지 않은 것은?",options:["지정된 혁신제품은 수의계약 가능","혁신장터는 나라장터와 연계 운영","혁신제품 지정 기간은 통상 3년","혁신제품은 반드시 경쟁입찰로 구매해야 한다"],answer:3,explanation:"혁신제품은 지정 후 수의계약이 가능하며, 경쟁입찰 의무가 없습니다."},
{id:"P1-114",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"하도급지킴이",ss:"1-5-4-4",tag:["하도급","전자조달"],difficulty:"중",question:"하도급지킴이 시스템에 관한 설명으로 옳은 것은?",options:["원도급자가 하수급인을 선정하는 입찰 시스템","발주자가 하도급대금을 직접 지급하는 시스템","하도급대금의 청구·승인·지급을 전자적으로 처리하고 발주기관이 지급 여부를 확인하는 시스템","하도급 계약서를 대신 작성해 주는 시스템"],answer:2,explanation:"하도급지킴이는 조달청의 전자적 대금지급시스템입니다. 전용계좌를 통해 하수급인·노무자·자재장비업자에게 줄 대금의 청구·승인·지급을 전자로 처리하고 발주기관이 이를 확인합니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 제9조의2, 같은 법 시행령 제7조 제2항",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률/제9조의2"},
{id:"P1-115",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"디지털서비스계약",ss:"1-3-2-4",tag:["MAS","전자조달"],difficulty:"상",question:"디지털서비스 이용계약에 관한 설명으로 옳은 것은?",options:["오프라인으로만 계약 체결","심사를 거쳐 선정된 클라우드 등 디지털서비스는 수의계약이나 카탈로그계약으로 구매할 수 있다","물품 구매만 해당","지명경쟁 방식만 허용"],answer:1,explanation:"디지털서비스 전문계약제도는 심사로 선정된 클라우드 등 디지털서비스를 수의계약과 카탈로그계약으로 공급하는 제도입니다.",basis:"국가계약법 시행령 제26조 제1항 제5호 아목, 조달사업법 시행령 제16조",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률시행령/제16조"},
// 공공조달법률 이해 보강 (+5)
{id:"P1-116",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"국가계약법 적용 범위",ss:"1-1-1-3",tag:["법률","범위"],difficulty:"중",question:"국가계약법의 적용 대상으로 옳은 것은?",options:["모든 민간기업 계약","국가기관이 당사자인 계약","지방자치단체만 해당","지방자치단체의 계약에도 직접 적용된다"],answer:1,explanation:"국가계약법은 국가를 당사자로 하는 계약에 적용됩니다. 지방자치단체 계약은 지방계약법, 공기업·준정부기관 계약은 공기업·준정부기관 계약사무규칙이 적용됩니다.",basis:"국가계약법 제2조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제2조"},
{id:"P1-117",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"지방계약법",ss:"1-1-1-3",tag:["법률","지방"],difficulty:"중",question:"지방자치단체의 계약에 적용되는 주요 법령은?",options:["국가계약법","지방계약법","조달사업법","건설산업기본법"],answer:1,explanation:"지방자치단체 계약은 지방자치단체를 당사자로 하는 계약에 관한 법률(지방계약법)이 적용됩니다."},
{id:"P1-118",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"WTO GPA",ss:"1-5-5-1",tag:["국제","GPA"],difficulty:"중",question:"WTO 정부조달협정(GPA)에 관한 설명으로 옳은 것은?",options:["가입국 간 공공조달시장 상호 개방","개발도상국에만 적용","민간기업 거래에 적용","관세 협정을 의미"],answer:0,explanation:"GPA는 가입국 간 공공조달시장을 상호 개방하는 협정으로 국내 국가계약법 정비의 배경이 되었습니다."},
{id:"P1-119",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"계약의 원칙",ss:"1-5-1-1",tag:["원칙","법률"],difficulty:"중",question:"공공계약에 적용되는 민법 원칙 중 계약 자유의 원칙에 대한 설명으로 공공조달에서의 제한 사유로 옳은 것은?",options:["법령상 절차·경쟁 원칙에 의해 계약 자유가 제한된다","공공계약은 민법을 전혀 적용하지 않는다","계약 자유의 원칙이 공공계약에 더 넓게 적용된다","당사자 합의만으로 모든 법령 규정을 배제할 수 있다"],answer:0,explanation:"공공계약은 공익·투명성·공정성을 위해 법령에 따른 절차 의무로 계약 자유가 상당 부분 제한됩니다."},
{id:"P1-120",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"부정당업자",ss:"1-6-2-2",tag:["제재","법률"],difficulty:"중",question:"부정당업자 제재 기간으로 옳은 것은?",options:["최대 6개월","최대 1년","최대 2년","영구 제한"],answer:2,explanation:"부정당업자 입찰참가자격 제한은 최대 2년까지 가능하며, 위반 행위의 경중에 따라 기간이 달라집니다."},
// 전략적 공공조달 보강 (+5)
{id:"P1-121",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"사회적기업 우선구매",ss:"1-4-4-4",tag:["사회적가치","우선구매"],difficulty:"중",question:"사회적기업 제품에 대한 공공기관의 우선구매 의무에 관한 설명으로 옳은 것은?",options:["공공기관의 장은 사회적기업 제품의 우선 구매를 촉진해야 한다","민간기업에도 동일하게 적용된다","우선구매 제품 목록은 비공개이다","경쟁입찰로만 구매 가능하다"],answer:0,explanation:"사회적기업육성법상 공공기관의 장은 사회적기업 제품의 우선 구매를 촉진해야 하고, 구매계획과 전년도 구매실적을 고용노동부장관에게 통보해야 합니다.",basis:"사회적기업 육성법 제12조",basisUrl:"https://www.law.go.kr/법령/사회적기업육성법/제12조"},
{id:"P1-122",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"장애인기업",ss:"1-4-4-1",tag:["사회적가치","장애인"],difficulty:"하",question:"장애인기업에 대한 공공조달 지원 제도로 옳은 것은?",options:["입찰 참가 자격 박탈","수의계약 등 우선구매 지원","가격 불이익 부과","평가 점수 감점"],answer:1,explanation:"공공기관은 장애인기업 제품 구매를 촉진하고, 구매목표비율을 포함한 구매계획을 이행해야 합니다. 또 국가계약법 시행령에 따라 일정 금액 이하는 장애인기업과 수의계약을 할 수 있습니다.",basis:"장애인기업활동 촉진법 제9조의2",basisUrl:"https://www.law.go.kr/법령/장애인기업활동촉진법/제9조의2"},
{id:"P1-123",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"녹색조달",ss:"1-4-2-2",tag:["녹색조달","환경"],difficulty:"중",question:"녹색조달(GPP)의 주된 목적으로 옳은 것은?",options:["최저가 구매 보장","환경마크 제품 우선구매로 탄소배출 저감","공급자 수 확대","입찰 절차 간소화"],answer:1,explanation:"GPP(Green Public Procurement)는 환경성이 우수한 제품을 우선 구매하여 탄소배출을 줄이는 정책입니다."},
{id:"P1-124",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"혁신조달",ss:"1-4-3-3",tag:["혁신","IPP"],difficulty:"중",question:"혁신조달(IPP)에 관한 설명으로 옳지 않은 것은?",options:["혁신제품 도입으로 공공서비스 질 향상 목적","혁신장터를 통한 거래 가능","지정 기간은 통상 3년","혁신제품은 반드시 경쟁입찰로 구매"],answer:3,explanation:"혁신제품은 수의계약이 허용되어 신속하게 도입할 수 있습니다."},
{id:"P1-125",exam:"필기",subject:"공공조달과 법제도 이해",major:"전략적 공공조달",sub:"VFM",ss:"1-4-2-3",tag:["VFM","비용"],difficulty:"중",question:"VFM(Value for Money) 개념에 관한 설명으로 옳은 것은?",options:["최저가 구매가 항상 VFM을 실현한다","구매가격·품질·서비스·지속가능성을 종합한 최적 가치를 추구한다","VFM은 민간 기업에만 적용되는 개념이다","생애주기비용(LCC)과 전혀 무관하다"],answer:1,explanation:"VFM은 단순 최저가가 아닌 품질·성능·지속가능성까지 포함한 종합 가치 최적화 개념으로 LCC와 밀접하게 연계됩니다."},
// ─── P3 공공계약관리 추가 (+15) ───
// 공정조달 관리 보강 (+5)
{id:"P3-101",exam:"필기",subject:"공공계약관리",major:"공정조달 관리",sub:"담합",ss:"1-6-2-3",tag:["담합","부정당"],difficulty:"중",question:"입찰 담합(부당한 공동행위)에 해당하는 행위로 가장 적절한 것은?",options:["각 업체가 자기 원가를 바탕으로 따로 입찰가격을 정하는 것","입찰설명회에 참석해 과업 내용을 질의하는 것","원가계산서를 사실대로 작성해 제출하는 것","입찰 전에 경쟁 업체들끼리 낙찰받을 업체와 투찰 가격을 미리 정하는 것"],answer:3,explanation:"입찰에서 낙찰자·입찰가격 등을 다른 사업자와 합의해 정하는 것은 공정거래법상 부당한 공동행위이며, 국가계약법상 입찰참가자격 제한 사유이기도 하다.",basis:"공정거래법 제40조①8호; 국가계약법 제27조①2호",basisUrl:"https://www.law.go.kr/법령/독점규제및공정거래에관한법률/제40조"},
{id:"P3-102",exam:"필기",subject:"공공계약관리",major:"공정조달 관리",sub:"부당특약",ss:"3-1-1-1",tag:["불공정","특약"],difficulty:"상",question:"국가계약법상 '부당한 특약등'에 해당하여 무효가 될 수 있는 계약 조항은?",options:["발주기관의 책임으로 생긴 손해까지 계약상대자가 부담하도록 한 조항","양 당사자에게 같은 수준의 의무를 지우는 조항","납기를 넘기면 정해진 지체상금을 물리는 조항","하자담보책임기간을 법령이 정한 기간대로 정한 조항"],answer:0,explanation:"계약담당공무원은 법령에 규정된 계약상대자의 이익을 부당하게 제한하는 특약·조건을 정할 수 없고, 이런 부당한 특약등은 무효다.",basis:"국가계약법 제5조③④",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제5조"},
{id:"P3-103",exam:"필기",subject:"공공계약관리",major:"공정조달 관리",sub:"정보공개",ss:"1-5-3-4",tag:["정보공개","투명성"],difficulty:"중",question:"국가계약의 투명성을 위한 정보공개로 옳지 않은 것은?",options:["분기별 발주계획을 전자조달시스템에 공개한다","입찰 전에 예정가격을 미리 공개한다","계약체결 방법·상대자·계약금액 등 계약체결 내용을 공개한다","계약변경 내용과 사유를 공개한다"],answer:1,explanation:"예정가격은 밀봉해 개찰장소 등에 두고 누설되지 않도록 해야 한다. 발주계획·계약체결·계약변경 정보는 전자조달시스템에 공개 대상이다.",basis:"국가계약법 시행령 제7조의2①, 제92조의2①; 시행규칙 제82조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제7조의2"},
{id:"P3-104",exam:"필기",subject:"공공계약관리",major:"공정조달 관리",sub:"이해충돌",ss:"1-6-2-3",tag:["청렴","이해충돌"],difficulty:"중",question:"조달 담당자의 이해충돌 또는 불공정 행위로 가장 적절한 것은?",options:["모든 입찰자에게 같은 평가기준을 적용하는 것","여러 업체에서 규격 의견을 고르게 듣는 것","입찰공고 전에 특정 업체에게만 규격 정보를 알려주는 것","원가를 객관적인 자료로 검토하는 것"],answer:2,explanation:"공고 전에 특정 업체에만 규격 정보를 알려주면 그 업체가 부당하게 유리해져 공정한 경쟁을 해친다. 나머지는 공정한 조달 업무다."},
{id:"P3-105",exam:"필기",subject:"공공계약관리",major:"공정조달 관리",sub:"청렴의무",ss:"1-6-2-3",tag:["청렴","의무"],difficulty:"하",question:"국가공무원법상 '청렴의 의무'의 내용이 아닌 것은?",options:["직무와 관련해 직접 사례·증여·향응을 주거나 받지 않는다","직무와 관련해 간접적으로도 사례·증여·향응을 주고받지 않는다","직무 관계가 있든 없든 소속 상관에게 증여하지 않는다","법령을 지키며 맡은 직무를 성실히 수행한다"],answer:3,explanation:"청렴의 의무(제61조)는 직무 관련 사례·증여·향응 수수 금지와 상관에 대한 증여 금지다. 법령 준수와 성실한 직무 수행은 별도 조항인 성실 의무(제56조)다.",basis:"국가공무원법 제61조, 제56조",basisUrl:"https://www.law.go.kr/법령/국가공무원법/제61조"},
// 공급대상물 유형별 계약관리 보강 (+5)
{id:"P3-106",exam:"필기",subject:"공공계약관리",major:"공급대상물 유형별 계약관리",sub:"물품·용역·공사 비교",ss:"1-2-4-2",tag:["비교","유형"],difficulty:"중",question:"소액 수의계약 기준금액이 공사와 물품·용역에서 서로 다르게 정해진 이유로 가장 적절한 것은?",options:["계약 대상의 특성과 규모, 적용 법령이 유형마다 다르기 때문이다","공사는 추정가격을 산정할 수 없기 때문이다","물품은 언제나 공사보다 싸기 때문이다","용역은 수의계약이 금지되어 있기 때문이다"],answer:0,explanation:"시행령은 종합공사 4억원·전문공사 2억원·그 밖의 공사 1억6천만원 이하, 물품·용역 2천만원 이하로 유형별 기준을 달리 둔다. 용역도 이 기준 이하면 수의계약이 가능하다.",basis:"국가계약법 시행령 제26조①5호가목",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제26조"},
{id:"P3-107",exam:"필기",subject:"공공계약관리",major:"공급대상물 유형별 계약관리",sub:"공사 종류",ss:"3-4-1-1",tag:["공사","종류"],difficulty:"중",question:"건설산업기본법상 종합공사와 전문공사를 나누는 기준으로 옳은 것은?",options:["공사금액만을 기준으로 나눈다","공사기간의 길고 짧음으로 나눈다","종합공사는 종합적인 계획·관리·조정을 하며 시설물을 시공하고, 전문공사는 시설물의 일부나 전문 분야를 시공한다","전문공사는 언제나 종합공사보다 기술 난도가 높다"],answer:2,explanation:"종합공사는 종합적인 계획·관리·조정을 하면서 시설물을 시공하는 공사, 전문공사는 시설물의 일부 또는 전문 분야에 관한 공사다.",basis:"건설산업기본법 제2조5호·6호",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제2조"},
{id:"P3-108",exam:"필기",subject:"공공계약관리",major:"공급대상물 유형별 계약관리",sub:"용역 분류",ss:"3-4-1-1",tag:["용역","분류"],difficulty:"중",question:"공공조달에서 용역으로 분류하기 어려운 것은?",options:["청사 청소·경비","노후 건물의 해체(철거)","정보시스템 개발","정책 연구·컨설팅"],answer:1,explanation:"건설산업기본법상 건설공사에는 시설물·구조물의 설치뿐 아니라 해체공사도 포함되므로 건물 철거는 공사로 발주한다.",basis:"건설산업기본법 제2조4호",basisUrl:"https://www.law.go.kr/법령/건설산업기본법/제2조"},
{id:"P3-109",exam:"필기",subject:"공공계약관리",major:"공급대상물 유형별 계약관리",sub:"물품과 공사 구분",ss:"3-4-1-3",tag:["물품","공사","구분"],difficulty:"중",question:"물품계약과 공사계약 중 어느 쪽으로 발주할지 따져봐야 하는 경계 사례로 가장 적절한 것은?",options:["복사용지 구매","청사 청소 용역","도로 포장 공사","공장에서 만든 구조물을 현장에 설치까지 해서 납품하는 계약"],answer:3,explanation:"제조한 물품을 현장에서 설치까지 하는 계약은 물품 공급과 시공의 성격이 섞여 있어 발주 유형을 판단해야 하는 대표적인 경계 사례다."},
{id:"P3-110",exam:"필기",subject:"공공계약관리",major:"공급대상물 유형별 계약관리",sub:"MAS 2단계경쟁",ss:"3-3-2-4",tag:["MAS","2단계"],difficulty:"중",question:"다수공급자계약(MAS) 물품 구매에서 수요기관이 요청하면 조달청장이 2단계경쟁 예외를 허용할 수 있는 사유는?",options:["재해복구·방역사업이나 폭염·폭우 등 이상기후에 필요한 물자를 긴급히 사는 경우","물품의 단가가 높은 경우","해당 품목의 계약상대자 수가 많은 경우","1회 납품요구 구매예산이 2단계경쟁 기준금액을 넘는 경우"],answer:0,explanation:"재해복구·방역사업이나 이상기후 대응 물자를 긴급하게 구매하는 경우는 2단계경쟁 예외 사유다. 구매예산이 기준금액 이상이면 오히려 2단계경쟁 대상이 된다.",basis:"물품 다수공급자계약 업무처리규정 제50조①1호",basisUrl:"https://www.law.go.kr/행정규칙/물품다수공급자계약업무처리규정"},
// 공공조달 법제도 활용 보강 (+5)
{id:"P3-111",exam:"필기",subject:"공공계약관리",major:"공공조달 법제도 활용",sub:"이의신청",ss:"1-5-2-5",tag:["이의","절차"],difficulty:"중",question:"입찰 참가자격이나 낙찰자 결정 등으로 불이익을 받은 업체가 국가계약법에 따라 밟을 수 있는 불복 절차로 옳은 것은?",options:["이의신청 제도가 없어 곧바로 행정소송만 제기할 수 있다","계약담당공무원에게 구두로 항의하면 이의신청을 한 것으로 본다","국가계약분쟁조정위원회에 먼저 재심을 청구한 뒤 중앙관서의 장에게 이의신청한다","중앙관서의 장에게 이의신청하고, 그 조치에 이의가 있으면 국가계약분쟁조정위원회에 재심을 청구한다"],answer:3,explanation:"이의신청은 행위가 있었던 날부터 30일 또는 안 날부터 25일 이내에 해당 중앙관서의 장에게 하고, 15일 이내 통지된 조치에 이의가 있으면 통지받은 날부터 30일 이내에 국가계약분쟁조정위원회에 재심을 청구한다.",basis:"국가계약법 제28조①~④",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제28조"},
{id:"P3-112",exam:"필기",subject:"공공계약관리",major:"공공조달 법제도 활용",sub:"분쟁조정",ss:"1-6-1-1",tag:["분쟁","조정"],difficulty:"중",question:"국가계약분쟁조정위원회의 조정이 갖는 효력으로 옳은 것은?",options:["조정은 권고일 뿐이어서 어떤 경우에도 법적 효력이 없다","조정 신청만으로 해당 계약이 자동 해지된다","조정 완료 후 15일 이내에 청구인과 중앙관서의 장이 이의를 제기하지 않으면 재판상 화해와 같은 효력을 갖는다","조정이 끝나는 즉시 이의 여부와 관계없이 확정판결과 같은 효력이 생긴다"],answer:2,explanation:"조정은 청구인과 해당 중앙관서의 장이 조정 완료 후 15일 이내에 이의를 제기하지 않은 경우 재판상 화해와 같은 효력을 갖는다.",basis:"국가계약법 제31조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제31조"},
{id:"P3-113",exam:"필기",subject:"공공계약관리",major:"공공조달 법제도 활용",sub:"계약이행실적증명",ss:"3-1-4-3",tag:["실적","증명"],difficulty:"하",question:"업체가 발주기관에서 계약이행실적증명서를 발급받는 주된 목적으로 가장 적절한 것은?",options:["하자보수를 청구하기 위해","이후 입찰의 참가자격 심사나 적격심사에서 수행 실적을 증명하기 위해","대금 지급을 청구하기 위해","예정가격을 정하기 위해"],answer:1,explanation:"계약이행실적증명서는 업체가 과거에 계약을 수행한 실적을 증명하는 문서로, 이후 입찰 참가자격 심사·적격심사 등에서 실적 자료로 쓰인다."},
{id:"P3-114",exam:"필기",subject:"공공계약관리",major:"공공조달 법제도 활용",sub:"정보공개청구",ss:"2-3-5-1",tag:["정보공개","법률"],difficulty:"중",question:"입찰에서 떨어진 업체가 발주기관에 입찰 관련 문서의 공개를 청구할 수 있는 법적 근거는?",options:["공공기관의 정보공개에 관한 법률","독점규제 및 공정거래에 관한 법률","민법","형법"],answer:0,explanation:"공공기관의 정보공개에 관한 법률은 모든 국민에게 정보공개 청구권을 인정하므로, 업체도 공공기관이 보유한 입찰 관련 정보의 공개를 청구할 수 있다(비공개 대상 정보는 제외).",basis:"공공기관의 정보공개에 관한 법률 제5조①",basisUrl:"https://www.law.go.kr/법령/공공기관의정보공개에관한법률/제5조"},
{id:"P3-115",exam:"필기",subject:"공공계약관리",major:"공공조달 법제도 활용",sub:"감사원 감사",ss:"1-1-4-2",tag:["감사","통제"],difficulty:"중",question:"공공조달에 대한 감사원 감사의 주된 목적으로 옳은 것은?",options:["계약 담당자의 승진 순위를 정하는 것","공급업체의 납품 실적을 평가해 등급을 매기는 것","회계를 검사하고 공무원의 직무를 감찰해 예산 집행과 행정 운영의 적정을 기하는 것","계약금액을 자동으로 조정하는 것"],answer:2,explanation:"감사원은 세입·세출 결산을 검사하고 회계를 상시 검사·감독하며, 행정기관과 공무원의 직무를 감찰해 행정 운영의 개선과 향상을 꾀한다.",basis:"감사원법 제20조",basisUrl:"https://www.law.go.kr/법령/감사원법/제20조"},
// ─── 출제기준 보충 (2026-09-26) ───
{id:"P1-126",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"공공조달 공급자",ss:"1-1-2-2",tag:["개념"],difficulty:"하",question:"공공조달의 공급자(조달기업)에 관한 설명으로 옳지 않은 것은?",options:["법적인 관점에서 조달기업은 「국가종합전자조달시스템 입찰참가자격등록규정」에 따라 나라장터에 물품·용역·공사 제공 업체로 등록한 업체를 말한다","물품 조달기업은 직접 생산·제조하는 '제조업체'와 타인이 생산한 물품을 유통해 판매하는 '공급업체'로 구분된다","외국 기업은 정부조달협정(GPA)에 따른 국제입찰에 참여하는, 외국에 본점 소재지가 있는 기업으로서 본사와 국내 지사 등이 해당한다","공공조달의 공급자는 영리법인에 한정되므로 개인사업자나 비영리법인은 공급자가 될 수 없다"],answer:3,explanation:"공급자는 물품·용역·공사를 제공하는 사업자(법인 또는 개인)이고, 조달기업은 대기업·중견기업·중소기업·비영리법인 등으로 나뉩니다. 개인사업자나 비영리법인도 공급자가 될 수 있습니다. 나머지는 교재 설명 그대로입니다."},
{id:"P1-127",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"용역 조달기업 분류",ss:"1-1-2-2",tag:["개념","분류"],difficulty:"중",question:"국내 공공조달 실무에서 용역(서비스) 조달기업을 분류하는 방식으로 가장 적절한 것은?",options:["컨설팅 서비스 업체와 비컨설팅 서비스 업체 2가지로만 구분한다","일반용역(서비스)업체, 정보기술용역(서비스)업체, 기술용역(서비스)업체로 구분한다","제조업체와 공급업체로 구분한다","종합공사업체와 전문공사업체로 구분한다"],answer:1,explanation:"국내 실무는 용역을 일반용역·정보기술용역·기술용역으로 나누므로 조달기업도 이 세 가지로 볼 수 있습니다. 컨설팅/비컨설팅은 해외에서 쓰는 구분이고, 제조업체/공급업체는 물품 조달기업의 구분입니다. 종합·전문공사업체는 공사 쪽 구분입니다."},
{id:"P1-128",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"직접 이해관계자",ss:"1-1-2-3",tag:["개념"],difficulty:"하",question:"공공조달 이해관계자를 협의(직접적)와 광의로 구분할 때, 협의의 직접적 이해관계자로만 묶은 것은?",options:["국회, 감사원","시민사회단체, 국민","수요기관인 공공기관, 공급자인 조달기업","잠재적 공급업체, 조달·계약 유관 중앙행정기관"],answer:2,explanation:"직접적(협의) 이해관계자는 계약의 당사자로 조달 절차에 직접 참여하는 수요기관과 조달기업입니다. 국회·감사원·잠재적 공급업체·시민사회단체·국민·유관 중앙행정기관은 광의의 이해관계자입니다."},
{id:"P1-129",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 개요",sub:"내부 이해관계자",ss:"1-1-2-3",tag:["개념","분류"],difficulty:"중",question:"공공조달을 수행하는 공공기관의 '내부적' 이해관계자에 해당하지 않는 것은?",options:["계약심의위원회","감사원","계약부서","내부 감사부서"],answer:1,explanation:"감사원은 국회와 함께 공공부문 전반을 외부에서 감시·감독하는 외부 이해관계자입니다. 계약심의위원회, 사업부서, 계약부서, 내부 법률·감사부서는 기관 안의 내부 이해관계자입니다."},
{id:"P1-130",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"중앙집중형 특징",ss:"1-2-2-1",tag:["개념","비교"],difficulty:"중",question:"중앙집중형 공공조달 운영체계에 관한 설명으로 옳은 것은?",options:["규모의 경제를 통한 운영 효율성과, 표준화된 절차·기준에 따른 신속한 정책 실행이 장점이다","조달기관별로 독립적인 공공조달·계약 법령과 절차를 수립한다","개별 조달기관에 특화된 수요에 유연하고 고객화된 대응을 하는 데 가장 적합하다","수요를 통합해 운영하므로 절차의 복잡성이나 기간 지연 문제는 생기지 않는다"],answer:0,explanation:"중앙집중형은 국가의 조달수요를 통합해 규모의 경제와 표준화된 신속한 실행을 얻는 방식입니다. 기관별 독립 법령과 고객화된 대응은 분산형의 특징이고, 중앙집중형은 오히려 통합 운영에 따른 복잡성과 기간 지연이 단점입니다."},
{id:"P1-131",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"국내 중앙조달기관",ss:"1-2-2-1",tag:["개념","사례"],difficulty:"중",question:"국내의 부문별 중앙조달(구매)기관과 그 전자조달시스템의 연결로 옳지 않은 것은?",options:["조달청 – 나라장터(G2B)","방위사업청 – 국방전자조달시스템(D2B)","조달청 – 학교장터(S2B)","한국농수산식품유통공사 – 공공급식전자조달시스템"],answer:2,explanation:"학교장터(S2B)는 교육 부문 중앙조달기관인 한국교직원공제회가 운영합니다. 조달청은 나라장터, 방위사업청은 국방전자조달시스템, 한국농수산식품유통공사는 공공급식 식재료 부문 시스템을 운영합니다."},
{id:"P1-132",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"분산형 개념",ss:"1-2-2-2",tag:["개념"],difficulty:"하",question:"분산형 공공조달에 관한 설명으로 옳은 것은?",options:["단일 또는 분야별 전문 국가기관이 국가 안의 모든 공공기관 조달 수요를 전담해 처리한다","공공조달 권한을 받은 각 조달기관이 자체적으로 공공조달의 실행과 관리를 담당한다","통일된 조달·계약 법령에 따라 위임된 범위 안에서만 기관별 조달기준과 절차를 둔다","오늘날 대부분의 국가는 분산형 단일 모델만 채택하고 있다"],answer:1,explanation:"분산형은 권한을 받은 각 조달기관이 스스로 조달을 실행·관리하는 방식입니다. 한 기관이 전담하는 것은 중앙집중형, 위임 범위 안에서 기관별 기준을 두는 것은 혼합형(병립형)입니다. 실제로는 대부분의 나라가 두 방식을 함께 쓰는 병립형을 활용합니다."},
{id:"P1-133",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달 원칙 및 방법",sub:"분산형 단점",ss:"1-2-2-2",tag:["개념","비교"],difficulty:"중",question:"분산형 공공조달 운영체계의 단점으로 가장 적절한 것은?",options:["개별 조달기관의 고객화된 조달수요 충족도가 떨어진다","수요를 통합해 운영하므로 절차가 복잡해지고 기간이 지연된다","통합과 분산 운영을 위한 법적·시스템적 기반이 없으면 실행·관리 부담이 커진다","규모의 경제를 확보하지 못해 운영 효율성이 떨어지고, 기관마다 다른 법규·절차로 운영 안정성이 낮아진다"],answer:3,explanation:"분산형은 수요를 모으지 않으니 규모의 경제가 없고, 기관별로 법규·절차가 달라 안정성이 떨어집니다. 고객화 수요 충족도 저하와 통합 운영의 복잡성·지연은 중앙집중형의 단점이고, 통합·분산 기반 미비 시 부담 증가는 혼합형의 단점입니다."},
{id:"P1-134",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자적 구매시스템",ss:"1-3-1-2",tag:["개념","분류"],difficulty:"중",question:"2005년 영국 조달청(OGC)의 분류에 따른 전자조달시스템 유형 중 '전자적 구매(e-Purchasing) 시스템'의 주요 기능으로 가장 적절한 것은?",options:["전자적 입찰(e-Tendering)과 평가(e-Evaluation)","공급업체 데이터베이스와 협상(e-Negotiation)","전자적 경매(e-Auction)와 계약관리","구매, 지불(Payment), 구매카드, 전자송장(e-Invoicing)"],answer:3,explanation:"전자적 구매시스템은 정확한 주문정보를 바탕으로 구매·지불을 처리하는 데 초점을 두며, 구매·지불·구매카드·전자송장이 주요 기능입니다. 입찰·평가·공급업체 DB·협상·경매·계약관리는 전자적 소싱(e-Sourcing) 시스템의 기능입니다."},
{id:"P1-135",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자적 소싱시스템",ss:"1-3-1-2",tag:["개념"],difficulty:"하",question:"전자조달시스템 유형 중 전자적 소싱(e-Sourcing) 시스템에 관한 설명으로 옳은 것은?",options:["정확한 주문정보를 바탕으로 한 구매·지불 처리에 초점을 둔다","물품·용역·공사를 제공할 공급자를 찾고 평가하는 소싱 활동 지원에 초점을 둔다","구매카드와 전자송장이 핵심 기능이다","영국 분류에서 소싱·구매·지불·평가의 4가지 유형 중 하나이다"],answer:1,explanation:"전자적 소싱 시스템은 공급자를 찾고 평가하는 활동을 지원하며, 입찰·평가·협업·협상 기능 등을 포함합니다. 구매·지불, 구매카드, 전자송장은 전자적 구매시스템의 특징이고, 영국 분류는 소싱과 구매의 2가지 유형입니다."},
{id:"P1-136",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"발전단계와 구성요소",ss:"1-3-1-4",tag:["개념","단계"],difficulty:"중",question:"전자조달시스템의 5단계 발전 과정에 관한 설명으로 옳지 않은 것은?",options:["세 번째 단계에서 전통적 조달 프로세스가 도구와 기능을 완전히 통합한 전자조달 플랫폼으로 대체되었다","첫 번째 단계는 종이 기반 오프라인 업무처리로, 문서작성·표 계산 등 일부 업무에만 컴퓨터를 활용했다","두 번째 단계는 메인프레임·PC·ERP·EDI로 조달정보의 입력·전송·저장·처리를 지원했다","네 번째 단계에서는 온라인 공급자 등록 데이터베이스, 전자카탈로그, 웹 기반 EDI 등이 전통적 프로세스를 보완했다"],answer:0,explanation:"전통적 프로세스를 통합 전자조달 플랫폼으로 '대체'하는 것은 마지막 다섯 번째 단계입니다. 세 번째 단계는 이메일·웹사이트 등 인터넷 수단으로 전통적 프로세스를 지원하는 단계입니다."},
{id:"P1-137",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"전자조달 도구",ss:"1-3-1-4",tag:["개념"],difficulty:"중",question:"전자조달시스템을 구성하는 전자적 도구에 관한 설명으로 옳지 않은 것은?",options:["전자카탈로그 기능은 국내에서 나라장터 종합쇼핑몰이 구현한 것으로 볼 수 있다","전자적 정보(e-Informing) 제공은 조달 프로세스의 특정 단계와 직접 관련 없이 인터넷으로 조달정보를 수집·배포하는 과정이다","EDI는 인터넷 같은 개방형 네트워크에서 운영되므로 구현 비용이 낮다","동적구매시스템(DPS)은 계약 기간 중에도 새로운 공급업체가 참여할 수 있도록 한다"],answer:2,explanation:"EDI는 전통적으로 부가가치 네트워크(VAN)라는 폐쇄형 네트워크에서 운영되고, 보내는 쪽과 받는 쪽 모두 구현해야 해서 비용이 상대적으로 높습니다. 나머지 설명은 교재 내용과 같습니다."},
{id:"P1-138",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"물품목록번호 체계",ss:"1-3-3-3",tag:["개념","숫자"],difficulty:"중",question:"물품목록번호 체계에 관한 설명으로 옳지 않은 것은?",options:["물품목록번호는 8자리 물품분류번호와 8자리 물품식별번호로 구성된다","물품분류번호는 2자리씩 4단계(대·중·소·세분류) 계층구조로 되어 있다","세부품명번호는 물품분류번호 8자리 뒤에 2자리를 더한 10자리 번호이다","물품식별번호는 UNSPSC 표준에 따라 부여되므로 물품의 분류가 바뀌면 새 번호로 바뀐다"],answer:3,explanation:"물품식별번호는 UNSPSC와 관계없이 제조업체별·모델별로 붙이는 고유번호라서, 품명·세부품명 등 분류가 바뀌어도 한번 부여한 번호는 바뀌지 않습니다. 목록번호는 8자리 분류번호(2자리씩 4단계)와 8자리 식별번호로 이루어집니다.",basis:"물품목록정보의 관리 및 이용에 관한 법률 시행령 제9조 제1항",basisUrl:"https://www.law.go.kr/법령/물품목록정보의관리및이용에관한법률시행령/제9조"},
{id:"P1-139",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"목록화 절차",ss:"1-3-3-3",tag:["절차"],difficulty:"중",question:"목록정보시스템을 이용한 목록화 절차에 관한 설명으로 옳은 것은?",options:["목록화 요청은 각 기관만 할 수 있고 조달기업은 요청할 수 없다","기존에 없는 새 품명(세부품명)은 담당자 검토 후 상품목록심의회 심의를 거쳐 신설하는 것이 원칙이다","품목등록을 요청한 물품에 이미 같은 품목의 번호가 있어도 요청자에게 새 번호를 추가로 부여한다","물품을 직접 제조하는 기업이라면 조달청에 공급업체로만 입찰참가자격을 등록했더라도 자기 업체명을 제조업체명으로 하여 품목등록을 신청할 수 있다"],answer:1,explanation:"품명 신설은 요청 검토 후 상품목록심의회 심의를 거쳐 결정하는 것이 원칙입니다(긴급하거나 기준이 명확하면 생략 가능). 조달기업도 목록화를 요청할 수 있고, 이미 번호가 있으면 그 기존 번호를 통보합니다. 공급업체로만 등록한 기업은 제조 사실이 검증되지 않아 제조업체명으로 신청할 수 없습니다.",basis:"목록화지침 제8조 제2항, 제12조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/목록화지침"},
{id:"P1-140",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"분류번호 부여 기준",ss:"1-3-3-4",tag:["규정","숫자"],difficulty:"상",question:"목록화지침상 상품분류번호와 세부품명번호의 부여 기준으로 옳지 않은 것은?",options:["UNSPSC에 없는 분류가 필요하면 유보코드로 분류하되, 동일 단계의 뒷부분 숫자인 '99'부터 역순으로 번호를 매긴다","세부품명번호로 추가하는 두 자리 숫자는 '01'부터 차례로 번호를 매긴다","세분화할 필요성이 없는 품명은 세부품명번호를 생성하지 않는다","삭제된 세부품명번호는 다시 사용하지 않는 것을 원칙으로 한다"],answer:2,explanation:"세분화할 필요가 없는 품명이라도 세부품명번호를 하나 생성합니다. 유보코드는 '99'부터 역순, 세부품명번호 추가 두 자리는 '01'부터 차례로 매기고, 삭제된 번호는 다시 쓰지 않는 것이 원칙입니다.",basis:"목록화지침 제10조 제2호·제4호",basisUrl:"https://www.law.go.kr/행정규칙/목록화지침"},
{id:"P1-141",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"상품 분류 순서",ss:"1-3-3-4",tag:["규정","순서"],difficulty:"중",question:"목록화지침상 상품을 최신 UNSPSC 분류체계에 따라 분류할 때 적용하는 기준의 순서로 옳은 것은?",options:["사용된 재료 → 용도와 기능 → 유사한 공정이나 제조업체","유사한 공정이나 제조업체 → 사용된 재료 → 용도와 기능","용도와 기능 → 사용된 재료 → 유사한 공정이나 제조업체","용도와 기능 → 유사한 공정이나 제조업체 → 사용된 재료"],answer:3,explanation:"먼저 용도와 기능으로 분류하고, 그것이 어려우면 유사한 공정이나 제조업체로, 그래도 어려우면 상품을 만드는 데 쓴 재료로 분류합니다.",basis:"목록화지침 제11조 제1호",basisUrl:"https://www.law.go.kr/행정규칙/목록화지침"},
{id:"P1-142",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"품목 최신화",ss:"1-3-3-5",tag:["규정"],difficulty:"중",question:"목록화지침상 품목의 최신화에 관한 설명으로 옳은 것은?",options:["품목은 삭제하지 않는 것이 원칙이나, 등록 후 10년 이상 물품관리·조달계약 등에 사용되지 않았거나 중대한 흠 또는 중복 등록이 있으면 삭제할 수 있다","생산이 중단된 품목은 즉시 삭제해야 한다","품목의 개별속성값은 오류나 누락이 없어도 요청자가 원하면 언제든 자유롭게 수정할 수 있다","품목 최신화는 모든 경우 반드시 상품목록심의회의 심의를 거쳐야 한다"],answer:0,explanation:"품목은 삭제하지 않는 것이 원칙이고, 10년 이상 쓰이지 않았거나 중대한 흠·중복 등록이 있을 때만 삭제할 수 있습니다. 속성값 수정은 오류·누락이 있을 때가 원칙이고, 품목 최신화는 담당자가 처리하되 판단이 어려울 때 심의회 심의를 요청할 수 있습니다.",basis:"목록화지침 제37조",basisUrl:"https://www.law.go.kr/행정규칙/목록화지침"},
{id:"P1-143",exam:"필기",subject:"공공조달과 법제도 이해",major:"전자조달시스템",sub:"분류 정비보고서",ss:"1-3-3-5",tag:["규정"],difficulty:"상",question:"목록화지침상 분류 및 품명 정비를 위한 정비보고서에 반드시 포함되어야 하는 사항이 아닌 것은?",options:["UNSPSC와의 매핑테이블 검토","해당 분류 상품을 공급하는 업체별 매출액 순위","중소기업자간 경쟁제품 여부 및 계약현황 검토","유사 상품분류와의 통합 여부 검토"],answer:1,explanation:"정비보고서에는 상품분류 현황, 분류기준, 관련 상품분류, 유사 분류와의 통합 여부, UNSPSC 매핑테이블, 중소기업자간 경쟁제품 여부·계약현황 검토가 들어가야 합니다. 업체별 매출액 순위는 포함 사항이 아닙니다.",basis:"목록화지침 제38조 제3호",basisUrl:"https://www.law.go.kr/행정규칙/목록화지침"},
{id:"P1-144",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"민법 - 화해",ss:"1-5-1-5",tag:["법령","민법"],difficulty:"중",question:"민법상 화해에 관한 설명으로 옳지 않은 것은?",options:["화해는 당사자가 서로 양보하여 분쟁을 끝낼 것을 약정함으로써 효력이 생긴다","화해계약으로 당사자 일방이 양보한 권리는 소멸하고, 상대방은 화해로 그 권리를 취득한다","화해의 목적인 분쟁 자체에 관한 사항에 착오가 있으면 이를 이유로 화해계약을 취소할 수 있다","화해계약은 원칙적으로 착오를 이유로 취소하지 못한다"],answer:2,explanation:"화해계약은 착오를 이유로 취소하지 못하는 것이 원칙이고, 예외는 화해당사자의 자격 또는 분쟁 '이외'의 사항에 착오가 있을 때뿐입니다. 분쟁 자체에 관한 착오로는 취소할 수 없습니다.",basis:"민법 제731조, 제732조, 제733조",basisUrl:"https://www.law.go.kr/법령/민법/제733조"},
{id:"P1-145",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"분쟁해결방법 합의",ss:"1-5-1-5",tag:["법령","분쟁"],difficulty:"중",question:"국가계약법상 계약을 체결할 때 계약당사자 간 합의로 정할 수 있는 분쟁해결방법으로 옳은 것은?",options:["행정심판 또는 헌법소원","감사원 심사청구 또는 국민권익위원회 고충민원","형사고소 또는 수사의뢰","국가계약분쟁조정위원회의 조정 또는 「중재법」에 따른 중재"],answer:3,explanation:"국가계약법은 계약 체결 때 분쟁해결방법을 정할 수 있게 하고, 그 방법은 국가계약분쟁조정위원회의 조정 또는 중재법에 따른 중재 중에서 합의로 정합니다. 민법의 화해 규정이 공공계약법령에 반영된 조항으로 볼 수 있습니다.",basis:"국가계약법 제28조의2",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제28조의2"},
{id:"P1-146",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"계약체결 요청 기준",ss:"1-5-3-2",tag:["법령","숫자"],difficulty:"중",question:"조달사업법령상 국가기관이 조달청장에게 계약체결을 요청해야 하는 경우에 해당하지 않는 것은? (단, 해당 물자에 조달청의 제3자단가계약·다수공급자계약 등이 체결되어 있지 않고, 요청 예외 사유도 없다고 가정한다)",options:["추정가격 7천만원인 국산 수요물자를 구매하는 경우","추정가격 1억 5천만원인 국산 수요물자를 구매하는 경우","추정가격 40억원인 종합공사 계약을 체결하는 경우","추정가격 5억원인 전기공사 계약을 체결하는 경우"],answer:0,explanation:"국가기관의 수요물자 구매는 추정가격 1억원(외국산 20만달러) 이상일 때 조달청에 요청해야 하므로 7천만원은 해당하지 않습니다. 공사는 추정가격 30억원 이상인 종합공사와 3억원 이상인 전문·전기·정보통신·소방시설공사가 요청 대상입니다.",basis:"조달사업법 시행령 제11조 제1항",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률시행령/제11조"},
{id:"P1-147",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"계약체결 요청 절차",ss:"1-5-3-2",tag:["법령"],difficulty:"중",question:"조달사업법상 계약체결의 요청에 관한 설명으로 옳지 않은 것은?",options:["수요기관의 장은 의무 요청 기준에 해당하지 않더라도 조달청장에게 수요물자 구매나 공사의 계약체결을 요청할 수 있다","조달청장은 요청받은 계약의 체결방법 등을 수요기관이 적용해야 할 법령에 따라 수요기관과 협의하여 결정한다","조달청장은 계약체결방법 등에 관한 협의가 이루어지지 않으면 수요기관이 직접 계약을 체결하게 할 수 있다","조달청은 국가기관이므로 지방자치단체가 요청한 계약에도 항상 국가계약법을 적용한다"],answer:3,explanation:"조달청장은 수요기관이 적용해야 할 법령에 따라 계약방법을 정하므로, 지방자치단체가 요청한 계약은 지방계약법을 적용합니다(법제처 해석도 같음). 나머지는 조달사업법 제11조 제2항~제4항 내용입니다.",basis:"조달사업법 제11조 제2항~제4항",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률/제11조"},
{id:"P1-148",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"구매위탁 의무 예외 사유",ss:"1-5-5-2",tag:["법령","공기업"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙상 중소기업자간 경쟁 제품의 조달청 구매위탁 의무에 대한 예외 사유에 해당하지 않는 것은?",options:["계약목적을 달성하기 위하여 제품을 긴급히 구매할 필요가 있는 경우","해당 기관의 계약부서가 자체 입찰 경험을 쌓기 위해 직접 구매를 원하는 경우","디자인 공모 및 선호도 조사 결과 등을 반영하여 미리 제품을 선정하고 구매할 필요가 있는 경우","전산업무 소프트웨어 개발 등 용역사업과 관련된 제품으로서 기관 고유사업 지원을 위해 직접 구매하는 것이 적합한 경우"],answer:1,explanation:"예외 사유는 긴급 구매, 디자인 공모 등 반영, 전산 소프트웨어 개발 등 용역 관련 제품, 조달청장이 인정한 핵심 기자재, 그 밖에 특수성·전문성·안전성 등으로 조달청장이 인정한 경우입니다. 기관이 단순히 원한다는 것은 사유가 아닙니다.",basis:"공기업·준정부기관 계약사무규칙 제7조의2 제1항",basisUrl:"https://www.law.go.kr/법령/공기업ㆍ준정부기관계약사무규칙/제7조의2"},
{id:"P1-149",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"구매위탁 예외 절차",ss:"1-5-5-2",tag:["법령","공기업","숫자"],difficulty:"상",question:"공기업·준정부기관 계약사무규칙상 중소기업자간 경쟁 제품을 조달청에 위탁하지 않고 직접 구매하는 경우에 관한 설명으로 옳은 것은?",options:["공기업의 핵심 기자재라면 조달청장의 인정 없이 기관장이 스스로 판단해 직접 구매할 수 있다","조달청장은 직접 구매 인정 신청을 받은 날부터 30일 이내에 결과를 통보해야 한다","제품을 해당 기관에서 직접 구매하는 경우 그 사유를 발주계획서 및 입찰공고문에 구체적으로 밝혀야 한다","예외에 해당하는 제품은 전자조달시스템에 게재하지 않아도 된다"],answer:2,explanation:"직접 구매할 때는 그 사유를 발주계획서와 입찰공고문에 구체적으로 적어야 합니다. 핵심 기자재 등은 조달청장의 인정을 받아야 하고, 조달청장은 신청을 받은 날부터 10일 이내에 통보합니다. 예외 제품과 그렇지 않은 제품은 각각 전자조달시스템(또는 자체 시스템)에 게재해야 합니다.",basis:"공기업·준정부기관 계약사무규칙 제7조의2 제2항~제4항",basisUrl:"https://www.law.go.kr/법령/공기업ㆍ준정부기관계약사무규칙/제7조의2"},
{id:"P1-150",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"의견청취 통지",ss:"1-5-5-4",tag:["법령","공기업","숫자"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙상 입찰참가자격을 제한하기 전 의견청취에 관한 설명으로 옳은 것은?",options:["의견청취 예정일 3일 전까지 구두로 알리면 된다","의견청취 예정일 7일 전까지 처분의 상대방 또는 그 대리인에게 서면으로 사유·일시·장소 등을 알려야 한다","처분의 상대방은 반드시 출석해야 하며 서면으로 의견을 제출할 수는 없다","처분의 상대방 외 이해관계인의 의견은 어떤 경우에도 들을 수 없다"],answer:1,explanation:"의견청취 예정일 7일 전까지 서면으로 사유·일시·장소 등을 알려야 합니다. 상대방은 출석해 진술하거나 서면으로 의견을 낼 수 있고, 기관장은 필요하면 이해관계인의 의견도 들어야 합니다.",basis:"공기업·준정부기관 계약사무규칙 제16조 제1항~제3항",basisUrl:"https://www.law.go.kr/법령/공기업ㆍ준정부기관계약사무규칙/제16조"},
{id:"P1-151",exam:"필기",subject:"공공조달과 법제도 이해",major:"공공조달법률 이해",sub:"의견청취 절차",ss:"1-5-5-4",tag:["법령","공기업"],difficulty:"중",question:"공기업·준정부기관 계약사무규칙상 입찰참가자격 제한 처분의 의견청취 절차에 관한 설명으로 옳지 않은 것은?",options:["의견진술 기회는 입찰참가자격 제한 처분을 한 뒤 사후에 주면 된다","상대방이 정당한 사유 없이 따르지 않거나 소재 불명으로 기회를 줄 수 없으면 의견진술 기회를 주지 않을 수 있다","통지에는 정당한 사유 없이 응하지 않으면 의견진술 기회를 포기한 것으로 본다는 뜻을 명시해야 한다","상대방이 출석해 진술하면 관계 직원이 그 내용을 서면으로 작성해 확인하게 한 뒤 서명 또는 기명날인하게 해야 한다"],answer:0,explanation:"기관장은 입찰참가자격을 제한하려면 '미리' 의견을 진술할 기회를 주어야 합니다. 사후에 주는 것은 틀립니다. 나머지는 규칙 제16조 제1항 단서, 제4항, 제5항 내용입니다.",basis:"공기업·준정부기관 계약사무규칙 제16조",basisUrl:"https://www.law.go.kr/법령/공기업ㆍ준정부기관계약사무규칙/제16조"},
{id:"P1-152",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"정부유권해석",ss:"1-6-1-2",tag:["개념","해석"],difficulty:"중",question:"정부유권해석에 관한 설명으로 옳지 않은 것은?",options:["행정기관 사이의 통일된 법령 해석 의견을 제시하는 것으로, 원칙적으로 법제처가 담당한다","법적 구속력은 없지만, 이를 벗어난 집행은 징계나 감사 등 책임 문제로 이어질 수 있어 사실상 구속력이 있다고 볼 수 있다","정부유권해석은 같은 사안에 대한 법원의 확정판결보다 우선하는 효력이 있다","개별 행정기관의 행정해석에 이견이 있으면 정부유권해석으로 통일된 해석과 집행기준을 마련할 수 있다"],answer:2,explanation:"해석의 우선순위는 사법해석(법원) > 정부유권해석(법제처) > 행정해석(개별 행정기관)입니다. 법원의 확정판결이 나오면 정부유권해석의 효력은 제한됩니다."},
{id:"P1-153",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"시스템과 공고문 불일치",ss:"1-6-1-2",tag:["법령","해석"],difficulty:"중",question:"나라장터(전자조달시스템)에 게시된 내용과 붙임 파일 형태의 입찰공고문 내용이 서로 다를 때의 처리로 옳은 것은?",options:["모든 항목에서 전자조달시스템에 게시된 내용이 우선한다","입찰공고문의 내용이 우선하되, 입찰공고일은 전자조달시스템에 게시한 날이 우선한다","모든 항목에서 입찰공고문의 내용이 우선한다","전자조달시스템 게시 내용이 우선하되, 입찰공고일은 입찰공고문에 적힌 날이 우선한다"],answer:1,explanation:"경쟁방법·낙찰자 선정방법 등 내용이 다르면 입찰공고문이 우선합니다. 다만 입찰공고일이 다르면 전자조달시스템에 게시한 날이 우선합니다.",basis:"전자조달법 시행령 제4조 제3항",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률시행령/제4조"},
{id:"P1-154",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"지체상금과 계약보증금상당액",ss:"1-6-1-3",tag:["법령","해석"],difficulty:"상",question:"성질상 분할할 수 있는 용역계약에서 일부를 검사 후 인수했고, 이후 미이행분에 지체상금이 부과되고 있다. 계약 해제·해지 판단 기준인 '지체상금이 계약보증금상당액에 달하는 시점'에 관한 정부 해석으로 옳은 것은?",options:["인수한 기성부분을 뺀 잔여 계약금액에 대한 계약보증금에 달하는 시점","지체상금 상한인 계약금액의 100분의 30에 달하는 시점","계약보증금을 면제받은 계약이라면 이 시점을 따질 필요가 없다","기성부분을 빼지 않은 전체 계약금액에 대한 계약보증금에 달하는 시점"],answer:3,explanation:"시행령 제75조 제2항의 계약보증금상당액은 기성부분을 제외하지 않은 전체 계약보증금을 뜻하므로, 전체 계약금액에 대한 계약보증금에 달하는 시점으로 봅니다. 면제된 계약보증금도 포함해 판단합니다. 100분의 30은 지체상금 자체의 상한으로 다른 개념입니다.",basis:"국가계약법 시행령 제75조 제2항, 제74조 제3항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제75조"},
{id:"P1-155",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"계약보증금 국고귀속",ss:"1-6-1-3",tag:["법령"],difficulty:"상",question:"국가계약법 시행령상 계약보증금의 국고귀속에 관한 설명으로 옳지 않은 것은?",options:["국고에 귀속시키는 계약보증금은 원칙적으로 기성부분에 대한 미지급액과 상계 처리한다","계약상대자가 정당한 이유 없이 계약상 의무를 이행하지 않으면 계약보증금을 국고에 귀속시켜야 한다","성질상 분할할 수 있는 계약에서 기납부분을 검사를 거쳐 인수했다면, 그 기납부분에 해당하는 계약보증금은 제외하고 귀속시킨다","단가계약으로 여러 차례 분할해 이행하는 경우, 이행이 완료된 부분에 해당하는 계약보증금은 제외하고 귀속시킨다"],answer:0,explanation:"국고에 귀속시키는 계약보증금은 기성부분 미지급액과 상계 처리해서는 안 됩니다. 계약보증금의 전부 또는 일부를 면제한 경우에만 상계할 수 있습니다.",basis:"국가계약법 시행령 제51조 제1항·제2항·제4항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제51조"},
{id:"P1-156",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"허위 적격심사서류 처리",ss:"1-6-1-5",tag:["규정","해석"],difficulty:"상",question:"(계약예규) 적격심사기준상 적격심사를 위해 제출된 서류가 허위로 작성된 것으로 판명된 경우의 처리로 옳지 않은 것은?",options:["계약체결 이전이면 적격낙찰자 결정대상에서 제외하거나 결정통보를 취소한다","계약체결 이후이면 해당 계약을 해제 또는 해지할 수 있다","각 중앙관서의 장은 해당 업체에 대해 국가계약법 시행령 제76조에 따른 입찰참가자격 제한조치를 하여야 한다","허위 실적을 빼고도 심사기준을 충족했다면 허위서류 제출로 볼 수 없어 제재할 수 없다"],answer:3,explanation:"허위서류가 심사 결과에 어떤 영향을 미쳤는지와 관계없이, 허위서류를 낸 사실 자체로 계약 해제·해지와 입찰참가자격 제한 대상이 된다는 것이 정부 해석입니다. 나머지는 적격심사기준 제10조 내용입니다.",basis:"(계약예규) 적격심사기준 제10조",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)적격심사기준"},
{id:"P1-157",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"허위서류와 입찰참가자격 제한",ss:"1-6-1-5",tag:["법령","숫자"],difficulty:"중",question:"국가계약법령상 입찰 또는 계약에 관한 서류를 위조·변조하거나 허위서류를 제출한 자에 대한 입찰참가자격 제한에 관한 설명으로 옳은 것은?",options:["계약금액이 고시금액 이상인 경우에만 제한 대상이 된다","제한 기간은 3년 이상 5년 이하의 범위에서 정한다","경쟁의 공정한 집행을 저해할 염려가 있는 자로서 입찰참가자격 제한 대상이 된다","위반행위가 끝난 날부터 10년이 지나도 입찰참가자격을 제한할 수 있다"],answer:2,explanation:"서류 위·변조나 허위서류 제출은 '경쟁의 공정한 집행을 저해할 염려가 있는 자'에 해당해 1개월 이상 2년 이하로 입찰참가자격을 제한합니다. 금액 요건은 없고, 행위가 끝난 날부터 5년(담합·뇌물은 7년)이 지나면 제한할 수 없습니다.",basis:"국가계약법 제27조 제1항 제9호 가목·제4항, 같은 법 시행령 제76조 제2항 제1호 가목·제3항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제76조"},
{id:"P1-158",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"지체상금 도달 시 해제·해지",ss:"1-6-2-1",tag:["법령"],difficulty:"중",question:"국가계약법 시행령상 지체상금이 계약보증금상당액에 달한 경우의 조치로 옳은 것은?",options:["지체상금이 계약보증금상당액에 달하면 예외 없이 계약을 해제해야 한다","계약상대자의 귀책사유로 계약을 수행할 가능성이 없음이 명백하면 계약보증금을 국고에 귀속시키고 계약을 해제 또는 해지한다","이행 가능성이 있고 계약 유지가 필요하면 추가 보증금 없이 그대로 계약을 유지한다","계약보증금을 면제받은 계약에는 이 규정을 적용하지 않는다"],answer:1,explanation:"수행 가능성이 없음이 명백하면 계약보증금을 국고에 귀속시키고 해제·해지합니다. 이행 가능성이 있고 유지가 필요하면 미이행 부분에 상당하는 계약보증금을 추가로 내게 하고 계약을 유지합니다. 면제된 계약보증금도 계약보증금상당액에 포함됩니다.",basis:"국가계약법 시행령 제75조 제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제75조"},
{id:"P1-159",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"해제·해지와 선금 정산",ss:"1-6-2-1",tag:["규정","비교"],difficulty:"상",question:"(계약예규) 물품구매(제조)계약일반조건상 계약 해제·해지 시 선금 미정산잔액 처리에 관한 설명으로 옳은 것은?",options:["계약상대자의 책임 있는 사유로 해제·해지된 경우, 계약상대자는 선금 미정산잔액에 약정이자상당액을 가산하여 상환해야 한다","발주기관의 사정변경으로 해제·해지된 경우에도 선금 미정산잔액에 약정이자상당액을 가산하여 상환해야 한다","계약상대자의 책임 있는 사유로 해제된 경우 선금 미정산잔액은 상환하지 않아도 된다","사정변경으로 해제·해지한 경우 발주기관은 미지급 기성대가를 해제·해지한 날부터 60일 이내에 지급하면 된다"],answer:0,explanation:"계약상대자 책임으로 해제·해지되면 선금 미정산잔액에 약정이자상당액을 더해 갚아야 합니다. 발주기관 사정변경에 의한 해제·해지는 미정산잔액만 갚고 이자는 붙이지 않으며, 발주기관은 미지급 대가와 철수비용을 14일 이내에 지급합니다.",basis:"(계약예규) 물품구매(제조)계약일반조건 제26조 제4항, 제27조 제2항·제3항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
{id:"P1-160",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"불공정 조달행위 유형",ss:"1-6-2-4",tag:["법령"],difficulty:"중",question:"조달사업법상 불공정 조달행위(부당이득 환수 대상)에 해당하지 않는 것은?",options:["직접생산기준을 위반하여 납품하는 행위","원산지를 거짓으로 표시하여 납품하는 행위","시장가격이 내려가 다음 입찰에서 종전보다 낮은 가격으로 투찰하는 행위","수요기관 등의 사전 승인 없이 계약규격과 다른 제품을 납품하는 행위"],answer:2,explanation:"불공정 조달행위는 서류 위·변조나 거짓 서류 제출, 직접생산기준 위반 납품, 원산지 거짓 표시 납품, 사전 승인 없는 규격 상이 제품 납품, 다수공급자계약 가격 유지 의무 위반, 우수조달물품 등 부정 지정의 6가지입니다. 조달청장은 이로 얻은 이득을 환수할 수 있습니다. 정상적으로 낮은 가격에 투찰하는 것은 해당하지 않습니다.",basis:"조달사업법 제21조 제1항·제6항",basisUrl:"https://www.law.go.kr/법령/조달사업에관한법률/제21조"},
{id:"P1-161",exam:"필기",subject:"공공조달과 법제도 이해",major:"공정조달 관리",sub:"부당이득금과 계약보증금 비교",ss:"1-6-2-4",tag:["비교","개념"],difficulty:"상",question:"다수공급자계약에서 부당이득금 환수와 계약보증금 국고귀속의 차이에 관한 설명으로 옳은 것은?",options:["부당이득금은 이행이 완료된 위반 납품분을 기준으로 산정하고, 계약보증금 국고귀속은 이행이 완료된 부분을 제외한 미이행분을 대상으로 한다","둘은 같은 대상에 대한 같은 성격의 제재이므로 함께 부과할 수 없다","부당이득금 환수는 입찰참가자격 제한과 같은 행정처분의 성격을 가진다","계약보증금 국고귀속은 이미 납품을 마친 분량까지 포함한 총 납품금액을 기준으로 한다"],answer:0,explanation:"부당이득금은 위반해 납품을 마친 금액 전부를 기준으로, 계약보증금은 분할 납품한 경우 이미 이행한 부분을 빼고 남은 부분에 대해서만 귀속됩니다. 부당이득금 환수는 행정처분이 아니라 민사상 손해배상 예정액의 성격이어서 중복 제재로 보지 않습니다.",basis:"국가계약법 시행령 제51조 제2항 제2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제51조"},
{id:"P2-085",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"공급방법 확인",ss:"2-1-2-1",tag:["공급계획","조달방법"],difficulty:"중",question:"공급업체가 공급하려는 물품의 공급방법 적정성을 분석할 때에 관한 설명으로 옳지 않은 것은?",options:["다수공급자계약 품목이라도 일반 입찰공고를 꾸준히 검색하면 종합쇼핑몰 등록 없이도 같은 공급 기회를 확보할 수 있다","공급하려는 물품이 조달청 다수공급자계약으로 공급되는 품목이면 다수공급자계약을 맺고 종합쇼핑몰에 등록되어야 공급할 수 있다","금액이 작아 1인 견적 수의계약으로 체결되는 물품은 일반 입찰공고만 검색해서는 공급 기회를 찾기 어렵다","이전 입찰공고문, 수의계약 안내공고문, 다수공급자계약 공고문 등을 검색해 해당 물품이 어떤 방법으로 조달되는지 확인한다"],answer:0,explanation:"다수공급자계약 품목은 일반 입찰이나 수의계약으로는 공급할 수 없고, 계약을 맺어 종합쇼핑몰에 등록되어야 합니다. 그래서 공급하려는 물품이 어떤 조달방법으로 사 가는 물건인지 먼저 확인하는 것이 공급방법 적정성 분석의 출발점입니다."},
{id:"P2-086",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"입찰요청 방법과 계약방법",ss:"2-1-2-1",tag:["공급계획","RFP"],difficulty:"중",question:"입찰요청 방법과 국내 계약방법의 연결로 볼 때, 제안서요청서(RFP) 방식에 해당하는 국내 계약방법은?",options:["희망수량경쟁입찰","적격심사낙찰제","협상에 의한 계약","1인 견적 수의계약"],answer:2,explanation:"제안서요청서(RFP)는 기술·품질과 가격을 가중치로 함께 평가하고 최고점자와 협상하는 방식으로, 협상에 의한 계약·경쟁적 대화에 의한 계약·일괄/대안/기술제안입찰이 여기에 해당합니다. 희망수량경쟁입찰과 1인 견적 수의계약은 견적요청서(RFQ), 적격심사낙찰제는 입찰초청서(ITB)에 해당합니다."},
{id:"P2-087",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"조달데이터허브",ss:"2-1-2-2",tag:["공급정보","데이터"],difficulty:"중",question:"공급정보 수집을 위한 조달데이터허브 활용에 관한 설명으로 옳지 않은 것은?",options:["사전에 정의된 데이터 보고서와 오픈 API는 로그인하지 않아도 내려받거나 활용할 수 있다","'조달업체 등록 내역' 보고서를 세부품명 기준으로 검색하면 경쟁 조달업체의 등록 정보를 확인할 수 있다","오픈 API는 사용자가 표준화된 조달데이터로 웹서비스나 모바일 앱을 만들려는 목적으로 활용할 수 있다","데이터 보고서와 오픈 API가 지역별 분포를 그래프로 보여 주므로 별도의 데이터 시각화 기능은 제공되지 않는다"],answer:3,explanation:"데이터 보고서와 오픈 API는 기본적으로 문자 기반 정보라 그래프 같은 시각 정보는 제한됩니다. 수요기관·세부품명의 지역 분포나 그래프 비교가 필요하면 '데이터 시각화' 메뉴를 씁니다."},
{id:"P2-088",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"발주계획 정보",ss:"2-1-2-2",tag:["공급정보","발주계획"],difficulty:"중",question:"공급업체의 공급정보 수집 시점에 관한 설명으로 가장 적절한 것은?",options:["입찰공고가 게시된 때가 공급정보를 얻을 수 있는 가장 이른 시점이다","전자조달시스템에 공개되는 분기별 발주계획을 미리 확인하면 입찰공고 전부터 수요기관·발주시기·규모를 파악해 준비기간을 더 확보할 수 있다","발주계획은 조달청 중앙조달분만 공개되므로 지방자치단체 자체조달 사업은 입찰공고 이전에 확인할 방법이 없다","발주계획 정보는 입찰 준비기간 확보에만 쓰일 뿐 무효입찰이나 부적격 입찰 예방과는 관계가 없다"],answer:1,explanation:"국가계약법 시행령상 분기별 발주계획은 전자조달시스템 등에 공개해야 합니다. 이를 미리 보면 입찰공고 뒤 짧은 기간에 급히 준비하는 것보다 훨씬 긴 준비기간을 얻고, 자격·역량을 미리 점검해 무효·부적격 입찰도 막을 수 있습니다. 지방자치단체 발주계획도 나라장터나 자치단체 홈페이지에서 확인할 수 있습니다.",basis:"국가계약법 시행령 제92조의2 제1항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제92조의2"},
{id:"P2-089",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"수요예측 기능",ss:"2-1-4-1",tag:["수요예측","데이터"],difficulty:"중",question:"조달데이터허브의 데이터 분석 기능을 활용한 수요예측에 관한 설명으로 옳지 않은 것은?",options:["공공조달 수요예측 결과는 확정된 실적이므로 다른 계약 실적 자료와 교차 검증할 필요가 없다","쇼핑몰키워드 분석으로 세부품명 키워드의 검색량과 수요기관별 납품 실적을 확인할 수 있다","공공조달 수요예측은 중앙조달과 자체조달로 나누어 수요 규모의 변화 추세를 연간·월간 단위로 보여 준다","입찰혼잡도 예측은 일자별·시간대별 혼잡도를 보여 주어 입찰이 몰리지 않는 때를 고르도록 돕는다"],answer:0,explanation:"수요예측 기능은 공공조달 빅데이터로 추정한 전망이라 정확하지 않을 수 있습니다. 그래서 데이터 보고서의 조달대상물별·세부품명별 계약 실적과 함께 보며 교차 검증해 쓰는 것이 효과적입니다."},
{id:"P2-090",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"2단계입찰 장단점",ss:"2-1-4-2",tag:["조달방법","장단점"],difficulty:"중",question:"2단계입찰(Two-Stage Tendering) 방식의 단점으로 보기 어려운 것은?",options:["입찰 절차가 두 단계로 진행되어 조달 대상물의 공급 시점까지 오래 걸릴 수 있다","기술사양 협상과 과업 범위 확정 과정에서 가격이 오르거나 수요기관과 조달기업이 대립할 수 있다","1단계에서 입찰자의 자격이 검증되므로 계약 이행 역량 면에서 신뢰성이 높다","우선협상대상자가 정해지면 경쟁이 끝나므로 협상 결과에 따라 계약가격이 오를 수 있다"],answer:2,explanation:"1단계에서 자격이 검증되어 이행 역량의 신뢰성이 높다는 것은 2단계입찰의 장점입니다. 나머지는 긴 소요기간, 가격 인상·대립 가능성, 경쟁 종료 뒤 가격 상승 영향으로 모두 단점입니다."},
{id:"P2-091",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"견적요청 장단점",ss:"2-1-4-2",tag:["조달방법","장단점"],difficulty:"중",question:"견적요청(RFQ) 방식의 장단점에 관한 설명으로 옳지 않은 것은?",options:["입찰서류 준비나 입찰공고가 필요 없어 조달 기간을 크게 줄일 수 있다","특정 기업에서 빨리 공급받기 위해 수량·금액을 나누는 식으로 오남용될 수 있다","다양한 기업으로부터 공급받지 못하고 특정 소수 기업에 의존하게 될 수 있다","요구사항이 정해지지 않은 복잡하거나 혁신적인 조달사업에 특히 적합하다"],answer:3,explanation:"견적요청은 요건이 명확하고 가격 비교가 중심일 때 쓰는 방식이라 복잡하거나 혁신적인 조달사업에는 맞지 않습니다. 기간 단축은 장점, 분할 오남용과 소수 기업 의존은 단점입니다."},
{id:"P2-092",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"사업예산 경제성 분석",ss:"2-2-2-2",tag:["사업예산","원가"],difficulty:"중",question:"공급업체가 공개된 사업예산의 경제적 적정성을 분석하는 방법으로 옳지 않은 것은?",options:["먼저 사업예산(기초금액)의 내역과 부가가치세 포함 여부를 확인한다","사업예산이 원가계산 금액보다 크면 계약조건 준수나 납품일정 때문에 생기는 추가 비용은 따로 검토하지 않아도 된다","예정가격작성기준에 따라 원가계산한 금액(일반관리비·이윤 포함)이 사업예산을 넘으면 1차적으로 경제적 적정성이 낮다고 볼 수 있다","사업예산이 재료비·노무비·경비 같은 순원가를 넘으면 일반관리비와 이윤 수준을 조정해 대안적으로 검토할 수 있다"],answer:1,explanation:"명목상 금액만 맞는지 볼 것이 아니라 계약조건 준수, 납품기간 등에서 생길 수 있는 숨은 비용까지 따져야 계약 뒤 부실 이행이나 불이행을 막을 수 있습니다. 나머지 셋은 교재의 기초검토·원가계산 분석 방법 그대로입니다."},
{id:"P2-093",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"예산 부족 시 대응",ss:"2-2-2-2",tag:["사업예산","사전규격"],difficulty:"중",question:"사전규격공개 단계에서 공개된 사업예산이 요구 과업에 비해 지나치게 적다고 판단될 때 공급업체의 대응으로 가장 적절한 것은?",options:["원가계산 등 근거자료를 갖추어 사전규격 의견으로 등록해 개선을 요청한다","일단 입찰에 참가하고, 낙찰되면 계약 이행 중에 계약금액 증액을 요구한다","의견을 내지 않고 개찰 결과를 본 뒤 이의를 제기한다","발주기관 담당자에게 사적으로 연락해 예산 증액을 부탁한다"],answer:0,explanation:"문제를 알면 사전규격공개나 입찰마감 전에 공식 의견을 내는 것이 원칙입니다. 알고도 참가해 계약한 뒤 문제 삼으면 자유로운 합의로 계약했다는 점 때문에 인정받기 어렵고, 사적 접촉은 부패·불공정 행위가 될 수 있습니다."},
{id:"P2-094",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"새로 공고와 정정공고",ss:"2-2-3-1",tag:["입찰공고","정정"],difficulty:"상",question:"「지방자치단체 입찰 및 계약 집행기준」상 입찰공고 후 개찰 전에 공고문의 착오·오류를 발견한 경우의 처리로 옳은 것은?",options:["입찰참가자격에 중대한 착오가 있으면 정정공고로 바로잡고 남은 공고기간대로 진행한다","예정가격에 중대한 오류가 있어도 개찰 뒤 낙찰자 결정 단계에서 고치면 된다","관련 법령을 잘못 적은 경미한 하자가 있으면 정정공고를 하되, 남은 공고기간에 5일 이상을 더해 공고한다","정정공고는 새로운 입찰공고로 보므로 공고기간을 처음부터 다시 계산한다"],answer:2,explanation:"사업내용·예정가격·입찰참가자격·입찰 및 계약조건에 중대한 착오·오류가 있으면 공고를 취소하고 새로 공고합니다. 단순 법규 위반이나 법령 오기 같은 경미한 하자는 정정공고를 하며, 남은 공고기간에 5일 이상을 더합니다. 이런 처리는 개찰 전까지 합니다.",basis:"지방자치단체 입찰 및 계약 집행기준 제1장 제1절 3. 가",basisUrl:"https://www.law.go.kr/행정규칙/지방자치단체입찰및계약집행기준"},
{id:"P2-095",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"시스템 게시 내용과 공고문 불일치",ss:"2-2-3-1",tag:["입찰공고","전자조달"],difficulty:"상",question:"나라장터에 게시된 내용에는 낙찰자 결정방법이 '적격심사'로, 붙임 파일 입찰공고문에는 '협상에 의한 계약'으로 적혀 있다. 공고일도 나라장터 게시일은 9월 1일, 공고문에 적힌 날은 8월 29일로 다르다. 「전자조달법 시행령」상 적용 기준으로 옳은 것은?",options:["낙찰자 결정방법: 적격심사 / 공고일: 9월 1일","낙찰자 결정방법: 협상에 의한 계약 / 공고일: 8월 29일","낙찰자 결정방법: 협상에 의한 계약 / 공고일: 9월 1일","낙찰자 결정방법: 적격심사 / 공고일: 8월 29일"],answer:2,explanation:"전자조달시스템 게시 내용과 붙임 입찰공고문이 다르면 입찰공고문 내용이 우선합니다. 다만 입찰공고일만은 전자조달시스템에 게시한 날이 우선합니다. 이런 불일치는 자격·낙찰에 영향을 주므로 발견하면 정정을 요청하는 것이 좋습니다.",basis:"전자조달법 시행령 제4조 제3항",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률시행령/제4조"},
{id:"P2-096",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"문의처 구분",ss:"2-2-4-2",tag:["정보요청","입찰공고"],difficulty:"하",question:"입찰공고문의 보충정보 제공처를 활용해 필요한 정보를 요청하는 방법으로 가장 적절한 것은?",options:["구매 물품의 상세 사양은 계약부서(회계과)에, 입찰 관련 법령·절차는 사업부서에 문의한다","나라장터 이용 방법 같은 일반 문의는 수요기관 감사부서에 문의한다","부서 구분 없이 발주기관 담당자에게 사적으로 연락해 정보를 얻는 것이 가장 빠르다","구매 물품의 상세 사양은 사업부서에, 입찰·계약 관련 법령·절차는 계약부서에 문의한다"],answer:3,explanation:"구매사양 등 물품 상세 정보는 그 물품을 실제로 쓰는 사업부서가, 입찰·계약 법령과 절차는 계약부서가 담당합니다. 나라장터 이용 문의는 조달청 전자조달 콜센터를 이용하고, 사적 접촉은 부패·비리의 당사자가 될 위험이 있어 피해야 합니다."},
{id:"P2-097",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"입찰설명회 정보 확인",ss:"2-2-4-2",tag:["정보요청","설명회"],difficulty:"중",question:"입찰설명회를 통한 정보 식별·요청에 관한 설명으로 가장 적절한 것은?",options:["최신 정보를 주기 위해 입찰설명회는 입찰마감 직전에 여는 것이 일반적이다","설명회에서 나온 질문과 답변은 문서로 정리해 참석 업체와 공유하고, 중요한 내용은 입찰공고문 등에 반영한다","입찰공고문에 참석 의무가 명시되어 있어도 불참한 업체는 제한 없이 입찰에 참가할 수 있다","설명회에서는 기술적 사항만 질의할 수 있고 조달 절차에 관한 질의는 할 수 없다"],answer:1,explanation:"설명회 질의응답은 문서화해 공유하고 핵심 내용은 공고문에 반영해 누락·오류를 막습니다. 설명회는 보통 공고 후 7일 내외, 마감 최소 2주 전에 열리며, 참석 의무가 명시된 경우에는 반드시 참석해야 입찰에 참가할 수 있습니다. 절차 측면과 기술 측면 질의응답을 모두 진행합니다."},
{id:"P2-098",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"지명경쟁입찰 절차",ss:"2-3-1-1",tag:["지명경쟁","절차"],difficulty:"중",question:"국가계약법 시행령상 지명경쟁입찰에 부칠 때 입찰대상자 지명에 관한 설명으로 옳은 것은?",options:["5인 이상을 지명하여 2인 이상의 입찰참가신청이 있어야 하며, 지명대상자가 5인 미만이면 대상자를 모두 지명해야 한다","3인 이상을 지명하여 1인 이상의 입찰참가신청이 있으면 된다","10인 이상을 지명하여 3인 이상의 입찰참가신청이 있어야 한다","지명 인원에는 제한이 없고 계약담당공무원이 자유롭게 1인만 지명할 수도 있다"],answer:0,explanation:"지명경쟁입찰은 5인 이상을 지명하고 2인 이상이 입찰참가신청을 해야 합니다. 지명할 수 있는 대상자가 5인 미만이면 모두 지명해야 합니다. 지명한 대상자에게는 입찰공고 사항(시행령 제36조 각 호)을 통지합니다.",basis:"국가계약법 시행령 제24조 제1항·제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제24조"},
{id:"P2-099",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"재입찰과 재공고입찰",ss:"2-3-1-1",tag:["경쟁입찰","절차"],difficulty:"중",question:"국가계약법 시행령상 재입찰과 재공고입찰에 관한 설명으로 옳지 않은 것은?",options:["경쟁입찰에서 2인 이상의 유효한 입찰자가 없거나 낙찰자가 없으면 재입찰에 부칠 수 있다","재입찰은 새로운 입찰로 보지 않으며, 입찰자나 입찰횟수의 제한을 받지 않는다","재공고입찰 때에는 최초 입찰의 가격과 그 밖의 조건을 필요에 따라 자유롭게 바꿀 수 있다","낙찰자가 계약을 체결하지 않는 경우에는 재공고입찰에 부칠 수 있다"],answer:2,explanation:"재입찰이나 재공고입찰 때에는 기한을 제외하고 최초 입찰에 정한 가격과 그 밖의 조건을 바꿀 수 없습니다. 조건을 바꾸면 사실상 다른 입찰이 되어 처음 참가를 포기한 업체와 형평이 맞지 않기 때문입니다.",basis:"국가계약법 시행령 제20조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제20조"},
{id:"P2-100",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"재공고 유찰 후 수의계약",ss:"2-3-1-2",tag:["수의계약","절차"],difficulty:"중",question:"국가계약법 시행령상 재공고입찰에서도 입찰자나 낙찰자가 없어 수의계약을 하는 경우에 관한 설명으로 옳은 것은?",options:["수의계약이므로 가격과 계약조건을 계약상대자와 새로 협의해 정할 수 있다","최초 입찰에 정한 가격보다 높은 가격으로만 계약할 수 있다","재공고입찰을 한 번 더 실시해야만 수의계약을 할 수 있다","보증금과 기한을 제외하고는 최초 입찰에 부칠 때 정한 가격과 그 밖의 조건을 바꿀 수 없다"],answer:3,explanation:"경쟁입찰이 두 번(최초·재공고) 유찰되어 수의계약으로 넘어가도 보증금과 기한만 바꿀 수 있고, 최초 입찰의 가격과 그 밖의 조건은 그대로 유지해야 합니다.",basis:"국가계약법 시행령 제27조 제1항 제2호·제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제27조"},
{id:"P2-101",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"수의계약 견적 절차",ss:"2-3-1-2",tag:["수의계약","견적"],difficulty:"중",question:"국가계약법 시행령상 수의계약의 견적 절차에 관한 설명으로 옳지 않은 것은?",options:["수의계약을 체결하려면 원칙적으로 2인 이상으로부터 견적서를 받아야 한다","견적가격이 예정가격의 범위를 벗어나더라도 수의계약이므로 그 견적가격대로 계약할 수 있다","추정가격이 2천만원 이하인 경우 등에는 1인으로부터 받은 견적서에 의할 수 있다","전자조달시스템으로 견적서를 제출받는 경우에는 그 제출에 관한 사항을 전자조달시스템으로 안내공고해야 한다"],answer:1,explanation:"견적가격이 예정가격 범위에 들지 않는 등 계약상대자를 정할 수 없으면 다시 견적서를 받아 계약금액을 정해야 합니다. 2인 이상 견적 원칙, 2천만원 이하 등 1인 견적 예외, 전자견적 시 안내공고는 모두 맞는 설명입니다.",basis:"국가계약법 시행령 제30조 제1항·제3항·제6항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제30조"},
{id:"P2-102",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"규격·기술 적격자",ss:"2-3-3-1",tag:["2단계경쟁","규격적격자"],difficulty:"상",question:"국가계약법령상 2단계 경쟁입찰과 규격·가격 동시입찰에 관한 설명으로 옳지 않은 것은?",options:["동시입찰에서 규격적격자로 확정된 자가 1인뿐이면 가격입찰서를 개봉할 수 없고 반드시 재공고입찰을 해야 한다","먼저 규격 또는 기술입찰을 실시한 뒤, 개찰 결과 적격자로 확정된 자에게만 가격입찰 참가 자격을 준다","규격과 가격을 동시에 입찰하는 경우 규격입찰 개찰 결과 적격자로 확정된 자의 가격입찰서만 개찰한다","이러한 입찰을 하려면 입찰 전에 평가기준과 절차를 정해 입찰 참가 희망자가 열람할 수 있게 해야 한다"],answer:0,explanation:"규격입찰이 2인 이상의 유효한 입찰로 성립했다면, 개찰 결과 규격(기술)적격자가 1인이어도 가격입찰서를 개봉할 수 있습니다. 나머지는 시행령 제18조의 내용 그대로입니다.",basis:"국가계약법 시행령 제18조, 시행규칙 제48조 제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제48조"},
{id:"P2-103",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"우선협상대상자 동점 처리",ss:"2-3-3-1",tag:["협상계약","우선협상대상자"],difficulty:"상",question:"협상에 의한 계약체결기준상 협상적격자의 기술능력평가 점수와 입찰가격평가 점수의 합산점수가 같은 제안자가 2인 이상일 때 우선순위를 정하는 방법으로 옳은 것은?",options:["입찰가격이 낮은 제안자를 우선순위자로 하고, 가격도 같으면 추첨한다","곧바로 추첨으로 우선순위자를 정한다","기술능력 평가점수가 높은 제안자를 우선순위자로 하고, 그것도 같으면 기술능력 세부평가항목 중 배점이 큰 항목에서 높은 점수를 얻은 자를 우선순위자로 한다","동점자 모두를 우선협상대상자로 정해 동시에 협상한다"],answer:2,explanation:"합산점수가 같으면 기술능력 평가점수가 높은 쪽이 앞섭니다. 기술능력 점수까지 같으면 배점이 큰 세부평가항목에서 더 높은 점수를 받은 자가 우선순위자가 됩니다. 협상은 우선순위자와 먼저 하며, 동시에 여러 명과 하지 않습니다.",basis:"(계약예규) 협상에 의한 계약체결기준 제8조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P2-104",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"기술협상의 범위",ss:"2-3-3-2",tag:["협상계약","기술협상"],difficulty:"상",question:"협상에 의한 계약체결기준상 기술(규격)협상과 그 결과에 따른 가격 조정에 관한 설명으로 옳지 않은 것은?",options:["협상대상자가 제안한 사업내용·이행방법·이행일정 등 제안서 내용을 대상으로 협상하며 그 일부를 조정할 수 있다","계약담당공무원은 협상대상자에게 해당 사업과 무관한 요구사항을 추가하거나 기술 이전을 요구하는 등 불공정한 요구를 해서는 안 된다","협상으로 제안 내용을 가감하면 그에 상당하는 금액을 사업예산(예정가격을 작성한 경우 예정가격) 범위에서 조정할 수 있다","기술협상에서 제안 내용의 가감이 없더라도 가격협상에서 협상대상자가 제안한 가격을 낮추도록 조정할 수 있다"],answer:3,explanation:"제안 내용의 가감 조정이 없으면 가격협상에서 협상대상자가 제안한 가격을 올리거나 내릴 수 없습니다. 가격협상은 기술협상으로 과업이 늘거나 줄었을 때 그만큼을 반영하는 절차이기 때문입니다.",basis:"(계약예규) 협상에 의한 계약체결기준 제11조·제12조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P2-105",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"협상기간",ss:"2-3-3-2",tag:["협상계약","기술협상"],difficulty:"중",question:"협상에 의한 계약체결기준상 협상기간에 관한 설명으로 옳은 것은?",options:["협상기간은 협상대상자에게 통보된 날부터 30일 이내로 한다","협상기간은 협상대상자에게 통보된 날부터 15일 이내로 하고, 그 기간 안에 협상이 이루어지지 않으면 10일 범위에서 연장할 수 있다","협상기간에는 제한이 없으며 협상이 성립될 때까지 계속할 수 있다","정해진 기간 안에 협상이 이루어지지 않으면 연장 없이 즉시 차순위자와 협상해야 한다"],answer:1,explanation:"협상기간은 협상대상자에게 통보된 날부터 15일 이내이고, 사업 규모·난이도 등에 따라 협의로 5일 범위에서 조정할 수 있습니다. 그 기간에 협상이 안 되면 10일 범위에서 연장할 수 있습니다.",basis:"(계약예규) 협상에 의한 계약체결기준 제13조",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P2-106",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"희망수량 낙찰자 결정 계산",ss:"2-3-4-3",tag:["희망수량","계산"],difficulty:"상",question:"다량 물품 구매를 위한 희망수량경쟁입찰에서 수요수량은 1,000개, 예정가격(단가)은 10,000원이다. 입찰 결과가 다음과 같을 때 B의 낙찰수량은?\n· A: 단가 9,000원, 400개\n· B: 단가 9,500원, 300개\n· C: 단가 9,500원, 500개\n· D: 단가 9,800원, 200개\n· E: 단가 10,500원, 600개",options:["0개","100개","200개","300개"],answer:1,explanation:"예정가격 이하 단가 중 최저가 순으로 수요수량까지 낙찰합니다. A(9,000원) 400개가 먼저, B·C는 같은 가격이라 입찰수량이 많은 C(500개)가 앞서 누계 900개가 됩니다. 다음 B는 300개 중 수요수량을 넘는 200개가 낙찰되지 않아 100개만 낙찰됩니다. D는 수량이 이미 찼고, E는 예정가격을 넘어 낙찰될 수 없습니다.",basis:"국가계약법 시행령 제46조, 시행규칙 제47조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제47조"},
{id:"P2-107",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"희망수량경쟁입찰 일반",ss:"2-3-4-3",tag:["희망수량","낙찰"],difficulty:"중",question:"국가계약법령상 희망수량경쟁입찰에 관한 설명으로 옳지 않은 것은?",options:["다량의 물품을 매각할 때에는 예정가격 이하의 단가로 입찰한 자 중 최저가격 입찰자 순으로 매각수량까지 낙찰자를 정한다","희망수량경쟁입찰의 예정가격은 해당 물품의 단가로 정한다","2종 이상의 물품을 희망수량경쟁입찰에 부칠 때에는 물품 종류별로 단가와 수량을 입찰하게 해야 한다","1인의 능력이나 생산시설로는 공급이 불가능하거나 곤란한 다량의 동일물품을 제조·구매할 때 활용할 수 있다"],answer:0,explanation:"매각은 파는 것이므로 예정가격 이상의 단가로 입찰한 자 중 최고가격 입찰자 순으로 매각수량에 도달할 때까지 낙찰자를 정합니다. 예정가격 이하·최저가 순은 제조·구매의 경우입니다.",basis:"국가계약법 시행령 제45조, 시행규칙 제12조·제19조·제21조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제45조"},
{id:"P3-116",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약의 기능",ss:"3-1-1-2",tag:["개념"],difficulty:"하",question:"계약의 기능 가운데, 계약 이행 과정에서 생길 수 있는 위험을 누가 부담하는지 계약서에 정해 두어 위험을 부담하지 않는 쪽의 재정적 손실을 줄여 주는 기능은?",options:["증거기능","관리기능","동기부여기능","위험전가기능"],answer:3,explanation:"위험을 누가 질지 계약서에 미리 정해 두는 것이 위험전가기능입니다. 증거기능은 '합의했다는 증거', 관리기능은 이행 행동·작업을 이끄는 역할, 동기부여기능은 이익을 얻으려는 의지로 이행을 북돋우는 역할(유인계약 등)입니다."},
{id:"P3-117",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약서 해석 순위",ss:"3-1-1-2",tag:["개념"],difficulty:"중",question:"계약서 내용의 의미가 분명하지 않을 때 적용하는 계약서 해석 우선순위의 일반원칙으로 옳지 않은 것은?",options:["계약서의 특정 조항이 민법의 일반원칙에 위배되는 것이 명백하더라도 계약서 조항이 우선 적용된다","특수조건은 일반조건에 우선하여 적용된다","계약당사자 간 합의로 추가된 수기 문구나 별도로 명시한 문구는 기본 문서에 우선하여 적용된다","강행규정은 일반규정보다 우선하여 적용된다"],answer:0,explanation:"계약서에 적힌 사항은 원칙적으로 민법의 일반원칙보다 먼저 적용되지만, 어떤 조항이 민법 일반원칙에 명백히 어긋나면 그 조항은 적용되지 않습니다. 나머지 셋(특수조건 우선, 수기·별도 문구 우선, 강행규정 우선)은 교재가 든 일반원칙 그대로입니다."},
{id:"P3-118",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약상대자 귀책 해제·해지",ss:"3-1-2-3",tag:["법령","절차"],difficulty:"중",question:"물품구매(제조)계약일반조건상 계약상대자의 책임 있는 사유로 계약을 해제 또는 해지하는 경우에 관한 설명으로 옳지 않은 것은?",options:["지체상금이 계약보증금상당액에 이르렀더라도 이행 가능성이 있고 계약 유지가 필요하다고 인정되어, 계약상대자가 이행되지 않은 부분에 상당하는 계약보증금을 추가로 내면 계약을 유지한다","계약상대자가 낸 계약보증금은 해제·해지와 함께 계약상대자에게 돌려준다","해제·해지할 때에는 그 사실을 계약상대자에게 통지하고, 기납부분 검사를 마친 물품을 인수한 경우에는 그 부분에 상당하는 대가를 지급한다","계약상대자는 받은 선금에 미정산잔액이 있으면 그 잔액에 약정이자상당액을 더해 발주기관에 상환해야 한다"],answer:1,explanation:"계약상대자가 정당한 이유 없이 계약상 의무를 이행하지 않으면 계약보증금은 국고에 귀속됩니다(제8조①). 계약보증금을 돌려주는 것은 발주기관 사정(사정변경)으로 해제·해지할 때입니다. 계약 유지를 위한 추가 계약보증금은 당초 계약보증금에 지체상금 최대금액을 더한 금액이 한도입니다.",basis:"(계약예규) 물품구매(제조)계약일반조건 제26조 제1항·제2항·제4항, 제8조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
{id:"P3-119",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"사정변경 해제·해지",ss:"3-1-2-3",tag:["법령","절차","숫자"],difficulty:"중",question:"물품구매(제조)계약일반조건상 객관적으로 명백한 발주기관의 불가피한 사정으로 계약을 해제 또는 해지하는 경우(사정변경에 의한 해제·해지)에 관한 설명으로 옳은 것은?",options:["계약상대자가 납품기한 안에 물품을 납품하지 못한 경우가 대표적인 사유이다","과다한 지역 민원 제기로 사업이 취소된 경우에도 해당하며, 발주기관은 해제·해지한 날부터 14일 이내에 미지급 대가와 투입된 인력·재료·장비의 철수비용을 지급하고 계약보증금을 함께 반환해야 한다","계약보증금은 국고에 귀속하고, 이미 납품된 부분의 미지급 대가만 지급한다","계약상대자는 선금 미정산잔액에 약정이자상당액을 더해 상환해야 한다"],answer:1,explanation:"사정변경 사유는 정부정책 변화·관계 법령 제·개정·과다한 지역 민원으로 인한 사업취소, 공공복리에 따른 사업 변경 등입니다. 이때는 14일 이내에 미지급 대가와 철수비용을 주고 계약보증금도 돌려줍니다. 선금 미정산잔액은 상환받지만 이자는 더하지 않습니다. 납품기한 내 미납품은 계약상대자 책임 사유(제26조)입니다.",basis:"(계약예규) 물품구매(제조)계약일반조건 제27조",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)물품구매(제조)계약일반조건"},
{id:"P3-120",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"해제·해지와 손해배상",ss:"3-1-2-4",tag:["법령","개념"],difficulty:"중",question:"계약의 해제·해지와 손해배상에 관한 설명으로 옳지 않은 것은?",options:["계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 않는다","수급인이 일을 완성하기 전에는 도급인은 손해를 배상하고 계약을 해제할 수 있다","계약을 해제하면 계약이 소급하여 소멸하므로, 해제한 당사자는 더 이상 상대방에게 손해배상을 청구할 수 없다","합의해제·해지의 경우, 손해배상에 관한 특약이나 청구 유보가 없으면 원칙적으로 채무불이행에 따른 손해배상을 청구할 수 없는 것으로 본다"],answer:2,explanation:"민법 제551조에 따라 해제·해지를 해도 손해배상 청구는 그대로 할 수 있습니다. 그래서 '해제하면 손해배상을 청구할 수 없다'는 틀렸습니다. 도급인은 일이 완성되기 전이면 손해를 배상하고 해제할 수 있고(제673조), 당사자가 합의해서 해제한 경우에는 따로 약정이 없으면 손해배상을 청구할 수 없다고 봅니다.",basis:"민법 제551조, 제673조",basisUrl:"https://www.law.go.kr/법령/민법/제551조"},
{id:"P3-121",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약상대자 해지 후 조치",ss:"3-1-2-4",tag:["법령","절차","숫자"],difficulty:"상",question:"공사계약일반조건상 공사내용 변경으로 계약금액이 100분의 40 이상 감소하여 계약상대자가 계약을 해지한 경우, 발주기관의 조치로 옳은 것은?",options:["계약상대자가 스스로 해지한 것이므로 계약보증금을 국고에 귀속한다","선금 미정산잔액이 있으면 약정이자상당액을 더해 상환받는다","해지로 생긴 손해는 계약상대자가 부담하므로 기성부분 대가는 지급하지 않는다","시공부분 대가 중 지급하지 않은 금액과 투입된 인력·자재·장비의 철수비용을 지급하고, 계약보증금을 함께 반환한다"],answer:3,explanation:"계약금액 100분의 40 이상 감소, 공사정지기간이 공기의 100분의 50 초과 등은 계약상대자가 해제·해지할 수 있는 사유입니다(제46조①). 이때는 사정변경 해제 규정을 준용해 미지급 시공대가와 철수비용을 14일 이내에 지급하고 계약보증금을 반환하며, 선금 잔액은 상환받되 이자는 더하지 않습니다(제46조②→제45조③④).",basis:"(계약예규) 공사계약일반조건 제46조, 제45조 제3항·제4항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-122",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"성과기반 용역계약(PBSC)",ss:"3-1-3-4",tag:["개념"],difficulty:"중",question:"성과기반 용역계약(PBSC: Performance Based Service Contract)의 특징으로 옳지 않은 것은?",options:["용역 자체보다 용역지원의 성과 결과를 구매하는 방식이다","측정 가능한 요구 성과를 제시하고, 성과평가 결과에 따라 인센티브나 페널티를 준다","수행 방법을 상세히 규정한 과업기술서를 제시하고, 투입된 인력과 시간을 기준으로 대가를 지급하는 것이 핵심이다","주로 장기계약으로 체결하여 업체가 안정적으로 투자하고 원가를 낮출 수 있게 한다"],answer:2,explanation:"PBSC는 수행 방법이나 넓고 모호한 과업기술서 대신 측정 가능한 성과를 요구하고, 그 성과(결과)를 삽니다. 투입 인력·시간을 기준으로 값을 치르는 것은 PBSC와 반대되는 설명입니다. 성과지표를 객관적으로 만들기 어렵다는 것이 약점입니다."},
{id:"P3-123",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"서비스수준관리(SLM)",ss:"3-1-3-4",tag:["개념"],difficulty:"중",question:"IT서비스 분야의 서비스수준관리(SLM)에서, 서비스를 효율적으로 제공하기 위해 내부 공급자(조직) 사이에 지켜야 할 약정 사항을 적은 문서는?",options:["서비스수준협약(SLA)","운영수준협약(OLA)","외부공급계약(UC)","서비스 카탈로그"],answer:1,explanation:"OLA는 서비스에 관련된 내부 운영조직끼리 맺는 약정입니다. SLA는 서비스 제공업체와 이용자(고객)가 서비스 수준을 합의한 것, UC는 외부 공급업체와 맺는 계약, 서비스 카탈로그는 제공하는 모든 서비스의 목록 문서입니다."},
{id:"P3-124",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"입찰참가자격 등록",ss:"3-2-1-1",tag:["법령"],difficulty:"중",question:"국가계약법 시행규칙상 경쟁입찰참가자격의 등록에 관한 설명으로 옳은 것은?",options:["물품 제조로 등록하려는 자도 공장등록대장 등본이나 직접생산 확인 증명서류는 낼 필요가 없다","각 중앙관서의 장은 자기 관서의 경쟁입찰업무에만 쓰기 위한 등록은 받을 수 없다","전자조달시스템에 게재된 등록사항은 다른 중앙관서의 장 또는 계약담당공무원에게도 등록한 것으로 본다","등록사항에 변동이 있으면 낙찰된 뒤 계약 체결 전까지만 변경등록하면 된다"],answer:2,explanation:"나라장터(전자조달시스템)에 한 번 등록하면 다른 기관에도 등록한 것으로 봅니다(제15조⑤). 제조 등록에는 공장등록대장 등본이나 직접생산 확인 서류가 필요하고(②2호마목), 자기 관서 전용 등록도 받을 수 있으며(⑥), 변동 사항은 입찰 참가 전에 미리 변경등록해야 합니다(⑦3호).",basis:"국가계약법 시행규칙 제15조 제2항·제5항·제6항·제7항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행규칙/제15조"},
{id:"P3-125",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"제조물품 등록 유효기간",ss:"3-2-1-1",tag:["숫자"],difficulty:"중",question:"「국가종합전자조달시스템 입찰참가자격등록규정」상 제조물품 입찰참가자격 등록의 유효기간은? (허가·면허 등이나 제출서류에 따로 유효기간이 있는 경우는 제외)",options:["등록일부터 3년","등록일부터 1년","등록일부터 2년","등록일부터 5년"],answer:0,explanation:"제조물품 입찰참가자격 등록은 등록일부터 3년간 유효하고, 기간이 지나기 전에 갱신등록해야 합니다. 지나면 등록 효력이 없어집니다. '1년'은 등록자가 자기 정보를 스스로 확인·정비하는 자기정보확인등록 주기입니다.",basis:"국가종합전자조달시스템 입찰참가자격등록규정 제9조 제1항 제1호·제2항, 제4조 제2항",basisUrl:"https://www.law.go.kr/행정규칙/국가종합전자조달시스템입찰참가자격등록규정"},
{id:"P3-126",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 적격심사 낙찰자 결정",ss:"3-2-1-3",tag:["법령","숫자"],difficulty:"중",question:"조달청 물품구매적격심사 세부기준상 낙찰자 결정에 관한 설명으로 옳은 것은?",options:["최저가 입찰자에 대한 심사 결과 종합평점이 85점 이상이면 낙찰자로 결정한다","최저가 입찰자의 종합평점이 95점 이상이어야 낙찰자로 결정한다","최저가 입찰자의 종합평점이 기준에 못 미치면 입찰을 무효로 하고 재공고한다","입찰가격 점수에 다른 분야 배점한도를 모두 더해도 통과점수에 못 미치는 입찰자도 반드시 적격심사 서류를 내야 한다"],answer:0,explanation:"조달청 물품 적격심사는 종합평점 85점 이상이면 낙찰입니다(95점은 공사 적격심사 기준). 최저가 입찰자가 85점에 못 미치면 재공고가 아니라 차순위 최저가 입찰자 순으로 심사합니다. 만점을 더해도 통과점수가 안 되는 입찰자는 서류 제출을 생략합니다. 이 구조에서 낙찰하한율은 고시금액 미만 86.245%, 고시금액 이상 82.495%입니다.",basis:"조달청 물품구매적격심사 세부기준 제9조 제1항·제3항, 제3조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/조달청물품구매적격심사세부기준"},
{id:"P3-127",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"희망수량 경쟁입찰",ss:"3-2-1-3",tag:["법령","절차"],difficulty:"중",question:"국가계약법 시행령상 다량의 물품을 희망수량에 따라 분할하여 구매하는 일반경쟁입찰(희망수량 경쟁입찰)의 낙찰자 결정 방법으로 옳은 것은?",options:["예정가격 이상의 단가로 입찰한 자 중 최고가격으로 입찰한 자 순으로 수요수량에 도달할 때까지 낙찰자로 한다","예정가격 이하의 단가로 입찰한 자 중 최저가격으로 입찰한 자 순으로 수요수량에 도달할 때까지 낙찰자로 한다","낙찰될 수 있는 동일가격 입찰자가 2인 이상이면 입찰수량이 적은 자를 낙찰자로 한다","총액이 가장 낮은 1인만을 낙찰자로 하여 전체 수량을 계약한다"],answer:1,explanation:"구매(제조·임차)는 예정가격 이하 단가 중 최저가격 순으로 수요수량이 찰 때까지 여러 명을 낙찰자로 합니다(제46조). '예정가격 이상 중 최고가격 순'은 다량물품을 팔 때(매각, 제45조)입니다. 동일가격이면 입찰수량이 많은 자, 수량도 같으면 추첨입니다(제47조①1호).",basis:"국가계약법 시행령 제46조, 제47조 제1항 제1호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제46조"},
{id:"P3-128",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"품질보증조달물품",ss:"3-2-2-1",tag:["개념","품질"],difficulty:"하",question:"조달업체의 품질경영·공정관리·성과관리 등 품질관리 능력을 평가하여, 우수한 품질보증 체계에서 생산된 제품을 지정하고 납품검사 면제 등의 혜택을 주는 조달청 제도는?",options:["안전관리물자 지정제도","우수조달물품 지정제도","품질보증조달물품 지정제도","직접생산확인제도"],answer:2,explanation:"업체 스스로 품질을 관리하는 능력(품질경영·공정관리·성과관리)을 평가해 지정하는 것이 품질보증조달물품 제도이고, 지정되면 유효기간 동안 납품검사를 면제받을 수 있습니다. 안전관리물자는 국민 안전·보건 관련 물자를 지정해 품질관리를 강화하는 제도, 직접생산확인은 실제로 직접 생산했는지 확인하는 제도입니다.",basis:"조달청 품질보증조달물품 지정 및 관리규정 제1조, 제18조",basisUrl:"https://www.law.go.kr/행정규칙/품질보증조달물품지정및관리규정"},
{id:"P3-129",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"조달물자 품질점검",ss:"3-2-2-1",tag:["법령","품질"],difficulty:"상",question:"「조달물자 품질점검 업무규정」상 품질점검에 관한 설명으로 옳지 않은 것은?",options:["점검공무원이 수요기관 납품장소에서 시험용 시료를 채취하면 계약상대자는 그 수요기관에 같은 물품을 무상으로 대체 공급해야 한다","시료는 KS 샘플링 방법과 최소 수량에 대표성을 부여하는 방법 중 계약상대자가 선택한 방법으로 채취한다","채취한 시료가 규격미달이면 그 시료의 세부품명 전체를 규격미달로 판정한다","계약상대자가 반환받은 시험용 시료로 자체 시험한 결과가 적합이면 이를 점검결과에 반영하여 규격미달 판정을 바꿀 수 있다"],answer:3,explanation:"반환된 시료나 임의의 시료로 계약상대자가 시험한 결과는 점검결과에 반영할 수 없습니다(제11조④). 무상 대체 공급(제8조②), 계약상대자가 고른 채취 방법(제11조①), 세부품명 전체 규격미달 판정(제17조①)은 모두 규정 그대로입니다.",basis:"조달물자 품질점검 업무규정 제8조 제2항, 제11조 제1항·제4항, 제17조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/조달물자품질점검업무규정"},
{id:"P3-130",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"2단계 경쟁·규격가격 동시입찰",ss:"3-3-1-3",tag:["법령","절차"],difficulty:"중",question:"용역계약의 2단계 경쟁입찰 및 규격(기술)·가격 동시입찰에 관한 설명으로 옳지 않은 것은?",options:["규격(기술) 적격자로 확정된 자 가운데 기술평가 점수와 입찰가격 점수를 합산하여 가장 높은 자를 낙찰자로 결정한다","미리 적절한 규격 등을 작성하기 곤란한 경우 먼저 규격 또는 기술입찰을 실시한 후 가격입찰을 실시할 수 있다","2단계 경쟁입찰에서는 규격 또는 기술입찰을 개찰한 결과 적격자로 확정된 자에 한하여 가격입찰에 참가할 자격을 준다","동시입찰에서 2인 이상의 유효한 입찰로 성립한 기술입찰의 개찰 결과 기술적격자가 1인이어도 가격입찰서를 개봉할 수 있다"],answer:0,explanation:"이 방식은 규격(기술) 적격자로 확정된 자 중 예정가격 이하 최저가격 입찰자를 낙찰자로 합니다(시행령 제42조③). 기술·가격 점수를 합산해 고르는 것은 협상에 의한 계약 등의 방식입니다. 나머지 셋은 시행령 제18조①②와 시행규칙 제48조② 내용입니다.",basis:"국가계약법 시행령 제18조 제1항~제3항, 제42조 제3항 / 시행규칙 제48조 제2항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제18조"},
{id:"P3-131",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"용역 종합심사낙찰제 대상",ss:"3-3-1-3",tag:["법령","숫자"],difficulty:"상",question:"국가계약법 시행령상 입찰가격·용역수행능력·사회적 책임 등을 종합 심사하여 낙찰자를 결정하는(종합심사낙찰제) 용역에 해당하는 것은?",options:["추정가격 20억원 이상인 기본설계 용역","추정가격 50억원 이상인 건설사업관리 용역","추정가격 30억원 이상인 실시설계 용역","추정가격이 고시금액 이상인 모든 학술연구용역"],answer:1,explanation:"종합심사 대상 용역은 건설사업관리 용역 50억원 이상, 건설공사기본계획·기본설계 용역 30억원 이상, 실시설계 용역 40억원 이상입니다. 기본설계 20억원, 실시설계 30억원은 기준보다 낮고, 학술연구용역은 대상이 아닙니다.",basis:"국가계약법 시행령 제42조 제4항 제3호~제5호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제42조"},
{id:"P3-132",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"제안서 발표·질의응답",ss:"3-3-1-4",tag:["절차","숫자"],difficulty:"상",question:"「조달청 협상에 의한 계약 제안서평가 세부기준」상 사업관리자(PM)가 제안서를 발표하고 질의에 답변하도록 입찰공고에 정한 경우, 추정가격 5억원 미만 사업을 온라인으로 평가할 때의 진행 방식은?",options:["제안서 발표 → 평가위원 질의 → 입찰자 답변","제안서 발표만 하고 질의응답은 생략한다","입찰자가 참석하지 않아도 제안서 발표 영상을 내면 발표로 인정한다","제안서 발표 없이 평가위원 질의와 입찰자 답변만 한다"],answer:3,explanation:"오프라인(혼합 포함) 평가나 추정가격 5억원 이상 온라인 평가는 '발표 → 질의 → 답변'으로 하고, 5억원 미만 온라인 평가는 발표 없이 질의·답변만 합니다. 입찰자가 평가에 참석하지 않으면 제출한 서면 제안서만으로 평가합니다.",basis:"조달청 협상에 의한 계약 제안서평가 세부기준 제11조 제6항",basisUrl:"https://www.law.go.kr/행정규칙/조달청협상에의한계약제안서평가세부기준"},
{id:"P3-133",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"제안서 평가점수 산출",ss:"3-3-1-4",tag:["절차"],difficulty:"중",question:"「조달청 협상에 의한 계약 제안서평가 세부기준」상 평가위원회를 12명 미만으로 구성하고 차등점수제를 적용하지 않는 경우, 입찰자별 제안서 평가점수를 산출하는 방법은?",options:["평가위원 점수 중 최고점수와 최저점수를 하나씩 제외한 나머지 점수를 산술평균한다","평가위원 전원의 점수를 산술평균한다","평가위원장의 점수에 2배 가중치를 두어 평균한다","평가위원 점수의 중앙값을 평가점수로 한다"],answer:0,explanation:"입찰자별로 최고·최저 점수를 하나씩 빼고 나머지를 산술평균합니다(같은 최고·최저 점수가 여럿이면 하나만 뺌). 극단적인 점수 한두 개가 결과를 좌우하지 않게 하려는 것입니다. 12명 이상으로 구성하면 상위 2개와 하위 2개를 뺍니다.",basis:"조달청 협상에 의한 계약 제안서평가 세부기준 제12조 제2항·제6항",basisUrl:"https://www.law.go.kr/행정규칙/조달청협상에의한계약제안서평가세부기준"},
{id:"P3-134",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"용역 적격심사 통과점수",ss:"3-3-1-6",tag:["법령","숫자"],difficulty:"상",question:"조달청 일반용역 적격심사 세부기준상 낙찰자로 결정되기 위한 종합평점이 85점이 아니라 88점 이상인 용역은?",options:["학술연구용역","시설물 청소·경비 등 시설분야용역","보험용역","소프트웨어용역 중 중소기업자간 경쟁제품"],answer:3,explanation:"일반용역 적격심사는 종합평점 85점 이상이면 낙찰이 원칙이고, 소프트웨어용역의 중소기업자간 경쟁제품과 여객 육상운송용역만 88점 이상이어야 합니다. 학술연구·시설분야·보험용역은 85점입니다.",basis:"조달청 일반용역 적격심사 세부기준 제10조 제1항",basisUrl:"https://www.law.go.kr/행정규칙/조달청일반용역적격심사세부기준"},
{id:"P3-135",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"용역 적격심사 절차",ss:"3-3-1-6",tag:["법령","절차","숫자"],difficulty:"중",question:"조달청 일반용역 적격심사 세부기준상 적격심사 절차에 관한 설명으로 옳지 않은 것은?",options:["최저가 입찰자의 종합평점이 통과점수에 못 미치면 차순위 최저가 입찰자 순서로 심사하여 낙찰자를 결정한다","적격심사서류 제출을 통보받은 입찰자는 특별히 정한 기일이 없으면 통보서를 받은 날부터 5일 이내에 서류를 제출해야 한다","부적격 통보를 받은 자가 통보일부터 3일 이내에 재심사를 요청하면 특별한 사유가 없는 한 접수일부터 3일 이내에 재심사해야 한다","재심사를 요청할 때에는 적격심사에 필요한 추가서류를 함께 내어 점수를 보완할 수 있다"],answer:3,explanation:"재심사 요청서를 받을 때는 적격심사에 필요한 추가서류를 접수할 수 없습니다(제11조③). 재심사는 처음 낸 서류로 다시 따져 보는 절차이기 때문입니다. 나머지(차순위 심사, 5일 이내 제출, 3일·3일 재심사)는 규정 그대로입니다.",basis:"조달청 일반용역 적격심사 세부기준 제4조 제2항, 제10조 제3항, 제11조",basisUrl:"https://www.law.go.kr/행정규칙/조달청일반용역적격심사세부기준"},
{id:"P3-136",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 낙찰자 결정 일반",ss:"3-4-2-2",tag:["법령"],difficulty:"중",question:"국가계약법 시행령상 공사 입찰의 낙찰자 결정에 관한 설명으로 옳지 않은 것은?",options:["국고의 부담이 되는 경쟁입찰은 예정가격 이하로서 최저가격으로 입찰한 자의 순으로 계약이행능력 등을 심사하여 낙찰자를 결정한다","추정가격 100억원 이상인 공사는 입찰가격·공사수행능력·사회적 책임 등을 종합 심사하여 합산점수가 가장 높은 자를 낙찰자로 결정한다","종합심사낙찰제에서는 예정가격을 초과하여 입찰한 자라도 공사수행능력 점수가 높으면 낙찰자가 될 수 있다","종합 심사를 위해 종합심사낙찰제심사위원회를 둘 수 있다"],answer:2,explanation:"종합심사낙찰제도 '예정가격 이하로 입찰한 입찰자 중'에서 합산점수가 가장 높은 자를 고릅니다(제42조④). 예정가격을 넘긴 입찰은 대상이 아닙니다. 100억원 미만 일반공사는 제42조①의 적격심사, 100억원 이상은 종합심사이며, 심사위원회를 둘 수 있습니다(제42조⑦).",basis:"국가계약법 시행령 제42조 제1항·제4항·제7항",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제42조"},
{id:"P3-137",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"동일가격 입찰 시 낙찰자",ss:"3-4-2-2",tag:["법령","절차"],difficulty:"중",question:"국가계약법 시행령상 제42조제1항에 따라 계약이행능력 등을 심사하여 낙찰자를 결정하는 공사 입찰에서, 낙찰될 수 있는 동일가격 입찰자가 2인 이상인 경우의 낙찰자 결정 방법은?",options:["곧바로 추첨으로 결정한다","입찰서를 먼저 제출한 자로 결정한다","계약이행능력 및 일자리창출 실적 등 심사 결과 최고점수인 자로 결정하고, 그 결과도 같으면 추첨한다","입찰수량을 많이 제시한 자로 결정한다"],answer:2,explanation:"적격심사 방식에서 동일가격이면 심사 점수가 가장 높은 자를 낙찰자로 하고, 점수까지 같을 때 추첨합니다(제47조①2호). '입찰수량이 많은 자'는 희망수량 경쟁입찰의 동일가격 처리 방법입니다.",basis:"국가계약법 시행령 제47조 제1항 제2호",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제47조"},
{id:"P3-138",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 적격심사 낙찰자 결정",ss:"3-4-2-4",tag:["법령","숫자"],difficulty:"중",question:"(계약예규) 적격심사기준상 공사의 적격심사에 관한 설명으로 옳은 것은?",options:["종합평점이 90점 이상이면 낙찰자로 결정한다","예정가격 이하 최저가 입찰자 순으로 심사하여 종합평점이 95점 이상이면 낙찰자로 결정한다","최저가 입찰자의 종합평점이 기준에 못 미치면 재공고입찰에 부친다","적격심사 서류의 제출기한은 통보받은 날부터 3일 이상으로 정하면 된다"],answer:1,explanation:"공사 적격심사는 최저가 입찰자부터 심사해 종합평점 95점 이상이면 낙찰자로 정하고, 미달하면 차순위 최저가 입찰자 순으로 심사합니다(제8조①②). 서류 제출기한은 통보받은 날부터 5일 이상이어야 하고, 보완기간이 3일 이상입니다(제4조①②).",basis:"(계약예규) 적격심사기준 제4조 제1항·제2항, 제7조 제1항, 제8조 제1항·제2항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)적격심사기준"},
{id:"P3-139",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"적격심사 대상 제외(순공사원가)",ss:"3-4-2-4",tag:["법령","숫자"],difficulty:"상",question:"(계약예규) 적격심사기준상 예정가격이 100억원 미만인 공사의 적격심사에서 심사대상에서 제외하는 입찰자는?",options:["입찰가격이 예정가격 중 재료비·노무비·경비와 그에 대한 부가가치세를 합한 금액의 100분의 98 미만인 자","입찰가격이 예정가격의 100분의 88 미만인 자","입찰가격이 추정가격의 100분의 80 미만인 자","입찰가격이 예정가격 중 일반관리비와 이윤을 합한 금액의 100분의 98 미만인 자"],answer:0,explanation:"예정가격 100억원 미만 공사는 입찰가격이 예정가격 중 재료비·노무비·경비와 그 부가가치세 합계액(순공사원가)의 98%에 못 미치면 심사하지 않습니다. 공사 원가도 안 되는 금액으로 따낸 뒤 부실하게 시공하는 것을 막기 위한 장치입니다.",basis:"(계약예규) 적격심사기준 제7조 제1항 단서",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)적격심사기준"},
{id:"P3-140",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"종합심사 동점 처리",ss:"3-4-3-1",tag:["법령","절차"],difficulty:"중",question:"(계약예규) 공사계약 종합심사낙찰제 심사기준상 종합심사 점수가 최고점인 자가 둘 이상일 때 가장 먼저 적용하는 낙찰자 결정 기준은?",options:["입찰금액이 가장 낮은 자","공사수행능력점수와 사회적책임점수의 합산점수가 높은 자","추첨으로 정한 자","최근 1년간 종합심사낙찰제로 낙찰받은 계약금액이 적은 자"],answer:1,explanation:"동점이면 ① 공사수행능력+사회적책임 합산점수가 높은 자 → ② 입찰금액이 균형가격에 가까운 자(균형가격이 예정가격의 88% 이상이면 입찰금액이 낮은 자) → ③ 공사수행능력점수 → ④ 사회적책임점수 → ⑤ 최근 1년간 종심제 낙찰금액이 적은 자 순으로 정합니다.",basis:"(계약예규) 공사계약 종합심사낙찰제 심사기준 제13조 제2항 / 국가계약법 시행령 제47조 제1항 제5호",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약종합심사낙찰제심사기준"},
{id:"P3-141",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"균형가격 산정",ss:"3-4-3-1",tag:["법령","숫자"],difficulty:"상",question:"(계약예규) 공사계약 종합심사낙찰제 심사기준상 균형가격을 산정할 때 제외하는 입찰금액에 해당하지 않는 것은?",options:["입찰금액이 예정가격 이하이고 예정가격의 100분의 70 이상이며, 금액 불일치 등 다른 제외 사유가 없는 입찰","입찰서상의 금액과 산출내역서상의 금액이 일치하지 않는 입찰","입찰금액이 예정가격보다 높거나 예정가격의 100분의 70 미만인 입찰","입찰자의 산출내역서상 직접노무비가 발주기관 내역서상 직접노무비의 100분의 80 미만인 입찰"],answer:0,explanation:"균형가격은 입찰금액 점수를 매기는 기준 금액입니다. 금액 불일치, 예정가격 초과 또는 70% 미만, 직접노무비 80% 미만 등은 균형가격 계산에서 빼고, 이런 입찰자는 종합심사 점수를 산정하지 않고 낙찰자에서 배제합니다(제10조④). 예정가격 이하·70% 이상이면서 다른 제외 사유가 없는 입찰이 균형가격 계산에 들어갑니다.",basis:"(계약예규) 공사계약 종합심사낙찰제 심사기준 제8조 제1항, 제10조 제4항",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약종합심사낙찰제심사기준"},
// ─── 출제기준 보충 2차 (2026-09-27, 1개뿐인 항목에 +1) ───
{id:"P2-108",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"공급계획 수립 단계",ss:"2-1-1-3",tag:["공급계획","절차"],difficulty:"중",question:"공급업체의 공급계획 수립 절차(수요정보 수집 → 공급환경분석 → 내부공급역량 분석 → 적정성 분석 → 공급계획수립) 중 마지막 '공급계획수립' 단계에서 하는 일로 가장 적절한 것은?",options:["나라장터에서 중앙조달·자체조달 발주계획 정보와 공급실적 정보를 수집한다","조달대상물과 관련된 법령, 조달정책과 계약제도를 분석한다","앞 단계에서 조사·분석한 내용을 종합해 공급 대상 수요기관, 공급 시기, 공급 방법, 공급물량과 공급가격을 정하고 입찰·공급계획을 세운다","직접생산 요건과 공급망 안정성 등 공공조달 요구사항 충족도를 확인한다"],answer:2,explanation:"공급계획수립 단계는 앞 단계 결과를 모아 '어느 기관에, 언제, 어떤 방법(입찰·수의계약 등)으로, 얼마나, 얼마에' 공급할지 정하는 단계입니다. 발주계획 정보 수집은 수요정보 수집, 법령·정책 분석은 공급환경분석, 직접생산·공급망 확인은 내부공급역량 분석 단계의 일입니다."},
{id:"P2-109",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"납품 지연 대비",ss:"2-1-1-4",tag:["비상계획","리스크"],difficulty:"중",question:"공급 차질에 대비한 계획 중 '납품 지연' 위험을 줄이기 위한 방안으로 표준교재에 제시된 것이 아닌 것은?",options:["비상계획(Contingency plan) 수립","여유분(버퍼) 및 비상재고 유지","지연배상금 설정","선적 전 검사(Pre-shipment inspection)"],answer:3,explanation:"교재는 납품 지연에 대비해 지연배상금, 선제적 계약관리, 비상계획, 적정한 계획, 여유분(버퍼)·비상재고 유지를 제시합니다. 선적 전 검사는 '품질 불량' 위험을 줄이는 방안입니다."},
{id:"P2-110",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"내부 공급역량 분석",ss:"2-1-2-4",tag:["공급역량","기술적 적정성"],difficulty:"중",question:"공급업체가 입찰 전에 하는 내부 공급역량(기술적 적정성) 분석에 관한 설명으로 옳지 않은 것은?",options:["투입인력과 수행조직의 자격·인증, 수행 경험 보유 여부가 기술 역량의 주된 판단 요소가 된다","입찰에 필요한 인증서·자격은 입찰 마감일에만 유효하면 되므로 예상 계약 완료일까지의 유효기간은 확인할 필요가 없다","기술적 요건을 모두 충족하더라도 배점이 높고 평점 차가 큰 핵심 평가항목에서의 비교우위를 분석해야 한다","다른 수요기관의 같거나 비슷한 입찰 사례와 비교해 요구하는 기술 수준의 적정성을 검증한다"],answer:1,explanation:"자격·인증이 계약 체결 뒤 이행 완료까지 유효하지 않으면 정당한 계약목적물로 인정받지 못할 수 있어, 예상 계약 완료일까지 유효기간이 충분한지, 인력 이직·인증 만료 때 채용·갱신으로 채울 수 있는지까지 확인해야 합니다. 나머지는 교재가 제시한 중점 검토 내용입니다."},
{id:"P2-111",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"제조물품 비용 분석",ss:"2-1-3-1",tag:["비용분석","원가"],difficulty:"중",question:"공급업체가 공급 여부를 결정하기 위해 제조물품의 비용을 분석할 때 유의할 점으로 옳지 않은 것은?",options:["수주 가능성을 높이려면 일반관리비와 이윤율을 최대한 낮게 잡아 비용 적정성을 판단하는 것이 바람직하다","수입 원부자재·부품 비중이 높으면 환율 변동뿐 아니라 공급망 불안정에 따른 일정 차질·고가 구매 가능성도 고려한다","최저임금 인상 등으로 늘어나는 인건비를 반영한다","운송지역이 도서산간벽지여서 선박·항공기를 이용해야 하면 운송비가 늘어날 수 있음을 고려한다"],answer:0,explanation:"일반관리비와 이윤율을 지나치게 낮게 잡으면, 나중에 물가변동 조정 사유에 이를 만큼 가격이 오를 때 손실을 흡수할 여유가 없어집니다. 교재는 이 점을 충분히 검토하라고 합니다. 환율·공급망, 인건비, 도서산간 운송비는 모두 반영해야 할 요소입니다."},
{id:"P2-112",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"공공조달계획",sub:"데이터허브 수요 분석",ss:"2-1-4-1",tag:["수요예측","조달데이터허브"],difficulty:"중",question:"조달청 조달데이터허브의 '분석' 메뉴를 활용한 수요예측에 관한 설명으로 가장 적절한 것은?",options:["수요 분석은 물품·용역·공사 같은 조달대상물 수준에서만 가능하고 품명 단위로는 할 수 없다","자체조달기관을 선택하고 분석 기간을 3년 또는 5년으로 정하면 그 기관의 중장기 조달대상물별 수요 특성(패턴)을 분석할 수 있다","계약방법별 수요 특성은 조달청 중앙조달분만 제공되어 자체조달기관이 활용한 총액계약·다수공급자계약 등의 실적은 확인할 수 없다","정해진 메뉴 외에 공공조달 실적 원자료(Raw Data)를 내려받아 따로 분석하는 것은 허용되지 않는다"],answer:1,explanation:"분석 기간을 3년이나 5년으로 설정하면 기관의 중장기 수요 패턴을 볼 수 있습니다. 품명(8자리) 기준으로 중앙·자체·통합 수요 규모와 시기도 예측할 수 있고, 자체조달기관의 총액계약·다수공급자계약·제3자단가계약·일반단가계약 실적도 분석할 수 있으며, 원자료로 다양한 분석도 할 수 있습니다."},
{id:"P2-113",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"입찰참가자격 등록 효력",ss:"2-2-1-1",tag:["입찰참가자격","등록"],difficulty:"중",question:"「국가종합전자조달시스템 입찰참가자격등록규정」상 입찰참가자격 등록에 관한 설명으로 옳지 않은 것은?",options:["물품 등록자는 등록증에 등재된 세부품명 또는 품명, 품류의 입찰에 참가할 수 있다","용역은 등록증에 등재된 업종의 입찰에, 공사는 등재된 업종 또는 주력분야의 입찰에 참가할 수 있다","시스템에서 출력한 등록증은 계약담당공무원이 시스템을 통해 입찰참가자격을 확인할 수 있는 경우에 한해 등록증으로서 효력을 가진다","등록신청서를 제출하면 등록담당공무원의 확인 없이 제출한 때에 바로 등록의 효력이 생긴다"],answer:3,explanation:"등록의 효력은 등록담당공무원이 신청서와 구비서류를 검토해 등록확인을 해야 생깁니다(다른 기관에서 자동 연계되는 정보 등만 예외). 서류가 모자라 확인되지 않은 책임은 신청자에게 있습니다. 나머지는 규정 내용 그대로입니다.",basis:"국가종합전자조달시스템 입찰참가자격등록규정 제10조②, 제11조①, 제15조①",basisUrl:"https://www.law.go.kr/행정규칙/국가종합전자조달시스템입찰참가자격등록규정"},
{id:"P2-114",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"입법·행정예고 의견제출",ss:"2-2-1-3",tag:["입법예고","행정예고","행정절차법"],difficulty:"중",question:"「행정절차법」상 입법예고와 행정예고에 관한 설명으로 옳지 않은 것은?",options:["누구든지 예고된 입법안에 대하여 의견을 제출할 수 있다","행정청은 제출된 의견을 참고만 하면 되고, 의견을 제출한 자에게 처리결과를 알려 줄 의무는 없다","입법예고기간은 특별한 사정이 없으면 40일(자치법규는 20일) 이상으로 한다","행정예고기간은 20일 이상으로 하되, 긴급한 필요가 있으면 단축할 수 있고 이때에도 10일 이상으로 한다"],answer:1,explanation:"행정청은 제출된 의견을 특별한 사유가 없으면 존중해 처리해야 하고, 의견을 낸 사람에게 처리결과를 통지해야 합니다. 그래서 조달업체도 입법·행정예고를 찾아 의견을 내면 그 결과를 받아 볼 수 있습니다.",basis:"행정절차법 제43조, 제44조①③④, 제46조③④",basisUrl:"https://www.law.go.kr/법령/행정절차법/제44조"},
{id:"P2-115",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"입찰보증금 면제·지급각서",ss:"2-2-3-3",tag:["입찰보증금","면제"],difficulty:"중",question:"국가계약법 시행령상 입찰보증금에 관한 설명으로 옳은 것은?",options:["입찰보증금 납부를 면제받은 자는 국고귀속사유가 생기면 입찰보증금에 해당하는 금액을 내겠다고 확약하는 문서를 제출해야 한다","입찰보증금을 면제받은 낙찰자는 계약을 체결하지 않더라도 입찰보증금 상당액을 낼 의무가 없다","재난이나 경제위기로 재정경제부장관이 기간을 정해 고시한 경우에도 입찰보증금을 입찰금액의 100분의 5 미만으로 할 수 없다","보증서로 받은 입찰보증금에 국고귀속사유가 생기면 보증기관에 알리지 않고 보증서를 그대로 보관한다"],answer:0,explanation:"면제받은 자도 지급확약 문서를 내야 하고, 국고귀속사유가 생기면 그 문서를 근거로 입찰보증금 상당액을 현금으로 징수합니다. 경제위기 고시 기간에는 입찰금액의 1천분의 25 이상으로 낮출 수 있고, 보증서로 받았다면 지체 없이 보증기관 등에 통지해 현금으로 징수하거나 정부소유 유가증권으로 전환합니다.",basis:"국가계약법 시행령 제37조①④, 제38조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제37조"},
{id:"P2-116",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"조달요구 응대 및 제안",sub:"공사 현장설명 시기",ss:"2-2-4-1",tag:["현장설명","입찰설명회"],difficulty:"상",question:"국가계약법 시행령상 공사입찰의 현장설명에 관한 설명으로 옳은 것은?",options:["현장설명은 모든 공사입찰에서 반드시 실시해야 한다","추정가격 10억원 미만 공사의 현장설명은 입찰서 제출마감일 전일부터 기산하여 15일 전에 실시해야 한다","추정가격 50억원 이상 공사의 현장설명은 입찰서 제출마감일 전일부터 기산하여 33일 전에 실시해야 한다","현장설명을 실시하는 공사입찰은 현장설명일 전일부터 기산하여 40일 전에 공고해야 한다"],answer:2,explanation:"현장설명은 공사의 성질·규모를 고려해 '실시할 수 있는' 것이고, 입찰서 제출마감일 전일부터 기산해 10억원 미만 7일, 10억~50억원 미만 15일, 50억원 이상 33일 전에 실시해야 합니다. 현장설명을 하는 공사는 현장설명일 전일부터 7일 전(사전심사 공사는 30일 전)에 공고합니다.",basis:"국가계약법 시행령 제14조의2①③, 제35조②",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제14조의2"},
{id:"P2-117",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"평가위원 제척·회피 사유",ss:"2-3-2-2",tag:["이해충돌","제척","회피"],difficulty:"중",question:"「조달청 협상에 의한 계약 제안서평가 세부기준」상 평가위원이 스스로 평가를 회피해야 하는 제척·회피 사유에 해당하지 않는 것은?",options:["평가위원이 평가대상자로부터 전년도 1월 1일부터 현재까지 하도급을 포함해 용역·자문·연구 등을 수행한 경우","평가위원이 최근 3년 이내 해당 평가대상자 소속으로 재직한 경력이 있는 경우","평가위원 또는 소속단체가 해당 사업의 시행으로 이해당사자가 되는 경우","평가위원이 발주담당직원이 아닌 수요기관 소속 직원이라는 사실만 있는 경우"],answer:3,explanation:"세부기준은 사업 시행으로 이해당사자가 되는 경우를 제척·회피 사유로 두면서, 발주담당직원을 제외한 수요기관 소속 직원은 여기에 해당하지 않는다고 명시합니다. 사유에 해당하는 위원은 즉시 위원장과 평가집행자에게 알리고 스스로 평가를 회피해야 합니다.",basis:"조달청 협상에 의한 계약 제안서평가 세부기준 제5조②",basisUrl:"https://www.law.go.kr/행정규칙/조달청협상에의한계약제안서평가세부기준"},
{id:"P2-118",exam:"필기",subject:"공공조달계획 수립 및 분석",major:"입찰·제안평가 및 계약체결",sub:"가격협상 기준가격",ss:"2-3-3-3",tag:["가격협상","협상계약"],difficulty:"중",question:"「협상에 의한 계약체결기준」상 가격협상에 관한 설명으로 옳은 것은?",options:["가격협상의 기준가격은 해당 사업예산(예정가격을 작성한 경우에는 예정가격) 이하로서 협상대상자가 제안한 가격으로 한다","가격협상의 기준가격은 협상대상자의 제안가격과 관계없이 해당 사업예산 전액으로 한다","가격협상을 위해 예정가격을 작성할 때에는 입찰에 참가한 자들의 제안가격을 기준으로 작성한다","계약담당공무원은 가격을 깎아 주는 대가로 해당 사업과 무관한 요구사항을 협상대상자에게 추가할 수 있다"],answer:0,explanation:"기준가격은 사업예산(또는 예정가격) 이하인 협상대상자의 제안가격입니다. 예정가격은 제안서 제출 전까지 시행령 제9조에 따라 작성해야 하고, 참가자의 제안가격을 기준으로 작성하면 안 됩니다. 사업과 무관한 요구사항 추가나 기술이전 요구 같은 불공정한 요구도 금지됩니다.",basis:"(계약예규) 협상에 의한 계약체결기준 제11조, 제12조①③",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)협상에의한계약체결기준"},
{id:"P3-142",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"용역 착수신고서 변경·조정",ss:"3-1-1-3",tag:["계약","용역"],difficulty:"중",question:"(계약예규) 용역계약일반조건상 용역의 착수 및 보고에 관한 설명으로 옳지 않은 것은?",options:["계약담당공무원은 제출된 착수신고서 서류의 내용을 조정할 필요가 있다고 인정하면 계약상대자에게 조정을 요구할 수 있다","착수신고서를 한 번 제출한 뒤에는 과업내용이 바뀌더라도 이미 낸 서류를 변경하여 제출할 필요가 없다","용역 진행이 지연되어 기간 내 수행이 불가능하다고 인정되면 계약담당공무원은 주간공정현황을 제출하게 하는 등 필요한 조치를 할 수 있다","계약상대자는 계약문서에서 정하는 바에 따라 용역을 착수하여야 한다"],answer:1,explanation:"과업내용 변경 등으로 착수 때 낸 서류(공정예정표, 인력·장비투입계획서 등)를 바꿔야 하면 계약상대자는 변경해서 다시 내야 합니다(제13조②). 발주기관의 조정 요구(③)와 지연 시 주간공정현황 요구(④)는 모두 조문 내용 그대로입니다.",basis:"(계약예규) 용역계약일반조건 제13조①~④",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)용역계약일반조건"},
{id:"P3-143",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"착공일 결정·공정보고",ss:"3-1-1-4",tag:["계약","공사","숫자"],difficulty:"중",question:"(계약예규) 공사계약일반조건상 착공 및 공정보고에 관한 설명으로 옳은 것은? (재해복구 등 긴급공사나 장기계속공사 연차계약은 아님)",options:["추정가격 10억원 미만 공사는 계약체결일 다음 날을 착공일로 정해야 한다","착공신고서를 제출한 공사의 월별 공정 현황은 공사가 끝난 뒤 한꺼번에 제출한다","추정가격 15억원인 공사는 계약체결일로부터 20일 이전의 날짜로 착공일을 정해서는 안 된다","공정이 지체되어 기한 내 준공이 어렵더라도 월별 현황 외에 추가 조치를 지시할 수는 없다"],answer:2,explanation:"착공일은 추정가격 10억원 미만이면 계약체결일로부터 10일, 10억원 이상이면 20일 이전의 날짜로 정할 수 없습니다(제17조②). 월별 공정율·수행공사금액 등은 다음 달 14일까지 제출하게 할 수 있고(⑤), 공정이 지체되면 주간공정현황 제출 등 필요한 조치를 지시할 수 있습니다(⑥).",basis:"(계약예규) 공사계약일반조건 제17조②⑤⑥",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-144",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"하도급 변경 통보·감독자 검토",ss:"3-1-1-5",tag:["하도급","공사"],difficulty:"중",question:"공공 건설공사의 하도급 승인 및 변경 절차에 관한 설명으로 옳지 않은 것은?",options:["하도급계약을 변경하거나 해제한 때에도 그날부터 30일 이내에 발주자에게 통보해야 한다","하도급계약을 변경한 경우에는 최초 체결 때 통보했으므로 다시 통보할 필요가 없다","공사감독자는 하도급 통지나 승낙 요청 사항의 적정성을 검토해 요청받은 날부터 7일 이내에 의견을 발주청에 제출해야 한다","계약담당공무원은 하도급계약을 통보받으면 건설공사하도급심사기준에 따라 하도급금액의 적정성을 심사해야 한다"],answer:1,explanation:"하도급 통보는 체결(또는 재하도급 승낙)한 날부터 30일 이내에 해야 하고, 하도급계약을 변경·해제한 때에도 같습니다(건설산업기본법 시행령 제32조①). 공사감독자의 7일 이내 의견 제출은 사업관리 업무수행지침 제129조①, 하도급금액 적정성 심사는 공사계약일반조건 제42조②의 내용입니다.",basis:"건설산업기본법 시행령 제32조①",basisUrl:"https://www.law.go.kr/법령/건설산업기본법시행령/제32조"},
{id:"P3-145",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"변경계약 처리 절차",ss:"3-1-2-1",tag:["변경"],difficulty:"중",question:"일반적인 변경계약 처리 절차에 관한 설명으로 옳지 않은 것은?",options:["먼저 변경계약이 가능한지 판단한 뒤 발주담당자와 계약상대자가 합의각서를 작성한다","계약금액이나 계약기간이 바뀌면 계약보증서·선금보증서·인지세 등의 추가 징구 여부를 확인한다","계약담당자가 나라장터로 변경계약서 초안을 보내면 계약업체는 이를 확인하고 응답서를 제출한다","변경계약은 기존 계약을 고치는 것이므로 합의각서 없이 발주기관이 일방적으로 변경계약서를 확정해 통보한다"],answer:3,explanation:"변경계약은 가능 여부 판단 → 합의각서 작성 → 변경계약 의뢰 → 나라장터 초안 송신 → 보증서·인지세 제출과 응답서 제출 → 체결 순으로 진행합니다. 계약은 당사자 합의로 이루어지므로 발주기관이 일방적으로 확정하지 않습니다."},
{id:"P3-146",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"공사계약 분쟁 해결",ss:"3-1-2-5",tag:["분쟁","공사"],difficulty:"중",question:"(계약예규) 공사계약일반조건상 분쟁의 해결에 관한 설명으로 옳지 않은 것은?",options:["계약 수행 중 계약당사자 사이에 생긴 분쟁은 먼저 협의로 해결한다","협의가 이루어지지 않으면 법원의 판결 또는 「중재법」에 따른 중재로 해결한다","분쟁처리 절차가 진행되는 동안에는 계약상대자가 공사 수행을 중지할 수 있다","계약을 체결할 때 국가계약법 제28조의2에 따라 분쟁해결방법을 정했다면 그에 따른다"],answer:2,explanation:"계약상대자는 분쟁처리 절차를 수행하는 기간에도 공사 수행을 중지해서는 안 됩니다(제51조④). 협의 → 판결 또는 중재(①②), 계약 때 정한 분쟁해결방법 우선(③)은 조문 그대로입니다. 국가계약법 제28조의2는 분쟁해결방법으로 국가계약분쟁조정위원회 조정과 중재 중 하나를 합의로 정하게 합니다.",basis:"(계약예규) 공사계약일반조건 제51조, 국가계약법 제28조의2",basisUrl:"https://www.law.go.kr/행정규칙/(계약예규)공사계약일반조건"},
{id:"P3-147",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"공급 일반절차 순서",ss:"3-1-3-1",tag:["계약","절차"],difficulty:"하",question:"계약(조달) 대상물 공급 일반절차를 \"수요의 제기 → 구매 계획 → ( ) → 공급자 발굴 → 공급자 선정 → 계약 체결 → 계약 관리\"로 나타낼 때 ( )에 들어갈 단계는?",options:["계약 관리","공급자 선정","수요의 상세화","대금 지급"],answer:2,explanation:"구매 계획 뒤에 구매부서가 수요부서와 협의해 구체적인 규격·물량·소요시기를 정하는 '수요의 상세화'를 거친 다음 공급자를 발굴합니다."},
{id:"P3-148",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"계약이행실태 점검",ss:"3-1-3-2",tag:["계약","점검"],difficulty:"중",question:"교재에 소개된 조달청 급식류 다수공급자계약 추가특수조건의 계약이행실태 점검 사례에 관한 설명으로 옳지 않은 것은?",options:["계약담당공무원 등은 필요하면 계약상대자에게 자료 제출을 요구할 수 있다","계약상대자의 사업장·공장 등을 방문해 시설·서류·생산제품을 불시에 점검할 수도 있다","계약상대자가 점검에 응하지 않으면 종합쇼핑몰 거래를 정지할 수 있다","점검은 계약상대자에게 미리 알린 정기 점검 일정에만 할 수 있다"],answer:3,explanation:"점검은 수시 또는 불시에 할 수 있고 계약상대자는 이에 협조해야 합니다(추가특수조건 제13조①). 점검에 응하지 않으면 종합쇼핑몰 거래정지를 할 수 있습니다(같은 조 ⑥)."},
{id:"P3-149",exam:"필기",subject:"공공계약관리",major:"계약관리 일반 절차",sub:"구매 위험관리",ss:"3-1-3-5",tag:["리스크"],difficulty:"중",question:"구매 운영에서의 위험관리에 관한 설명으로 옳지 않은 것은?",options:["위험의 정도를 측정·분석하는 요소로 위험발생확률, 지속기간, 영향도를 들 수 있다","외부의 어떤 충격에도 자재 공급이 중단되지 않고 지속되도록 하는 방안을 SCP(Supply Continuity Planning)라 한다","위험 공유란 위험을 혼자 극복하려 하지 않고 다른 사람이나 조직과 나누어 대처하는 방법이다","위험이 생긴 뒤 사후적으로 대비하는 것이 미리 예방하는 것보다 훨씬 효과적이다"],answer:3,explanation:"가능하다면 위험이 생기지 않도록 예방하는 것이 발생 후 사후 대비보다 훨씬 효과적입니다. 나머지는 위험 측정 3요소, 공급연속성계획(SCP), 위험 공유의 뜻을 바르게 설명한 것입니다."},
{id:"P3-150",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 입찰공고서 검토",ss:"3-2-1-2",tag:["물품","공고"],difficulty:"중",question:"물품구매 입찰공고서를 작성·검토할 때의 설명으로 옳지 않은 것은?",options:["입찰참가자격을 판단하는 기준일을 명시한다","중소기업자간 경쟁제품이면 직접생산 확인증명서를 중소기업 공공구매 종합정보망 등록 자료로 확인한다는 점을 명시한다","입찰 관련 비리 또는 불공정행위의 신고에 관한 사항을 명시한다","조세포탈 등으로 유죄판결이 확정된 날부터 5년이 지나지 않은 자는 입찰에 참가할 수 없다고 명시한다"],answer:3,explanation:"조세포탈 등을 한 자의 입찰참가 제한 기간은 유죄판결 확정일부터 2년입니다(국가계약법 제27조의5①). 비리·불공정행위 신고 사항은 시행령 제36조 제15호의2의 공고 명시사항이고, 자격 판단 기준일과 직접생산 확인 방법 명시는 교재의 공고서 작성 절차입니다.",basis:"국가계약법 제27조의5①, 같은 법 시행령 제36조 제15호의2",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률/제27조의5"},
{id:"P3-151",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"수의계약 견적서",ss:"3-2-1-4",tag:["물품","수의계약"],difficulty:"중",question:"국가계약법 시행령상 수의계약의 견적서 제출에 관한 설명으로 옳지 않은 것은?",options:["수의계약을 체결하려면 원칙적으로 2인 이상으로부터 견적서를 받아야 한다","추정가격 2천만원을 넘는 소액수의계약(시행령 제26조제1항제5호가목)은 원칙적으로 전자조달시스템으로 견적서를 받고, 그 제출 사항을 전자조달시스템에 안내공고해야 한다","견적가격이 예정가격의 범위에 들지 않아 계약상대자를 정할 수 없으면 다시 견적서를 받아 계약금액을 정해야 한다","전자조달시스템으로 견적서를 받는 수의계약에서 견적서 제출자를 법인등기부상 본점소재지로 제한하는 것은 어떤 경우에도 허용되지 않는다"],answer:3,explanation:"계약이행의 용이성·효율성 등을 고려해 필요하면 견적서 제출자를 본점소재지 기준으로 제한할 수 있고, 이때 안내공고에 제한사항과 기준을 적어야 합니다(제30조④). 2인 이상 견적 원칙(①), 전자조달 견적과 안내공고(②③), 재견적(⑥)은 조문 그대로입니다.",basis:"국가계약법 시행령 제30조①~④·⑥",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제30조"},
{id:"P3-152",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"외자구매 특징",ss:"3-2-1-5",tag:["물품","외자"],difficulty:"상",question:"조달청 외자구매계약의 특징에 관한 설명으로 옳지 않은 것은?",options:["외자 계약상대자는 입찰자와 공급자를 모두 뜻하며, 둘은 계약 이행에 연대책임을 진다","같은 공급자 1인을 둔 입찰자가 여러 명이면 1인 1입찰 원칙에 어긋나므로 그 입찰은 모두 무효이다","불가피한 경우 통화, 보증금 납부 형태와 시기, 신용장에 근거한 대가지급, 검수 등에 국제상관례를 따를 수 있다","오랜 해상(항공) 운송 중 생길 수 있는 책임에 대비해 적하보험에 가입할 수 있다"],answer:1,explanation:"공급자는 입찰자가 아니므로, 공급자가 1인이고 같은 공급자를 둔 입찰자가 여럿이어도 1인 1입찰 원칙에 어긋나지 않아 입찰이 무효가 되지 않습니다. 연대책임, 국제상관례 적용, 적하보험 가입은 외자구매의 특징입니다."},
{id:"P3-153",exam:"필기",subject:"공공계약관리",major:"물품 계약관리",sub:"물품 계약금액 조정",ss:"3-2-2-2",tag:["물품","변경"],difficulty:"중",question:"물품 제조·구매계약의 계약금액 조정에 관한 설명으로 옳지 않은 것은?",options:["물가변동으로 계약금액을 늘릴 때에는 계약상대자의 청구가 있어야 하고, 완납대가를 받기 전까지 조정신청을 해야 조정금액을 받을 수 있다","발주기관은 물가변동 증액 청구를 받은 날부터 20일 이내에 계약금액을 조정해야 한다","같은 계약의 물가변동 조정에 품목조정률과 지수조정률을 동시에 적용해서는 안 된다","국가계약법 시행령의 설계변경으로 인한 계약금액 조정 규정(제65조)은 공사에만 적용되며 제조계약에는 준용할 수 없다"],answer:3,explanation:"시행령 제65조 제1항~제6항은 제조·용역 등의 계약에서 계약금액을 조정할 때 준용할 수 있습니다(제65조⑦). 나머지는 물품구매(제조)계약일반조건 제11조②③⑤의 내용입니다.",basis:"국가계약법 시행령 제65조⑦, (계약예규) 물품구매(제조)계약일반조건 제11조",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제65조"},
{id:"P3-154",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"협상계약 용역 공고 시기",ss:"3-3-1-1",tag:["용역","공고","숫자"],difficulty:"중",question:"협상에 의한 계약으로 발주하는 용역의 입찰공고문을 검토할 때, 공고 시기로 옳은 것은? (재공고·긴급 등 단축 사유는 없음)",options:["제안서 제출마감일의 전날부터 기산하여 40일 전에 공고하되, 추정가격이 고시금액 미만이면 10일 전까지 공고할 수 있다","입찰서 제출마감일의 전일부터 기산하여 7일 전에 공고하면 된다","추정가격과 관계없이 언제나 제안서 제출마감일 전날부터 기산하여 40일 전에 공고해야 한다","제안서 제출마감일 전날부터 기산하여 5일 전까지 공고하면 된다"],answer:0,explanation:"협상에 의한 계약과 경쟁적 대화에 의한 계약은 제안서 제출마감일 전날부터 40일 전에 공고하는 것이 원칙이고, 추정가격이 고시금액 미만이거나 제35조④ 각 호의 사유가 있으면 10일 전까지 공고할 수 있습니다(시행령 제35조⑤). 7일은 일반 입찰공고 기준입니다.",basis:"국가계약법 시행령 제35조⑤",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제35조"},
{id:"P3-155",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"경쟁적 대화",ss:"3-3-1-5",tag:["용역","경쟁적대화"],difficulty:"중",question:"국가계약법 시행령상 경쟁적 대화에 의한 계약에 관한 설명으로 옳지 않은 것은?",options:["입찰공고를 할 때 경쟁적 대화에 의한 계약이라는 뜻을 명시해야 한다","경쟁적 대화를 하기 전에 입찰대상자의 제안 내용 등을 심사해 대화에 참여할 입찰대상자를 선정해야 한다","예정가격을 작성한 경우에는 예정가격 이하로 계약을 체결해야 한다","대화에 참여하고 제안서를 냈지만 낙찰자로 선정되지 않은 참여자에게는 어떤 경우에도 참여비용을 지급할 수 없다"],answer:3,explanation:"낙찰자로 선정되지 않은 참여자에게도 예산의 범위에서 경쟁적 대화 참여비용의 전부 또는 일부를 지급할 수 있습니다(제43조의3⑤). 공고 시 명시(②), 대화 전 참여자 선정(③), 예정가격 이하 체결(① 후단)은 조문 그대로입니다.",basis:"국가계약법 시행령 제43조의3①②③⑤",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제43조의3"},
{id:"P3-156",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"구 e-발주시스템",ss:"3-3-1-7",tag:["용역","전자조달"],difficulty:"하",question:"용역 제안서 제출·평가에 쓰이던 '구 e-발주시스템'에 관한 설명으로 옳은 것은?",options:["차세대 나라장터와 별도로 운영되는 민간 시스템으로, 업체가 수수료를 내고 이용한다","차세대 나라장터의 내부 기능으로 통합되어, 제안업체가 나라장터의 제안서 제출 기능으로 온라인 제출·제안발표를 할 수 있다","제안서는 이 시스템을 쓰지 않고 반드시 종이 문서로 우편 제출해야 한다","물품 대금 청구와 지급만 처리하는 재정 시스템이다"],answer:1,explanation:"구 e-발주시스템은 차세대 나라장터의 내부 기능으로 통합되었고, 협상에 의한 계약의 제안서 제출과 온라인 제안발표·평가에 활용됩니다."},
{id:"P3-157",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"종합쇼핑몰 MAS와 총액계약 비교",ss:"3-3-2-1",tag:["MAS","종합쇼핑몰"],difficulty:"중",question:"나라장터 종합쇼핑몰을 통한 다수공급자계약(MAS) 구매를 단일계약(총액계약)과 비교한 설명으로 옳지 않은 것은?",options:["MAS의 계약상대자는 2인 이상이다","MAS는 수요기관이 종합쇼핑몰에서 직접 비교·선택해 구매하는 수요자 중심 방식이다","MAS는 일정금액 이상이면 수요기관이 대상업체와 평가방법을 선택해 경쟁을 거친 뒤 납품요구를 한다","MAS는 계약을 체결한 뒤에는 공급자 사이에 경쟁이 없다"],answer:3,explanation:"MAS는 계약 체결 후에도 수요기관의 납품요구 단계에서 공급자 간 경쟁(2단계경쟁 등)이 있는 것이 특징입니다. 계약 후 경쟁이 없는 것은 단일계약(총액계약)입니다."},
{id:"P3-158",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"MAS 사전심사",ss:"3-3-2-3",tag:["MAS"],difficulty:"상",question:"물품 다수공급자계약 업무처리규정상 입찰참가자격 사전심사에 관한 설명으로 옳은 것은?",options:["사전심사는 결격사유 유무만 확인하며 항목별 점수는 매기지 않는다","체육시설탄성포장재 등 규정에 열거된 세부품명은 적격성 평가를 대신해 사전심사로 다수공급자계약 적격자를 선정할 수 있다","결격사유가 없고 종합평점이 60점 이상이면 적격자로 선정할 수 있다","적격자로 선정되지 못한 자는 신청서를 보완하더라도 다시 제출할 수 없다"],answer:1,explanation:"제9조에 열거된 14개 세부품명 등은 적격성 평가 대신 사전심사를 합니다. 사전심사는 납품실적·기술능력·경영상태·품질관리·사후관리·신인도를 점수로 심사하고(제11조①), 종합평점 70점 이상(최초 공고 품명의 최초 계약자는 65점 이상)이면 적격자로 선정할 수 있습니다(제12조①). 탈락자는 결과 통지 후 60일 이후 보완해 다시 낼 수 있습니다(제12조③).",basis:"물품 다수공급자계약 업무처리규정 제9조·제11조①·제12조①③",basisUrl:"https://www.law.go.kr/행정규칙/물품다수공급자계약업무처리규정"},
{id:"P3-159",exam:"필기",subject:"공공계약관리",major:"용역·다수공급자 계약 관리",sub:"MAS 이행실적평가 대상·항목",ss:"3-3-2-5",tag:["MAS"],difficulty:"중",question:"물품 다수공급자계약 업무처리규정상 계약이행실적평가에 관한 설명으로 옳지 않은 것은?",options:["평가담당공무원은 반기별로 종결된 납품실적이 있는 계약상대자를 평가할 수 있다","평가항목은 납기, 품질, 수요기관 만족도, 계약관리, 계약이행성실도로 구분한다","수요기관 만족도 지표는 해당 품목을 납품받은 수요기관의 장이 나라장터에 접속해 평가하도록 한다","계약상대자가 조합이면 조합이 아니라 조합원사별로 각각 평가해야 한다"],answer:3,explanation:"계약상대자가 조합인 경우에는 해당 조합을 기준으로 평가합니다(제42조②). 반기별 평가(제42조①), 5개 평가항목(제43조①), 수요기관의 장이 직접 평가하는 만족도 지표(제43조③)는 조문 그대로입니다.",basis:"물품 다수공급자계약 업무처리규정 제42조·제43조",basisUrl:"https://www.law.go.kr/행정규칙/물품다수공급자계약업무처리규정"},
{id:"P3-160",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"공사 입찰공고 시기",ss:"3-4-2-1",tag:["공사","공고","숫자"],difficulty:"중",question:"현장설명을 실시하지 않는 추정가격 20억원 공사의 입찰공고 시기로 옳은 것은? (재공고·긴급 등 단축 사유는 없음)",options:["입찰서 제출마감일의 전일부터 기산하여 7일 전","입찰서 제출마감일의 전일부터 기산하여 15일 전","입찰서 제출마감일의 전일부터 기산하여 40일 전","입찰서 제출마감일의 전일부터 기산하여 5일 전"],answer:1,explanation:"현장설명을 하지 않는 공사는 추정가격 10억원 미만 7일, 10억원 이상 50억원 미만 15일, 50억원 이상 40일 전에 공고합니다(시행령 제35조③). 5일은 재공고입찰·긴급 등 단축 사유가 있을 때 기준입니다(④).",basis:"국가계약법 시행령 제35조③",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제35조"},
{id:"P3-161",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"PQ 절차·심사기준",ss:"3-4-2-3",tag:["공사","PQ"],difficulty:"중",question:"국가계약법 시행령상 입찰참가자격 사전심사(PQ)에 관한 설명으로 옳지 않은 것은?",options:["발주기관은 입찰참가자의 자격을 미리 심사해 적격자를 선정할 수 있고, 선정했으면 그 결과를 적격자에게 통지해야 한다","심사기준은 계약이행의 난이도, 이행실적, 기술능력, 재무상태, 사회적 신인도, 계약이행의 성실도 등을 종합적으로 고려해 정한다","PQ를 하려는 공사입찰은 현장설명일 전일부터 기산하여 30일 전에 공고해야 한다","심사기준은 공정성을 위해 입찰이 끝난 뒤에 공개하며, 입찰 전에는 열람하게 할 수 없다"],answer:3,explanation:"발주기관은 심사기준과 증명서류 작성·제출방법 등을 적은 서류를 갖추어 입찰 전에 열람할 수 있게 하고, 요청하면 열람·교부해야 합니다(제13조④, 전자조달시스템 게재로 갈음 가능). 적격자 선정은 '할 수 있다'는 재량 규정입니다(제13조①).",basis:"국가계약법 시행령 제13조①②④, 제35조②",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제13조"},
{id:"P3-162",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"정부 요구 설계변경 단가",ss:"3-4-2-5",tag:["공사","변경","계산"],difficulty:"상",question:"발주기관이 설계변경을 요구하여 신규비목이 생긴 공사계약에서 설계변경 당시를 기준으로 산정한 단가는 10,000원, 낙찰률은 80%이다. 계약당사자 간 협의가 이루어지지 않은 경우 적용할 신규비목 단가는?",options:["8,000원","9,000원","10,000원","18,000원"],answer:1,explanation:"정부가 설계변경을 요구한 경우 증가 물량이나 신규비목 단가는 설계변경 당시 단가(10,000원)와 그 단가에 낙찰률을 곱한 금액(8,000원)의 범위에서 협의로 정하고, 협의가 안 되면 둘을 합한 금액의 50%인 9,000원으로 합니다(제65조③3). 8,000원은 계약상대자 요청 등 일반적인 신규비목 단가(설계변경 당시 단가 × 낙찰률) 방식입니다.",basis:"국가계약법 시행령 제65조③3",basisUrl:"https://www.law.go.kr/법령/국가를당사자로하는계약에관한법률시행령/제65조"},
{id:"P3-163",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"건설엔지니어링 SOQ",ss:"3-4-3-4",tag:["용역","공사"],difficulty:"상",question:"건설엔지니어링(기술용역) 사업자 선정의 적격심사 방식 중, 가장 낮은 가격을 낸 자부터 가격점수·사업수행능력 점수에 참여 기술인 평가 점수를 합산하되 참여 기술인 평가에 책임기술자의 면접점수가 포함되는 방식은?",options:["사업수행능력평가(PQ+가격)","기술제안서 평가(TP)","기술인 평가(SOQ)","종합심사낙찰제"],answer:2,explanation:"SOQ(Statement of Qualification)는 참여 기술인의 경력·역량과 수행계획을 평가하며 책임기술자 면접점수가 들어갑니다. TP(기술제안서 평가)는 책임기술자의 발표 점수가 들어가고, PQ+가격은 참여기술인·수행실적·신인도 등 사업수행능력과 가격만 봅니다."},
{id:"P3-164",exam:"필기",subject:"공공계약관리",major:"공사계약관리",sub:"전자적 대금지급 시스템 기능",ss:"3-4-3-6",tag:["하도급","전자조달"],difficulty:"중",question:"「전자조달의 이용 및 촉진에 관한 법률 시행령」상 하도급지킴이와 같은 하도급 관리 전자조달시스템등에 관한 설명으로 옳지 않은 것은?",options:["계약체결자가 하수급인·노무자·자재·장비업자에게 지급할 금액의 청구·승인·지급 기능을 갖춰야 한다","하수급인이 노무자·자재·장비업자에게 지급할 금액의 청구·승인·지급 기능도 갖춰야 한다","수요기관의 장이나 계약담당자가 청구·승인·지급을 실시간으로 확인할 수 있는 기능을 갖춰야 한다","대금 지급용 전용계좌는 계약체결자만 개설·등록하면 되고 하수급인은 등록할 필요가 없다"],answer:3,explanation:"계약체결자와 하수급인 모두 대금 지급을 위한 전용계좌를 개설해 전자조달시스템등에 등록해야 합니다(제7조③). 나머지는 시스템이 갖춰야 할 기능(제7조② 제1호·제2호)입니다.",basis:"전자조달의 이용 및 촉진에 관한 법률 시행령 제7조②③",basisUrl:"https://www.law.go.kr/법령/전자조달의이용및촉진에관한법률시행령/제7조"}
];
